-- Переводы отзывов Google и ответов владельцев (scripts/reviews/review-translations.mjs).
-- COALESCE: уже переведённое не перезаписывается; повторное применение безопасно.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све је на нивоу, све похвале за Филипа!!'), text_en = COALESCE(text_en, 'Everything is top-notch, all praise to Filip!!'), text_ru = COALESCE(text_ru, 'Всё на уровне, все похвалы Филипу!!'), text_de = COALESCE(text_de, 'Alles auf hohem Niveau, großes Lob an Filip!!'), text_tr = COALESCE(text_tr, 'Her şey çok iyi, Filip\'e tüm övgüler!!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT20xTGNHTjViSEZKU1MwMGJIazRTVU16TmxWaVozYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Најнељубазније особље које једна приватна клиника може имати.'), text_en = COALESCE(text_en, 'The rudest staff a private clinic could possibly have.'), text_ru = COALESCE(text_ru, 'Самый неприветливый персонал, какой только может быть в частной клинике.'), text_de = COALESCE(text_de, 'Das unfreundlichste Personal, das eine Privatklinik nur haben kann.'), text_tr = COALESCE(text_tr, 'Bir özel kliniğin sahip olabileceği en kaba personel.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT21scldHeGpaMHBzUzJsNFUyeDVXbk5ZTVhGaU5VRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Odlična klinika, cijela moja porodica ide ovdje već 6 godina. Nikada nismo imali nikakvih problema.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Одлична клиника, цијела моја породица иде овдје већ 6 година. Никада нисмо имали никаквих проблема.'), text_ru = COALESCE(text_ru, 'Отличная клиника, вся моя семья ходит сюда уже 6 лет. У нас никогда не было никаких проблем.'), text_de = COALESCE(text_de, 'Tolle Klinik, meine ganze Familie geht seit 6 Jahren hierher. Wir hatten nie Probleme.'), text_tr = COALESCE(text_tr, 'Harika bir klinik, tüm ailem 6 yıldır buraya geliyor. Hiçbir zaman sorun yaşamadık.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT25BME9XbHRjRVpVYUVKd1RXWnJNVWhwUjBGTVYzYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Желим да похвалим техничаре Филипа Медвидовића и Владимира Медвидовића, као и лаборанта Дуњу Божовић. Изузетно љубазни, професионални, сусретљиви и пажљиви према пацијентима. Све похвале за њих!'), text_en = COALESCE(text_en, 'I want to praise the technicians Filip Medvidović and Vladimir Medvidović, as well as the lab assistant Dunja Božović. Extremely kind, professional, accommodating and attentive to patients. All praise to them!'), text_ru = COALESCE(text_ru, 'Хочу похвалить техников Филипа Медвидовича и Владимира Медвидовича, а также лаборанта Дуню Божович. Исключительно вежливые, профессиональные, отзывчивые и внимательные к пациентам. Им все похвалы!'), text_de = COALESCE(text_de, 'Ich möchte die Techniker Filip Medvidović und Vladimir Medvidović sowie die Laborantin Dunja Božović loben. Äußerst freundlich, professionell, entgegenkommend und aufmerksam gegenüber den Patienten. Großes Lob an sie!'), text_tr = COALESCE(text_tr, 'Teknisyenler Filip Medvidović ve Vladimir Medvidović\'i, ayrıca laborant Dunja Božović\'i övmek istiyorum. Son derece nazik, profesyonel, yardımsever ve hastalara karşı özenliler. Hepsine tüm övgüler!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xaVFFVMW1Oa2xMVGpReVZHWjFlR3hqWm5GQ2FWRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Цијела моја породица долази овдје годинама. Најбољи!'), text_en = COALESCE(text_en, 'My whole family has been coming here for years. The best!'), text_ru = COALESCE(text_ru, 'Вся моя семья ходит сюда уже много лет. Лучшие!'), text_de = COALESCE(text_de, 'Meine ganze Familie kommt seit Jahren hierher. Die Besten!'), text_tr = COALESCE(text_tr, 'Tüm ailem yıllardır buraya geliyor. En iyisi!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT25aZmFUQlBTWGRmYkd0MWExQjBWa05ETFVabWFFRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Slušajte, odličan medicinski servis – ova klinika. Bili smo na odmoru, skočio mi je pritisak, hitne pomoći u Podgorici nema, pa sam svratio u njihovu kliniku. Brzo su mi izmjerili pritisak, a kardiolog je, sudeći po pitanjima koja je postavljao, veoma iskusan. Brzo mi je prepisao dvije infuzije, a zatim i privremenu terapiju, ali je insistirao da uradim analize! Činjenica je da su bez ikakvih pitanja primili državljanina druge zemlje! Ocjena 5!'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Слушајте, одличан медицински сервис – ова клиника. Били смо на одмору, скочио ми је притисак, хитне помоћи у Подгорици нема, па сам свратио у њихову клинику. Брзо су ми измјерили притисак, а кардиолог је, судећи по питањима која је постављао, веома искусан. Брзо ми је преписао двије инфузије, а затим и привремену терапију, али је инсистирао да урадим анализе! Чињеница је да су без икаквих питања примили држављанина друге земље! Оцјена 5!'), text_en = COALESCE(text_en, 'Listen, an excellent medical service – this clinic. We were on holiday, my blood pressure spiked, there\'s no ambulance in Podgorica, so I went to their clinic. They quickly measured my blood pressure, and judging by the quality of his questions, the cardiologist is very experienced. He quickly prescribed two IV drips and then temporary medication, but insisted that I get tests done! And the fact is they took in a citizen of another country without any questions! 5 stars!'), text_de = COALESCE(text_de, 'Hört mal, ein ausgezeichneter medizinischer Service – diese Klinik. Wir waren im Urlaub, mein Blutdruck ist gestiegen, in Podgorica gibt es keinen Rettungsdienst, also bin ich in ihre Klinik gegangen. Man hat schnell meinen Blutdruck gemessen, und der Kardiologe ist, nach der Qualität seiner Fragen zu urteilen, sehr erfahren. Er hat mir schnell zwei Infusionen verordnet und dann vorübergehend Medikamente verschrieben, bestand aber darauf, dass ich Laboruntersuchungen machen lasse! Fakt ist: Man hat einen Bürger eines anderen Landes ohne Fragen aufgenommen! 5 Punkte!'), text_tr = COALESCE(text_tr, 'Dinleyin, mükemmel bir sağlık hizmeti – bu klinik. Tatildeydik, tansiyonum yükseldi, Podgorica\'da ambulans yok, ben de kliniklerine gittim. Tansiyonumu hızlıca ölçtüler; kardiyolog, sorduğu soruların kalitesine bakılırsa çok deneyimli. Bana hızlıca iki serum yazdı, ardından geçici ilaçlar verdi, ama tahlil yaptırmamı şart koştu! İşin özü, başka bir ülkenin vatandaşını hiç soru sormadan kabul ettiler! 5 puan!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tGcFVVMUpha2xKUkhScU5EZGFZV2xCZUVOQ2IyYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Jedno od najboljih osoblja i ljekara – pružiće vam veoma dobru uslugu već od recepcije, a ljekari su najbolji❤️'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Једно од најбољих особља и љекара – пружиће вам веома добру услугу већ од рецепције, а љекари су најбољи❤️'), text_ru = COALESCE(text_ru, 'Один из лучших коллективов и врачей – вас очень хорошо обслужат уже на ресепшене, а врачи лучшие❤️'), text_de = COALESCE(text_de, 'Eines der besten Teams und Ärzte – man wird schon am Empfang sehr gut betreut, und die Ärzte sind die besten❤️'), text_tr = COALESCE(text_tr, 'En iyi personel ve doktorlardan biri – daha resepsiyondan itibaren çok iyi hizmet alırsınız, doktorlar da en iyileri❤️') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT25sYWFtaENlV2hWZFdWNVJ6bDRhVTkzUVV3Mk1XYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Пацијент сам клинике Milmedika већ 16–17 година, а током свих тих година њихову бригу и стручност упознала је и моја породица. Моја дјеца данас имају 9, 14 и 17 година и сво троје су код њих праћени од рођења.

Оно што ову клинику издваја јесте спој изузетне стручности и искрено пажљивог односа према пацијенту. Термин се добија брзо, чекање је кратко, а од тренутка када уђете осјећате се добродошло, уважено и саслушано. Чак и једноставно питање „Како сте данас?“ овдје није пука формалност.

Љекари су врхунски стручњаци и професионалци којима вјерујем годинама. Посебну захвалност дугујем медицинским сестрама и цијелом особљу — њихов труд, љубазност и брига чине срце ове клинике.

Клинику Milmedika од срца препоручујем свима који траже квалитетну здравствену његу и људе којима могу да вјерују.'), text_en = COALESCE(text_en, 'I have been a patient at Milmedika for 16–17 years, and over that time my whole family has experienced their care and expertise. My children are now 9, 14 and 17, and all three have been cared for by the clinic since birth.

What sets this clinic apart is the combination of excellent medical care and genuine kindness. Appointments are easy to arrange, waiting times are short, and from the moment you walk in, you feel welcome, respected and listened to. Even a simple “How are you today?” feels sincere.

The doctors are highly skilled professionals whom I have trusted for years. I am equally grateful to the nurses and the entire support team — their dedication, warmth and care are truly the heart of this clinic.

I wholeheartedly recommend Milmedika to anyone looking for excellent healthcare and people they can trust.'), text_ru = COALESCE(text_ru, 'Я пациент клиники Milmedika уже 16–17 лет, и за все эти годы их заботу и профессионализм узнала и моя семья. Моим детям сейчас 9, 14 и 17 лет, и все трое наблюдаются у них с рождения.

Эту клинику отличает сочетание исключительного профессионализма и искренне внимательного отношения к пациенту. Записаться можно быстро, ждать приходится недолго, а с момента, как вы входите, вы чувствуете, что вам рады, вас уважают и выслушивают. Даже простой вопрос «Как вы сегодня?» здесь не пустая формальность.

Врачи — первоклассные специалисты и профессионалы, которым я доверяю много лет. Особую благодарность хочу выразить медсёстрам и всему персоналу — их старание, доброжелательность и забота составляют сердце этой клиники.

От всей души рекомендую Milmedika всем, кто ищет качественную медицинскую помощь и людей, которым можно доверять.'), text_de = COALESCE(text_de, 'Ich bin seit 16–17 Jahren Patient der Klinik Milmedika, und in all diesen Jahren hat auch meine Familie ihre Fürsorge und Fachkompetenz kennengelernt. Meine Kinder sind heute 9, 14 und 17 Jahre alt, und alle drei werden dort seit ihrer Geburt betreut.

Was diese Klinik auszeichnet, ist die Verbindung von herausragender Fachkompetenz und aufrichtig aufmerksamem Umgang mit den Patienten. Einen Termin bekommt man schnell, die Wartezeit ist kurz, und vom ersten Moment an fühlt man sich willkommen, respektiert und gehört. Selbst die einfache Frage „Wie geht es Ihnen heute?“ ist hier keine bloße Formalität.

Die Ärzte sind hervorragende Fachleute und Profis, denen ich seit Jahren vertraue. Besonderen Dank schulde ich den Krankenschwestern und dem gesamten Personal — ihr Einsatz, ihre Freundlichkeit und ihre Fürsorge sind das Herz dieser Klinik.

Ich empfehle Milmedika von Herzen allen, die eine hochwertige medizinische Versorgung und Menschen suchen, denen sie vertrauen können.'), text_tr = COALESCE(text_tr, '16–17 yıldır Milmedika kliniğinin hastasıyım ve bu yıllar boyunca ailem de onların ilgisini ve uzmanlığını tanıdı. Çocuklarım bugün 9, 14 ve 17 yaşında ve üçü de doğduklarından beri burada takip ediliyor.

Bu kliniği farklı kılan, olağanüstü uzmanlık ile hastaya karşı içten ve özenli yaklaşımın bir araya gelmesidir. Randevu hızlı alınıyor, bekleme süresi kısa ve içeri girdiğiniz andan itibaren kendinizi hoş karşılanmış, saygı görmüş ve dinlenmiş hissediyorsunuz. Basit bir “Bugün nasılsınız?” sorusu bile burada sadece bir formalite değil.

Doktorlar, yıllardır güvendiğim üst düzey uzmanlar ve profesyoneller. Hemşirelere ve tüm personele ayrıca minnettarım — onların emeği, nezaketi ve ilgisi bu kliniğin kalbidir.

Kaliteli sağlık hizmeti ve güvenebilecekleri insanlar arayan herkese Milmedika\'yı gönülden tavsiye ediyorum.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT21WWlRscExTR2xoYTJ4SlJURnVhaTFCT0RGRk1VRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Дана 11.09.2026. отишао сам да урадим биохемију, крвну слику итд. Само бих хтио да похвалим тим сестре Дуње и њеног колеге, лабораторијског техничара. Овај тим је све оно чему свака приватна здравствена установа треба да тежи, а то је професионалност, љубазност, хуманост!'), text_en = COALESCE(text_en, 'On 11.09.2026 I went to have blood biochemistry, a complete blood count, etc. done. I just wanted to praise the team of nurse Dunja and her colleague, a lab technician. This team is everything every private healthcare facility should strive for: professionalism, kindness, humanity!'), text_ru = COALESCE(text_ru, '11.09.2026 я сдавал биохимию, общий анализ крови и т. д. Хочу просто похвалить команду медсестры Дуни и её коллеги — лаборанта. Эта команда — всё то, к чему должно стремиться любое частное медицинское учреждение: профессионализм, доброжелательность, человечность!'), text_de = COALESCE(text_de, 'Am 11.09.2026 war ich zur Blutbiochemie, zum Blutbild usw. dort. Ich möchte einfach das Team von Schwester Dunja und ihrem Kollegen, einem Labortechniker, loben. Dieses Team verkörpert alles, wonach jede private Gesundheitseinrichtung streben sollte: Professionalität, Freundlichkeit, Menschlichkeit!'), text_tr = COALESCE(text_tr, '11.09.2026 tarihinde biyokimya, tam kan sayımı vb. tahliller için gittim. Hemşire Dunja ve laboratuvar teknisyeni olan meslektaşından oluşan ekibi övmek istiyorum. Bu ekip, her özel sağlık kuruluşunun ulaşmaya çalışması gereken her şeydir: profesyonellik, nezaket, insanlık!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT2toZmRYbFdTbk5PT0VVMFFrZHRkMFUyZURCVWNXYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све препоруке за клинику Milmedika, а посебно за Филипа! Заиста једно од најбољих искустава које сам икада имала у здравственој установи. Од првог тренутка све је било на највишем нивоу – професионалност, љубазност, организација и однос према пацијенту.

Филип заслужује посебну похвалу. Изузетно стручан, пажљив, смирен и посвећен, са приступом због којег се одмах осјећате сигурно и опуштено. Све објасни јасно, има стрпљења за свако питање и види се да му је заиста стало до пацијента и до тога да све буде урађено како треба. Такав спој стручности, професионалности и људскости се заиста ријетко среће.

Комплетно искуство у клиници Milmedika било је беспријекорно и заиста немам ниједну замјерку. Све је било сјајно од почетка до краја и дефинитивно бих их препоручила свакоме. Филипу Медвидовићу посебно једно огромно хвала – када наиђете на некога ко свој посао ради са толико пажње и посвећености, то се памти. Чиста десетка! ❤️'), text_en = COALESCE(text_en, 'All recommendations for Milmedika, and especially for Filip! Truly one of the best experiences I have ever had at a healthcare facility. From the very first moment everything was top-notch – professionalism, kindness, organization and attitude toward the patient.

Filip deserves special praise. Extremely knowledgeable, attentive, calm and dedicated, with an approach that makes you feel safe and relaxed right away. He explains everything clearly, has patience for every question, and you can see that he truly cares about the patient and about everything being done right. Such a combination of expertise, professionalism and humanity is truly rare.

The whole experience at Milmedika was flawless and I really have no complaints at all. Everything was great from start to finish and I would definitely recommend them to anyone. A special, huge thank you to Filip Medvidović – when you come across someone who does their job with so much care and dedication, you remember it. A perfect ten! ❤️'), text_ru = COALESCE(text_ru, 'Всячески рекомендую Milmedika, и особенно Филипа! Действительно один из лучших опытов, который у меня когда-либо был в медицинском учреждении. С первой минуты всё было на высшем уровне – профессионализм, доброжелательность, организация и отношение к пациенту.

Филип заслуживает особой похвалы. Исключительно знающий, внимательный, спокойный и преданный делу, с таким подходом, что сразу чувствуешь себя в безопасности и расслабляешься. Всё ясно объясняет, терпеливо отвечает на любой вопрос, и видно, что ему действительно не всё равно, каково пациенту, и важно, чтобы всё было сделано как надо. Такое сочетание компетентности, профессионализма и человечности встречается действительно редко.

Всё в Milmedika было безупречно, и у меня правда нет ни одного замечания. Всё было прекрасно от начала до конца, и я однозначно рекомендовала бы их каждому. Отдельное огромное спасибо Филипу Медвидовичу – когда встречаешь человека, который делает свою работу с таким вниманием и самоотдачей, это запоминается. Твёрдая десятка! ❤️'), text_de = COALESCE(text_de, 'Volle Empfehlung für Milmedika, und ganz besonders für Filip! Wirklich eine der besten Erfahrungen, die ich je in einer Gesundheitseinrichtung gemacht habe. Vom ersten Moment an war alles auf höchstem Niveau – Professionalität, Freundlichkeit, Organisation und Umgang mit den Patienten.

Filip verdient besonderes Lob. Äußerst kompetent, aufmerksam, ruhig und engagiert, mit einer Art, bei der man sich sofort sicher und entspannt fühlt. Er erklärt alles verständlich, hat Geduld für jede Frage, und man merkt, dass ihm der Patient wirklich am Herzen liegt und dass alles richtig gemacht wird. Eine solche Verbindung von Fachwissen, Professionalität und Menschlichkeit findet man wirklich selten.

Die gesamte Erfahrung bei Milmedika war tadellos, und ich habe wirklich nichts zu bemängeln. Alles war von Anfang bis Ende großartig, und ich würde sie definitiv jedem empfehlen. Filip Medvidović ein ganz besonders großes Dankeschön – wenn man jemandem begegnet, der seine Arbeit mit so viel Sorgfalt und Hingabe macht, bleibt das in Erinnerung. Eine glatte Zehn! ❤️'), text_tr = COALESCE(text_tr, 'Milmedika\'yı, özellikle de Filip\'i herkese tavsiye ederim! Gerçekten bir sağlık kuruluşunda yaşadığım en iyi deneyimlerden biri. İlk andan itibaren her şey en üst düzeydeydi – profesyonellik, nezaket, organizasyon ve hastaya yaklaşım.

Filip özel bir övgüyü hak ediyor. Son derece bilgili, dikkatli, sakin ve işine bağlı; yaklaşımı sayesinde kendinizi hemen güvende ve rahat hissediyorsunuz. Her şeyi açıkça anlatıyor, her soruya sabır gösteriyor ve hastayı ve her şeyin doğru yapılmasını gerçekten önemsediği belli oluyor. Uzmanlık, profesyonellik ve insanlığın böyle bir birleşimine gerçekten nadiren rastlanır.

Milmedika\'daki deneyimin tamamı kusursuzdu ve gerçekten hiçbir şikâyetim yok. Her şey baştan sona harikaydı ve onları kesinlikle herkese tavsiye ederim. Filip Medvidović\'e ayrıca kocaman bir teşekkür – işini bu kadar özen ve bağlılıkla yapan biriyle karşılaştığınızda, bu unutulmaz. Tam on numara! ❤️') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT205YWRUSklVa1V5YWxBM04xQjVNbFZuVG5GbFVGRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Osoblje je bezobrazno. Čekao sam ispred ordinacije, ja sam pacijent. Rekli su da postoji drugi pacijent koji ima zakazan termin. Rekao sam: u redu. Naravno, on će ući prije mene. Ali natjerali su me da ustanem s mjesta na kojem sam sjedio. S kojim pravom?! Kakav bezobrazluk! Razlog je bio da bi pacijent prije mene mogao da sjedne. A niste čak ni ljekar, a bez stida tražite analizu krvi. Ustao sam i otišao. Vi ste prava zamka za novac. Ne dao Bog nikome da vam padne u ruke. I to se dešava prije nego što uopšte dođete do ljekara.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Особље је безобразно. Чекао сам испред ординације, ја сам пацијент. Рекли су да постоји други пацијент који има заказан термин. Рекао сам: у реду. Наравно, он ће ући прије мене. Али натјерали су ме да устанем с мјеста на којем сам сједио. С којим правом?! Какав безобразлук! Разлог је био да би пацијент прије мене могао да сједне. А нисте чак ни љекар, а без стида тражите анализу крви. Устао сам и отишао. Ви сте права замка за новац. Не дао Бог никоме да вам падне у руке. И то се дешава прије него што уопште дођете до љекара.'), text_ru = COALESCE(text_ru, 'Персонал грубый. Я ждал у кабинета врача, я пациент. Мне сказали, что есть другой пациент, записанный на приём. Я ответил: хорошо. Конечно, он пройдёт раньше меня. Но меня заставили встать с места, где я сидел. По какому праву?! Какая грубость! Причина была в том, чтобы пациент передо мной мог сесть. А вы даже не врач, но без стеснения требуете сдать анализ крови. Я встал и ушёл. Вы настоящая ловушка для денег. Не дай Бог никому попасть к вам в руки. И это происходит ещё до того, как вы попадёте к врачу.'), text_de = COALESCE(text_de, 'Das Personal ist unhöflich. Ich wartete vor dem Arztzimmer, ich bin Patient. Man sagte mir, es gebe einen anderen Patienten mit Termin. Ich sagte: in Ordnung. Natürlich kommt er vor mir dran. Aber man ließ mich von meinem Platz aufstehen. Mit welchem Recht?! Wie unverschämt! Der Grund war, dass sich der Patient vor mir setzen konnte. Und Sie sind nicht einmal Arzt, verlangen aber schamlos einen Bluttest. Ich bin aufgestanden und gegangen. Sie sind eine reine Geldfalle. Gott bewahre, dass jemand in Ihre Hände gerät. Und das passiert, noch bevor man überhaupt zum Arzt kommt.'), text_tr = COALESCE(text_tr, 'Personel kaba. Doktorun odasının önünde bekliyordum, ben bir hastayım. Randevusu olan başka bir hasta olduğunu söylediler. Tamam dedim. Elbette benden önce girecek. Ama oturduğum yerden kalkmamı istediler. Ne hakla?! Ne kadar kaba! Sebebi, benden önceki hastanın oturabilmesiydi. Üstelik doktor bile değilsiniz, ama utanmadan kan tahlili istiyorsunuz. Kalkıp gittim. Tam bir para tuzağısınız. Allah kimseyi elinize düşürmesin. Bu daha doktora girmeden oluyor.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xGSk5XMTFTR1pYVlZocmVqRmtSVlJqUmtSSlJVRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Imao sam zdravstveni problem i odlučio sam se za ovu kliniku.
Na recepciji su mi odmah zakazali termin kod specijalistkinje za sljedeći dan i rekli cijene liječenja u eurima. Istovremeno su me poslali u susjednu laboratoriju da uradim potrebnu analizu krvi. Odmah sam došao na red i nisam morao da čekam. Rezultat su mi poslali mejlom 2 sata kasnije.
Pregled kod specijalistkinje sljedećeg dana počeo je na vrijeme i čekali smo samo 7 minuta. Osoblje nam se čak i izvinilo zbog toga. Doktorka je odvojila mnogo vremena i profesionalno me pregledala.
Osoblje u klinici i u laboratoriji bilo je izuzetno ljubazno, predusretljivo i spremno da pomogne.
Ovu kliniku toplo preporučujem! Sve je bilo odlično, čisto i profesionalno!
Ako budem imao problem, sigurno ću ponovo doći!
Hvala vam puno'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Имао сам здравствени проблем и одлучио сам се за ову клинику.
На рецепцији су ми одмах заказали термин код специјалисткиње за сљедећи дан и рекли цијене лијечења у еврима. Истовремено су ме послали у сусједну лабораторију да урадим потребну анализу крви. Одмах сам дошао на ред и нисам морао да чекам. Резултат су ми послали мејлом 2 сата касније.
Преглед код специјалисткиње сљедећег дана почео је на вријеме и чекали смо само 7 минута. Особље нам се чак и извинило због тога. Докторка је одвојила много времена и професионално ме прегледала.
Особље у клиници и у лабораторији било је изузетно љубазно, предусретљиво и спремно да помогне.
Ову клинику топло препоручујем! Све је било одлично, чисто и професионално!
Ако будем имао проблем, сигурно ћу поново доћи!
Хвала вам пуно'), text_en = COALESCE(text_en, 'I had a health problem and chose this clinic.
At reception I was immediately given an appointment with a specialist for the following day and told the prices for the treatment in euros. At the same time I was sent next door to the lab to have a necessary blood test done. I was seen right away and didn\'t have to wait. The result was sent by email 2 hours later.
The appointment with the specialist the next day was on time and we only had to wait 7 minutes. The staff even apologized to us for that. The doctor took a lot of time and examined me professionally.
The staff at the clinic and in the lab were super friendly, obliging and helpful.
I can highly recommend this clinic! Everything was excellent, clean and professional!
I would definitely come back if I had a problem!
Thank you very much'), text_ru = COALESCE(text_ru, 'У меня возникла проблема со здоровьем, и я выбрал эту клинику.
На ресепшене меня сразу записали к врачу-специалисту на следующий день и назвали цены на лечение в евро. Тут же меня отправили в соседнюю лабораторию сдать необходимый анализ крови. Меня приняли сразу, ждать не пришлось. Результат прислали по электронной почте через 2 часа.
Приём у специалиста на следующий день начался вовремя, ждать пришлось всего 7 минут. Персонал даже извинился перед нами за это. Врач уделила мне много времени и профессионально меня осмотрела.
Персонал в клинике и в лаборатории был очень дружелюбным, предупредительным и всегда готов помочь.
Очень рекомендую эту клинику! Всё было отлично, чисто и профессионально!
Если возникнет проблема, обязательно приду снова!
Большое спасибо'), text_tr = COALESCE(text_tr, 'Bir sağlık sorunum vardı ve bu kliniği seçtim.
Resepsiyonda hemen ertesi gün için bir uzman doktordan randevu verildi ve tedavinin fiyatları euro olarak söylendi. Aynı anda gerekli kan tahlilini yaptırmam için yandaki laboratuvara gönderildim. Hemen sıram geldi, beklemek zorunda kalmadım. Sonuç 2 saat sonra e-postayla gönderildi.
Ertesi günkü uzman randevusu zamanındaydı ve sadece 7 dakika beklememiz gerekti. Personel bunun için bile bizden özür diledi. Doktor bana çok zaman ayırdı ve beni profesyonelce muayene etti.
Klinikteki ve laboratuvardaki personel son derece güler yüzlü, nazik ve yardımseverdi.
Bu kliniği kesinlikle tavsiye ederim! Her şey mükemmel, temiz ve profesyoneldi!
Bir sorunum olursa kesinlikle tekrar gelirim!
Çok teşekkürler') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT25scFozVTFWSE00VkcxNVR6RkZZbFpEZFdkRWFVRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Sve u svemu, imam pomiješana osjećanja u vezi s ovom laboratorijom.

Došli smo sa bebom, a tamo je stajao natpis da stariji, osobe s invaliditetom, trudnice i roditelji s malom djecom imaju prednost. Uprkos tome, čekali smo u redovnom redu na recepciji. Kada smo konačno došli na red, recepcionerka nas je zamolila da sačekamo kako bi prvo upisala jednu stariju ženu. Nakon toga je htjela da nastavi da uslužuje i druge. Trebalo je da je podsjetim da smo već čekali u redu, i tek tada nas je upisala.

Od pozitivnih strana, tehničar koji je vadio krv bio je veoma profesionalan i nježan. Postupak je bio brz, što je posebno važno s malom bebom. Rezultate smo dobili za svega nekoliko minuta.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све у свему, имам помијешана осјећања у вези с овом лабораторијом.

Дошли смо са бебом, а тамо је стајао натпис да старији, особе с инвалидитетом, труднице и родитељи с малом дјецом имају предност. Упркос томе, чекали смо у редовном реду на рецепцији. Када смо коначно дошли на ред, рецепционерка нас је замолила да сачекамо како би прво уписала једну старију жену. Након тога је хтјела да настави да услужује и друге. Требало је да је подсјетим да смо већ чекали у реду, и тек тада нас је уписала.

Од позитивних страна, техничар који је вадио крв био је веома професионалан и њежан. Поступак је био брз, што је посебно важно с малом бебом. Резултате смо добили за свега неколико минута.'), text_ru = COALESCE(text_ru, 'В целом у меня смешанные впечатления от этой лаборатории.

Мы пришли с младенцем, и там висела табличка о том, что пожилые люди, люди с инвалидностью, беременные и родители с маленькими детьми обслуживаются вне очереди. Несмотря на это, мы стояли в общей очереди на ресепшене. Когда наконец подошла наша очередь, администратор попросила нас подождать, чтобы сначала оформить пожилую женщину. После этого она собиралась обслуживать и других. Пришлось напомнить ей, что мы уже отстояли очередь, и только тогда она нас оформила.

Из положительного: лаборант, который брал кровь, был очень профессиональным и аккуратным. Процедура прошла быстро, что особенно важно с маленьким ребёнком. Результаты анализов мы тоже получили всего через несколько минут.'), text_de = COALESCE(text_de, 'Insgesamt habe ich gemischte Gefühle gegenüber diesem Labor.

Wir kamen mit unserem Säugling, und es gab ein Schild, auf dem stand, dass ältere Menschen, Menschen mit Behinderung, Schwangere und Eltern mit kleinen Kindern bevorzugt bedient werden. Trotzdem warteten wir in der normalen Schlange an der Rezeption. Als wir endlich dran waren, bat uns die Rezeptionistin zu warten, damit sie zuerst eine ältere Frau anmelden konnte. Danach wollte sie auch noch andere Leute bedienen. Ich musste sie daran erinnern, dass wir bereits angestanden hatten, und erst dann meldete sie uns an.

Positiv: Der Techniker, der die Blutprobe abnahm, war sehr professionell und behutsam. Die Prozedur ging schnell, was mit einem kleinen Baby besonders wichtig ist. Die Ergebnisse bekamen wir außerdem schon nach wenigen Minuten.'), text_tr = COALESCE(text_tr, 'Genel olarak bu laboratuvar hakkında karışık duygularım var.

Bebeğimizle geldik ve orada yaşlıların, engellilerin, hamilelerin ve küçük çocuklu ebeveynlerin öncelikli hizmet aldığını belirten bir tabela vardı. Buna rağmen resepsiyonda normal sırada bekledik. Sonunda sıra bize geldiğinde, resepsiyonist önce yaşlı bir kadının kaydını yapmak için beklememizi istedi. Ardından başkalarına da hizmet vermeye devam etmek üzereydi. Zaten sırada beklediğimizi kendisine hatırlatmam gerekti ve ancak o zaman kaydımızı yaptı.

Olumlu tarafı ise kan örneğini alan teknisyen çok profesyonel ve nazikti. İşlem hızlıydı, bu da küçük bir bebekle özellikle önemli. Test sonuçlarını da sadece birkaç dakika içinde aldık.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT2t0YVNVZFFUMlpVTFZKcmEyZHVPR2hEUzA5U1psRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Tokom našeg odmora u Crnoj Gori moja supruga je dobila tešku upalu mokraćne bešike. Pošto je trudna, tražili smo kliniku i na kraju je pronašli ovdje. Srdačno su nas dočekali, bez oklijevanja pomogli i veoma stručno (na dobrom engleskom) postavili dijagnozu. Kompletna krvna slika, brzi razgovori s ljekarima bez dugog čekanja i tačna dijagnoza (koju je naknadno potvrdila i naša ginekološkinja iz Njemačke u telefonskom razgovoru) ostavili su odličan utisak. Veoma profesionalno i s pažnjom prema pacijentima. Nakon otprilike sat i po račun je iznosio 73 € – a za to smo dobili visok nivo stručnosti kakav se u Njemačkoj za tako kratko vrijeme teško može naći. Jasna preporuka. Hvala vam puno na pomoći.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Током нашег одмора у Црној Гори моја супруга је добила тешку упалу мокраћне бешике. Пошто је трудна, тражили смо клинику и на крају је пронашли овдје. Срдачно су нас дочекали, без оклијевања помогли и веома стручно (на добром енглеском) поставили дијагнозу. Комплетна крвна слика, брзи разговори с љекарима без дугог чекања и тачна дијагноза (коју је накнадно потврдила и наша гинеколошкиња из Њемачке у телефонском разговору) оставили су одличан утисак. Веома професионално и с пажњом према пацијентима. Након отприлике сат и по рачун је износио 73 € – а за то смо добили висок ниво стручности какав се у Њемачкој за тако кратко вријеме тешко може наћи. Јасна препорука. Хвала вам пуно на помоћи.'), text_en = COALESCE(text_en, 'During our holiday in Montenegro my wife developed a severe bladder infection. Because she is pregnant, we looked for a clinic and eventually found this one. We were warmly welcomed, supported without hesitation and diagnosed very competently (in good English). A full blood count, short-notice and very quick consultations with the doctors, and the correct diagnosis (also confirmed afterwards in a phone call with our gynecologist in Germany) left a great impression. Very professional and patient-friendly. The bill came to €73 after about 1.5 hours – and for that we got a level of competence you would hardly find in Germany in such a short time anymore. Clear recommendation. Thank you very much for your help.'), text_ru = COALESCE(text_ru, 'Во время нашего отпуска в Черногории у жены начался сильный цистит. Из-за беременности мы искали клинику и в итоге нашли эту. Нас тепло встретили, без колебаний помогли и очень грамотно (на хорошем английском) поставили диагноз. Развёрнутый анализ крови, быстрые консультации у врачей без долгого ожидания и верный диагноз (его потом подтвердил и наш гинеколог из Германии по телефону) оставили отличное впечатление. Очень профессионально и с заботой о пациенте. Примерно через полтора часа счёт составил 73 € – и за это мы получили такой уровень компетентности, какой в Германии за такое короткое время, пожалуй, уже не найти. Однозначно рекомендую. Большое спасибо за помощь.'), text_tr = COALESCE(text_tr, 'Karadağ\'daki tatilimiz sırasında eşim ağır bir mesane iltihabı geçirdi. Hamile olduğu için bir klinik aradık ve sonunda burayı bulduk. Bizi sıcak bir şekilde karşıladılar, tereddüt etmeden yardımcı oldular ve çok yetkin bir şekilde (iyi bir İngilizceyle) teşhis koydular. Kapsamlı kan sayımı, kısa sürede ve çok hızlı doktor görüşmeleri ve doğru teşhis (sonradan Almanya\'daki kadın doğum uzmanımızla telefonda yaptığımız görüşmeyle de doğrulandı) harika bir izlenim bıraktı. Çok profesyonel ve hasta dostu. Yaklaşık 1,5 saatin sonunda hesap 73 € tuttu – karşılığında Almanya\'da bu kadar kısa sürede artık pek bulunamayacak düzeyde bir yetkinlik aldık. Kesinlikle tavsiye ederim. Yardımlarınız için çok teşekkürler.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT25NdFgwMVpPRFZZVlhoNFRqSjZiVTkzUkUwd2NGRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Dobili smo odličnu medicinsku njegu kod dr Radojke Lekić u klinici Milmedika. Odlični profesionalci.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Добили смо одличну медицинску његу код др Радојке Лекић у клиници Milmedika. Одлични професионалци.'), text_ru = COALESCE(text_ru, 'Доктор Радойка Лекич в Milmedika оказала нам отличную медицинскую помощь. Прекрасные профессионалы.'), text_de = COALESCE(text_de, 'Wir wurden von Dr. Radojka Lekić bei Milmedika hervorragend medizinisch versorgt. Ausgezeichnete Fachleute.'), text_tr = COALESCE(text_tr, 'Milmedika\'da Dr. Radojka Lekić\'ten mükemmel bir tıbbi bakım aldık. Mükemmel profesyoneller.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT25RNVUxQnhMVUpwT1MxWVFVOTBRVWN6VmpjMmIyYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Изузетно непрофесионално и нељубазно особље на телефону! Приликом покушаја заказивања прегледа код др Добричанина, запослена радница је била некултурна и буквално се смијала током разговора. Недопустиво понашање за једну приватну здравствену установу. Ако је љекар стручњак, особље на пријему би морало да прати тај ниво професионализма. У питању је Подгорица.'), text_en = COALESCE(text_en, 'Extremely unprofessional and rude staff on the phone! When trying to book an appointment with Dr Dobričanin, the employee was impolite and literally laughed during the conversation. Unacceptable behavior for a private healthcare facility. If the doctor is an expert, the reception staff should match that level of professionalism. This is about Podgorica.'), text_ru = COALESCE(text_ru, 'Крайне непрофессиональный и невежливый персонал на телефоне! При попытке записаться на приём к доктору Добричанину сотрудница вела себя некультурно и буквально смеялась во время разговора. Недопустимое поведение для частного медицинского учреждения. Если врач — специалист, то и персонал на ресепшене должен соответствовать этому уровню профессионализма. Речь о Подгорице.'), text_de = COALESCE(text_de, 'Äußerst unprofessionelles und unfreundliches Personal am Telefon! Beim Versuch, einen Termin bei Dr. Dobričanin zu vereinbaren, war die Mitarbeiterin unhöflich und hat während des Gesprächs buchstäblich gelacht. Ein inakzeptables Verhalten für eine private Gesundheitseinrichtung. Wenn der Arzt ein Experte ist, sollte das Empfangspersonal diesem Maß an Professionalität gerecht werden. Es geht um Podgorica.'), text_tr = COALESCE(text_tr, 'Telefonda son derece profesyonellikten uzak ve kaba personel! Dr. Dobričanin\'den randevu almaya çalışırken çalışan kadın kabaydı ve görüşme sırasında resmen gülüyordu. Özel bir sağlık kuruluşu için kabul edilemez bir davranış. Doktor bir uzmansa, kayıt personeli de bu profesyonellik düzeyine ayak uydurmalı. Söz konusu olan Podgorica.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xaT1dtcG5SbVEzTVZSd1JtcFNkVUo2VUVKWE9YYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Veoma profesionalna medicinska usluga, sjajno i ljubazno osoblje s visokim nivoom empatije, što je danas rijetkost.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома професионална медицинска услуга, сјајно и љубазно особље с високим нивоом емпатије, што је данас ријеткост.'), text_ru = COALESCE(text_ru, 'Очень профессиональное медицинское обслуживание, замечательный и доброжелательный персонал с высоким уровнем эмпатии, что в наше время редкость.'), text_de = COALESCE(text_de, 'Sehr professionelle medizinische Versorgung, tolles und freundliches Personal mit viel Empathie – heutzutage selten zu finden.'), text_tr = COALESCE(text_tr, 'Çok profesyonel bir sağlık hizmeti, empati düzeyi yüksek, harika ve nazik bir personel – bu zamanlarda nadir rastlanır.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT21seGRuWktkVFJYWVdOWWJqbFNRVzlJYzFSMFNIYxAB';
