UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Урадио сам рендген, нису ми нарезали диск, па сам бацио паре, а код доктора нису могли ништа да виде. Молим вас, идите у друге приватне клинике.'), text_en = COALESCE(text_en, 'I had an X-ray done, they didn\'t burn the images to a disc, so I wasted my money and the doctor couldn\'t see anything. Please go to other private clinics.'), text_ru = COALESCE(text_ru, 'Сделал рентген, мне не записали диск, так что деньги я выбросил на ветер, а врач ничего не смог посмотреть. Пожалуйста, идите в другие частные клиники.'), text_de = COALESCE(text_de, 'Ich habe ein Röntgenbild machen lassen, man hat mir keine CD gebrannt, also habe ich mein Geld zum Fenster hinausgeworfen, und beim Arzt konnte man nichts sehen. Bitte geht in andere Privatkliniken.'), text_tr = COALESCE(text_tr, 'Röntgen çektirdim, görüntüleri diske yazmadılar, yani paramı çöpe attım ve doktorda hiçbir şey göremediler. Lütfen başka özel kliniklere gidin.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJkRQwYCfrTRMR-kFKi7_Ilyg/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pKTVh5MUVlR3hYTW1Kbk5FSnRjV1F0VWtSdk5WRRAB';
