UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све похвале за Milmedika клинику у Никшићу! Презадовољни смо комплетном услугом, професионалношћу и, прије свега, љубазношћу и пажњом цијелог особља. Од самог доласка осјећали смо се пријатно, сигурно и добродошло.
