UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Јако пријатно особље, велике похвале за др Зиндовића. Чиста десетка.'), text_en = COALESCE(text_en, 'Very pleasant staff, big praise for Dr. Zindović. A solid 10.'), text_ru = COALESCE(text_ru, 'Очень приятный персонал, огромная благодарность доктору Зиндовичу. Твёрдая десятка.'), text_de = COALESCE(text_de, 'Sehr angenehmes Personal, großes Lob an Dr. Zindović. Eine glatte 10.'), text_tr = COALESCE(text_tr, 'Çok hoş bir ekip, Dr. Zindović\'e büyük övgüler. Tam 10 puan.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJ655v-VzVTRMRq8OGU_bGuPQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xoUFJsVTRiV04yTVhsSFgwUnZlR2xGT1ZaRlRWRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'ДР ДОБРИЛА И ДР ЛИЉА СУ ДИВНЕ, ЗНАЊЕ, ПОСВЕЋЕНОСТ И ИЗНАД СВЕГА ИСКУСТВО, СВОЈЕ ЗДРАВЉЕ ПОВЈЕРАВАМ ЊИМА'), text_en = COALESCE(text_en, 'DR. DOBRILA AND DR. LILYA ARE WONDERFUL — KNOWLEDGE, DEDICATION AND ABOVE ALL EXPERIENCE. I TRUST THEM WITH MY HEALTH'), text_ru = COALESCE(text_ru, 'ДОКТОР ДОБРИЛА И ДОКТОР ЛИЛЯ ЧУДЕСНЫЕ: ЗНАНИЯ, ПРЕДАННОСТЬ ДЕЛУ И ПРЕЖДЕ ВСЕГО ОПЫТ. Я ДОВЕРЯЮ ИМ СВОЁ ЗДОРОВЬЕ'), text_de = COALESCE(text_de, 'DR. DOBRILA UND DR. LILYA SIND WUNDERBAR – WISSEN, HINGABE UND VOR ALLEM ERFAHRUNG. IHNEN VERTRAUE ICH MEINE GESUNDHEIT AN'), text_tr = COALESCE(text_tr, 'DR. DOBRILA VE DR. LILYA HARİKA — BİLGİ, ÖZVERİ VE HER ŞEYDEN ÖNCE TECRÜBE. SAĞLIĞIMI ONLARA EMANET EDİYORUM') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJ655v-VzVTRMRq8OGU_bGuPQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT25acE9ISXhWbnBzWlhoU2JWZ3laM1ZyYTBFNWMwRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Била сам на прегледу, презадовољна сам услугом, све препоруке за њих.'), text_en = COALESCE(text_en, 'I came for a check-up and was extremely satisfied with the service. Highly recommend them.'), text_ru = COALESCE(text_ru, 'Была на осмотре, осталась более чем довольна обслуживанием. Всем их рекомендую.'), text_de = COALESCE(text_de, 'Ich war zur Untersuchung und bin mit dem Service äußerst zufrieden. Absolut empfehlenswert.'), text_tr = COALESCE(text_tr, 'Muayeneye gittim, hizmetten son derece memnun kaldım. Herkese tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJ655v-VzVTRMRq8OGU_bGuPQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tkTVQxTlFSWGMyT1RoWlR6SlNWSHBoWmpKUWFYYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све похвале цијелом тиму на професионалности, љубазности и посвећености пацијентима. Посебно желим да истакнем хирурга др Зиндовића и анестезиологињу др Дуњу, који су свој посао обавили врхунски и улили ми велико повјерење. Велико хвала и медицинској сестри Наташи на њеној бризи, стрпљењу, топлом приступу и осмијеху. Захваљујући оваквом тиму, осјећала сам се сигурно и збринуто. Искрена препорука и велико хвала свима! ❤️'), text_en = COALESCE(text_en, 'All praise to the whole team for their professionalism, kindness and dedication to patients. I especially want to highlight the surgeon Dr. Zindović and the anesthesiologist Dr. Dunja, who did a superb job and gave me great confidence. A big thank you also to nurse Nataša for her care, patience, warm approach and smile. Thanks to a team like this, I felt safe and well looked after. A sincere recommendation and a big thank you to everyone! ❤️'), text_ru = COALESCE(text_ru, 'Огромная благодарность всей команде за профессионализм, доброжелательность и внимание к пациентам. Особенно хочу отметить хирурга доктора Зиндовича и анестезиолога доктора Дуню: они сработали на высшем уровне и вселили в меня большое доверие. Большое спасибо и медсестре Наташе за заботу, терпение, тёплое отношение и улыбку. Благодаря такой команде я чувствовала себя в безопасности и под надёжной опекой. Искренне рекомендую и всем огромное спасибо! ❤️'), text_de = COALESCE(text_de, 'Großes Lob an das gesamte Team für Professionalität, Freundlichkeit und Hingabe an die Patienten. Besonders hervorheben möchte ich den Chirurgen Dr. Zindović und die Anästhesistin Dr. Dunja, die hervorragende Arbeit geleistet und mir großes Vertrauen gegeben haben. Ein großes Dankeschön auch an die Krankenschwester Nataša für ihre Fürsorge, Geduld, ihre herzliche Art und ihr Lächeln. Dank eines solchen Teams habe ich mich sicher und gut versorgt gefühlt. Eine aufrichtige Empfehlung und vielen Dank an alle! ❤️'), text_tr = COALESCE(text_tr, 'Profesyonellikleri, nezaketleri ve hastalara bağlılıkları için tüm ekibe övgüler. Özellikle işlerini mükemmel şekilde yapan ve bana büyük güven veren cerrah Dr. Zindović\'i ve anestezi uzmanı Dr. Dunja\'yı anmak istiyorum. Hemşire Nataša\'ya da ilgisi, sabrı, sıcak yaklaşımı ve gülümsemesi için çok teşekkür ederim. Böyle bir ekip sayesinde kendimi güvende ve emin ellerde hissettim. İçtenlikle tavsiye ediyorum, herkese çok teşekkürler! ❤️') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJ655v-VzVTRMRq8OGU_bGuPQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT2kxb2JYRkxhMU5zYzBvMGRYTmpjSGRhY1ZreVdXYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Клиника за сваку препоруку! Све похвале за комплетан тим на челу са доктором Миљаном Зиндовићем, а посебно бих истакао љубазност и рад сестара Наташе Шпањевић и Виолете Бубања 🙏🏻👍 Њихова добродошлица охрабрује све пацијенте 🙏🏻💪🏻'), text_en = COALESCE(text_en, 'A clinic I fully recommend! All praise for the whole team, headed by Dr. Miljan Zindović, and I would especially highlight the kindness and work of nurses Nataša Španjević and Violeta Bubanja 🙏🏻👍 Their warm welcome encourages every patient 🙏🏻💪🏻'), text_ru = COALESCE(text_ru, 'Клиника, которую можно смело рекомендовать! Все похвалы всей команде во главе с доктором Мильяном Зиндовичем, а особенно хочу отметить доброжелательность и работу медсестёр Наташи Шпаньевич и Виолеты Бубаня 🙏🏻👍 Их радушный приём ободряет всех пациентов 🙏🏻💪🏻'), text_de = COALESCE(text_de, 'Eine Klinik, die ich uneingeschränkt empfehlen kann! Großes Lob an das gesamte Team unter der Leitung von Dr. Miljan Zindović, besonders hervorheben möchte ich die Freundlichkeit und Arbeit der Krankenschwestern Nataša Španjević und Violeta Bubanja 🙏🏻👍 Ihr herzlicher Empfang macht allen Patienten Mut 🙏🏻💪🏻'), text_tr = COALESCE(text_tr, 'Kesinlikle tavsiye edilecek bir klinik! Dr. Miljan Zindović liderliğindeki tüm ekibe övgüler; özellikle hemşireler Nataša Španjević ve Violeta Bubanja\'nın nezaketini ve emeğini vurgulamak isterim 🙏🏻👍 Sıcak karşılamaları tüm hastalara cesaret veriyor 🙏🏻💪🏻') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJ655v-VzVTRMRq8OGU_bGuPQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT2psM1JVMDBWalphU0RGQlgxZHhhRGhqZGpCWVlWRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома сам задовољна услугом ове клинике. Хвала цијелом тиму ове клинике! Љубазни, професионални и увијек спремни да помогну. Доктор је детаљно објаснио сваки корак прегледа и терапије, због чега сам се осјећала сигурно и опуштено. Урађено је више него што сам очекивала.
🙏 Посебно хоћу да захвалим сестри Наташи на одговорности, стручности и љубазности. Све препоруке!'), text_en = COALESCE(text_en, 'I am very satisfied with this clinic\'s service. Thank you to the whole team at this clinic! Friendly, professional and always ready to help. The doctor explained every step of the examination and treatment in detail, which made me feel safe and relaxed. More was done than I had expected.
🙏 I especially want to thank nurse Nataša for her responsibility, expertise and kindness. Highly recommended!'), text_ru = COALESCE(text_ru, 'Я очень довольна обслуживанием в этой клинике. Спасибо всей команде клиники! Вежливые, профессиональные и всегда готовы помочь. Доктор подробно объяснил каждый этап обследования и лечения, поэтому я чувствовала себя уверенно и спокойно. Сделали даже больше, чем я ожидала.
🙏 Особенно хочу поблагодарить медсестру Наташу за ответственность, профессионализм и доброжелательность. Всем рекомендую!'), text_de = COALESCE(text_de, 'Ich bin mit dem Service dieser Klinik sehr zufrieden. Danke an das gesamte Team der Klinik! Freundlich, professionell und immer hilfsbereit. Der Arzt hat jeden Schritt der Untersuchung und Behandlung ausführlich erklärt, wodurch ich mich sicher und entspannt gefühlt habe. Es wurde mehr gemacht, als ich erwartet hatte.
🙏 Besonders danken möchte ich der Krankenschwester Nataša für ihr Verantwortungsbewusstsein, ihre Kompetenz und Freundlichkeit. Absolut empfehlenswert!'), text_tr = COALESCE(text_tr, 'Bu kliniğin hizmetinden çok memnun kaldım. Kliniğin tüm ekibine teşekkürler! Nazik, profesyonel ve her zaman yardıma hazırlar. Doktor muayenenin ve tedavinin her adımını ayrıntılı şekilde açıkladı, bu sayede kendimi güvende ve rahat hissettim. Beklediğimden fazlası yapıldı.
🙏 Özellikle hemşire Nataša\'ya sorumluluğu, uzmanlığı ve nezaketi için teşekkür etmek istiyorum. Herkese tavsiye ederim!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJ655v-VzVTRMRq8OGU_bGuPQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT25wU05VOXlTQzFMUjJ4RlRVeFdNakZTUkZoVVMyYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Došao sam u ovu kliniku sa jakim bolovima i morao sam da čekam više od sat vremena prije nego što su me primili. Doktor je bio veoma ljubazan i govorio je ruski, što mi je značilo.

Nažalost, ostatak iskustva je bio krajnje razočaravajući. Medicinska sestra nije uspjela da pravilno postavi iglu za infuziju iz prvog pokušaja, a u drugom pokušaju je, izgleda, pogodila nerv. Tri dana kasnije moja desna ruka i dalje ne funkcioniše normalno.

Osoblje je ukupno četiri puta pokušalo da da injekciju, ali nijedan lijek nisu uspjeli da daju, tvrdeći da moje tijelo „odbija“ injekcije. Iako nikakva terapija zapravo nije data, ipak su mi je naplatili.

Prepisani su mi i antibiotici, a da, kako mi se činilo, nije bilo prave dijagnoze niti jasnog objašnjenja zašto su potrebni.

Dva sata kasnije otišao sam u drugu kliniku. Tamo je medicinsko osoblje bez ikakvih poteškoća postavilo infuziju iz prvog pokušaja, uspješno dalo lijek i pravilno dijagnostikovalo moje stanje. Antibiotici nisu bili dio terapije, što ozbiljno dovodi u pitanje potrebu za receptom koji sam dobio u ovoj klinici.

Iako je doktor bio ljubazan, ukupan kvalitet njege koju sam dobio bio je neprihvatljiv.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Дошао сам у ову клинику са јаким боловима и морао сам да чекам више од сат времена прије него што су ме примили. Доктор је био веома љубазан и говорио је руски, што ми је значило.

Нажалост, остатак искуства је био крајње разочаравајући. Медицинска сестра није успјела да правилно постави иглу за инфузију из првог покушаја, а у другом покушају је, изгледа, погодила нерв. Три дана касније моја десна рука и даље не функционише нормално.

Особље је укупно четири пута покушало да да ињекцију, али ниједан лијек нису успјели да дају, тврдећи да моје тијело „одбија“ ињекције. Иако никаква терапија заправо није дата, ипак су ми је наплатили.

Преписани су ми и антибиотици, а да, како ми се чинило, није било праве дијагнозе нити јасног објашњења зашто су потребни.

Два сата касније отишао сам у другу клинику. Тамо је медицинско особље без икаквих потешкоћа поставило инфузију из првог покушаја, успјешно дало лијек и правилно дијагностиковало моје стање. Антибиотици нису били дио терапије, што озбиљно доводи у питање потребу за рецептом који сам добио у овој клиници.

Иако је доктор био љубазан, укупан квалитет његе коју сам добио био је неприхватљив.'), text_ru = COALESCE(text_ru, 'Я пришёл в эту клинику с сильной болью, и мне пришлось ждать больше часа, прежде чем меня приняли. Доктор был очень приветлив и говорил по-русски, что я оценил.

К сожалению, всё остальное крайне разочаровало. Медсестра не смогла правильно поставить иглу для капельницы с первой попытки, а со второй, судя по всему, задела нерв. Прошло три дня, а моя правая рука до сих пор не работает нормально.

Всего персонал сделал четыре попытки укола, но так и не смог ввести никакого лекарства, заявив, что мой организм «отторгает» уколы. Хотя никакого лечения фактически не было, мне всё равно выставили за него счёт.

Мне также назначили антибиотики — как мне показалось, без нормального диагноза и без внятного объяснения, зачем они нужны.

Через два часа я обратился в другую клинику. Там медики без всяких трудностей поставили капельницу с первой попытки, успешно ввели лекарство и правильно диагностировали моё состояние. Антибиотики в лечение не входили, что вызывает серьёзные сомнения в необходимости рецепта, который мне выписали в этой клинике.

Доктор был добр, но в целом качество медицинской помощи, которую я получил, было неприемлемым.'), text_de = COALESCE(text_de, 'Ich kam mit starken Schmerzen in diese Klinik und musste über eine Stunde warten, bevor ich drankam. Der Arzt war sehr freundlich und sprach Russisch, was ich zu schätzen wusste.

Leider war der Rest der Erfahrung äußerst enttäuschend. Die Krankenschwester schaffte es beim ersten Versuch nicht, die Infusionsnadel richtig zu legen, und beim zweiten Versuch traf sie offenbar einen Nerv. Drei Tage später funktioniert meine rechte Hand immer noch nicht normal.

Das Personal versuchte insgesamt viermal, eine Injektion zu setzen, konnte aber kein Medikament verabreichen und behauptete, mein Körper „verweigere“ die Injektionen. Obwohl tatsächlich keine Behandlung erfolgte, wurde sie mir trotzdem in Rechnung gestellt.

Außerdem wurden mir Antibiotika verschrieben, offenbar ohne richtige Diagnose und ohne klare Erklärung, warum sie nötig seien.

Zwei Stunden später ging ich in eine andere Klinik. Dort legte das medizinische Personal die Infusion ohne jede Schwierigkeit beim ersten Versuch, verabreichte das Medikament erfolgreich und stellte die richtige Diagnose. Antibiotika gehörten nicht zur Behandlung, was ernsthafte Zweifel an der Notwendigkeit des Rezepts weckt, das ich in dieser Klinik bekommen hatte.

Der Arzt war zwar freundlich, aber die Qualität der Versorgung insgesamt war inakzeptabel.'), text_tr = COALESCE(text_tr, 'Bu kliniğe şiddetli ağrıyla geldim ve muayene edilmeden önce bir saatten fazla beklemek zorunda kaldım. Doktor çok güler yüzlüydü ve Rusça konuşuyordu, bunu takdir ettim.

Ne yazık ki deneyimin geri kalanı son derece hayal kırıklığı yarattı. Hemşire serum iğnesini ilk denemede doğru takamadı, ikinci denemede ise bir sinire denk getirmiş gibi görünüyor. Üç gün geçmesine rağmen sağ elim hâlâ normal çalışmıyor.

Personel toplam dört kez enjeksiyon yapmayı denedi ama hiçbir ilacı veremedi; vücudumun enjeksiyonları "reddettiğini" iddia ettiler. Fiilen hiçbir tedavi uygulanmamasına rağmen bunun ücreti yine de bana kesildi.

Ayrıca, bana göre düzgün bir teşhis ve neden gerekli olduğuna dair net bir açıklama olmadan antibiyotik yazıldı.

İki saat sonra başka bir kliniğe gittim. Orada sağlık personeli serumu hiç zorlanmadan ilk denemede taktı, ilacı başarıyla verdi ve durumumu doğru teşhis etti. Tedavide antibiyotik yoktu; bu da bu klinikte bana yazılan reçetenin gerekliliği konusunda ciddi şüpheler doğuruyor.

Doktor nazik olsa da aldığım bakımın genel kalitesi kabul edilemezdi.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJ655v-VzVTRMRq8OGU_bGuPQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xOUlFUSkRNRXQwWkhONE5IcEdja2RNTUdzNExYYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Osoblje je ovdje zaista ljubazno i temeljno. Odlična usluga!'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Особље је овдје заиста љубазно и темељно. Одлична услуга!'), text_ru = COALESCE(text_ru, 'Персонал здесь по-настоящему доброжелательный и внимательный. Отличный сервис!'), text_de = COALESCE(text_de, 'Das Personal hier ist wirklich freundlich und gründlich. Toller Service!'), text_tr = COALESCE(text_tr, 'Buradaki personel gerçekten nazik ve titiz. Harika hizmet!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJ655v-VzVTRMRq8OGU_bGuPQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xWME9HZEtWbEJrWkZWYWJqSnpNRXBtYzJKVVZVRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Veliko hvala zaposlenima u klinici! Bili smo na odmoru. Došli smo na pregled sa sumnjom na upalu pluća i visokom temperaturom. Doktorka Dobrila Nikčević nas je pregledala, uzela analize i propisala odgovarajuću terapiju. Već uveče je bilo lakše. Veliko hvala medicinskim sestrama!'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Велико хвала запосленима у клиници! Били смо на одмору. Дошли смо на преглед са сумњом на упалу плућа и високом температуром. Докторка Добрила Никчевић нас је прегледала, узела анализе и прописала одговарајућу терапију. Већ увече је било лакше. Велико хвала медицинским сестрама!'), text_en = COALESCE(text_en, 'Many thanks to the clinic staff! We were on vacation. We came in with suspected pneumonia and a high fever. Dr. Dobrila Nikčević examined us, took tests and prescribed the right treatment. By the evening things were already better. Many thanks to the nurses!'), text_de = COALESCE(text_de, 'Vielen Dank an das Team der Klinik! Wir waren im Urlaub. Wir kamen mit Verdacht auf Lungenentzündung und hohem Fieber. Dr. Dobrila Nikčević hat die Untersuchung durchgeführt, Proben genommen und eine kompetente Behandlung verordnet. Schon am Abend ging es besser. Vielen Dank auch an die Krankenschwestern!'), text_tr = COALESCE(text_tr, 'Klinik çalışanlarına çok teşekkürler! Tatildeydik. Zatürre şüphesi ve yüksek ateşle muayeneye geldik. Dr. Dobrila Nikčević muayene etti, tahlil aldı ve doğru tedaviyi verdi. Daha akşam olmadan rahatladık. Hemşirelere de çok teşekkürler!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJ655v-VzVTRMRq8OGU_bGuPQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xjM1ZIUlpPRzgzWlZadVIzRnNhR2sxVW14RU1GRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Dobra klinika. Stručni specijalisti, ali 4 zvjezdice zbog doktora Velimira Miloševića. Klinika treba da preispita cijene njegovih konsultacija, jer za cijenu jedne konsultacije možete kupiti pretplatu na ChatGPT, saznati preciznije i dobiti zaista zainteresovano mišljenje. Ostali ljekari su veoma dobri.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Добра клиника. Стручни специјалисти, али 4 звјездице због доктора Велимира Милошевића. Клиника треба да преиспита цијене његових консултација, јер за цијену једне консултације можете купити претплату на ChatGPT, сазнати прецизније и добити заиста заинтересовано мишљење. Остали љекари су веома добри.'), text_en = COALESCE(text_en, 'A good clinic. Competent specialists, but 4 stars because of Dr. Velimir Milošević. The clinic should reconsider the prices of his consultations, because for the price of one consultation you can buy a ChatGPT subscription, get more accurate information and a genuinely engaged opinion. The other doctors are very good.'), text_de = COALESCE(text_de, 'Eine gute Klinik. Kompetente Fachärzte, aber 4 Sterne wegen Dr. Velimir Milošević. Die Klinik sollte die Preise für seine Konsultationen überdenken, denn für den Preis einer Konsultation kann man ein ChatGPT-Abo kaufen, genauere Auskünfte bekommen und eine wirklich engagierte Meinung erhalten. Die übrigen Ärzte sind sehr gut.'), text_tr = COALESCE(text_tr, 'İyi bir klinik. Uzmanlar yetkin, ancak Dr. Velimir Milošević yüzünden 4 yıldız. Klinik onun konsültasyon ücretlerini yeniden gözden geçirmeli; çünkü bir konsültasyon ücretine ChatGPT aboneliği alıp daha doğru bilgi ve gerçekten ilgili bir görüş edinebilirsiniz. Diğer doktorlar çok iyi.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJ655v-VzVTRMRq8OGU_bGuPQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT25kVGRrbGZVMHh4U2xOUU1sOWxkMlk0TUY5M2VVRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома смо разочарани организацијом рада клинике.

Били смо наручени на преглед код хирурга и посебно смо допутовали из Бара у Будву. Током пута администраторка је била у контакту с нама и знала је да долазимо на заказани преглед.

Када смо стигли у клинику, сазнали смо да је докторица већ отишла кући. Нико нас није унапријед обавијестио о отказивању прегледа или промјени распореда. Због тога смо изгубили неколико сати на путовање и остали без потребне медицинске помоћи.

Сматрамо да је овакав однос према пацијентима неприхватљив. Ако се преглед отказује, посебно када пацијент долази из другог града, клиника је дужна да га благовремено обавијести. Надамо се да ће руководство обратити пажњу на ову ситуацију и предузети мјере за побољшање организације рада и односа према пацијентима.'), text_en = COALESCE(text_en, 'We are very disappointed with how the clinic is organized.

We had an appointment with a surgeon and traveled specially from Bar to Budva. During the trip, the administrator was in contact with us and knew we were coming for the scheduled appointment.

When we arrived at the clinic, we found out that the doctor had already gone home. No one informed us in advance that the appointment was canceled or the schedule changed. Because of this, we lost several hours traveling and were left without the medical help we needed.

We believe this treatment of patients is unacceptable. If an appointment is canceled, especially when the patient is coming from another city, the clinic is obliged to notify them in time. We hope the management will pay attention to this situation and take steps to improve the organization of work and the treatment of patients.'), text_ru = COALESCE(text_ru, 'Мы очень разочарованы организацией работы клиники.

Мы были записаны на приём к хирургу и специально приехали из Бара в Будву. Во время поездки администратор была с нами на связи и знала, что мы едем на назначенный приём.

Когда мы приехали в клинику, оказалось, что врач уже ушла домой. Никто заранее не предупредил нас ни об отмене приёма, ни об изменении расписания. Из-за этого мы потратили несколько часов на дорогу и остались без необходимой медицинской помощи.

Считаем такое отношение к пациентам недопустимым. Если приём отменяется, особенно когда пациент едет из другого города, клиника обязана своевременно его об этом уведомить. Надеемся, что руководство обратит внимание на эту ситуацию и примет меры, чтобы улучшить организацию работы и отношение к пациентам.'), text_de = COALESCE(text_de, 'Wir sind von der Organisation der Klinik sehr enttäuscht.

Wir hatten einen Termin bei einer Chirurgin und sind extra von Bar nach Budva gefahren. Während der Fahrt stand die Mitarbeiterin am Empfang mit uns in Kontakt und wusste, dass wir zum vereinbarten Termin kommen.

Als wir in der Klinik ankamen, erfuhren wir, dass die Ärztin bereits nach Hause gegangen war. Niemand hatte uns im Voraus über die Absage des Termins oder eine Änderung des Zeitplans informiert. Dadurch haben wir mehrere Stunden mit der Anreise verloren und keine medizinische Hilfe bekommen, die wir gebraucht hätten.

Wir halten einen solchen Umgang mit Patienten für inakzeptabel. Wird ein Termin abgesagt, insbesondere wenn der Patient aus einer anderen Stadt anreist, ist die Klinik verpflichtet, ihn rechtzeitig zu informieren. Wir hoffen, dass die Leitung diese Situation zur Kenntnis nimmt und Maßnahmen ergreift, um die Arbeitsorganisation und den Umgang mit Patienten zu verbessern.'), text_tr = COALESCE(text_tr, 'Kliniğin iş organizasyonundan çok hayal kırıklığına uğradık.

Bir cerrahtan randevumuz vardı ve özellikle Bar\'dan Budva\'ya geldik. Yolculuk boyunca resepsiyon görevlisi bizimle iletişim halindeydi ve planlanan randevuya geldiğimizi biliyordu.

Kliniğe vardığımızda doktorun çoktan eve gittiğini öğrendik. Kimse bize randevunun iptal edildiğini ya da programın değiştiğini önceden bildirmedi. Bu yüzden yolda birkaç saat kaybettik ve ihtiyaç duyduğumuz tıbbi yardımı alamadık.

Hastalara bu şekilde davranılmasını kabul edilemez buluyoruz. Bir randevu iptal ediliyorsa, özellikle hasta başka bir şehirden geliyorsa, klinik onu zamanında bilgilendirmekle yükümlüdür. Yönetimin bu duruma dikkat etmesini ve iş organizasyonunu ve hastalara yaklaşımı iyileştirmek için önlem almasını umuyoruz.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJ655v-VzVTRMRq8OGU_bGuPQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT2sxTmRFOXVaM2szTUdKbGNEQlliM0JPVnpSV0xXYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'DIVNI SPECIJALISTI!!! PREKRASNI, DOBRI LJUDI!!! OGROMNA ZAHVALNOST MEDICINSKOJ SESTRI NATALIJI I SVIM ZDRAVSTVENIM RADNICIMA OVE DIVNE ZDRAVSTVENE USTANOVE!!!'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'ДИВНИ СПЕЦИЈАЛИСТИ!!! ПРЕКРАСНИ, ДОБРИ ЉУДИ!!! ОГРОМНА ЗАХВАЛНОСТ МЕДИЦИНСКОЈ СЕСТРИ НАТАЛИЈИ И СВИМ ЗДРАВСТВЕНИМ РАДНИЦИМА ОВЕ ДИВНЕ ЗДРАВСТВЕНЕ УСТАНОВЕ!!!'), text_en = COALESCE(text_en, 'WONDERFUL SPECIALISTS!!! LOVELY, KIND PEOPLE!!! HUGE THANKS TO NURSE NATALIA AND ALL THE MEDICAL STAFF OF THIS WONDERFUL MEDICAL FACILITY!!!'), text_de = COALESCE(text_de, 'WUNDERBARE FACHÄRZTE!!! TOLLE, HERZENSGUTE MENSCHEN!!! EIN RIESIGES DANKESCHÖN AN KRANKENSCHWESTER NATALIA UND DAS GESAMTE MEDIZINISCHE PERSONAL DIESER WUNDERBAREN EINRICHTUNG!!!'), text_tr = COALESCE(text_tr, 'HARİKA UZMANLAR!!! MÜKEMMEL, İYİ KALPLİ İNSANLAR!!! HEMŞİRE NATALIA\'YA VE BU HARİKA SAĞLIK KURULUŞUNUN TÜM SAĞLIK ÇALIŞANLARINA SONSUZ TEŞEKKÜRLER!!!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJ655v-VzVTRMRq8OGU_bGuPQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT20wMWRURndTVjlqVFRCTE0wOU5XSEpuY1UxdVZsRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Изузетно љубазна и пријатна докторка. Непријатну ситуацију на одмору (дијете је нагазило морског јежа) претворила је у доживљај којег ћемо се сјећати уз осмијех.'), text_en = COALESCE(text_en, 'An exceptionally kind and pleasant doctor. She turned an unpleasant situation on our vacation (our child stepped on a sea urchin) into an experience we will remember with a laugh.'), text_ru = COALESCE(text_ru, 'Исключительно доброжелательная и приятная врач. Неприятную ситуацию на отдыхе (ребёнок наступил на морского ежа) она превратила в приключение, которое мы будем вспоминать со смехом.'), text_de = COALESCE(text_de, 'Eine außergewöhnlich freundliche und angenehme Ärztin. Eine unangenehme Situation im Urlaub (unser Kind war auf einen Seeigel getreten) hat sie in ein Erlebnis verwandelt, an das wir uns lachend erinnern werden.'), text_tr = COALESCE(text_tr, 'Son derece nazik ve hoş bir doktor. Tatildeki tatsız bir durumu (çocuğumuz deniz kestanesine bastı) gülerek hatırlayacağımız bir anıya dönüştürdü.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21wWWJrWTVNbk4yVm5ZMU1GaHdYM1oyTTBVMU1WRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Брзи, љубазни, лако доступни и од велике помоћи. ПРЕПОРУЧУЈЕМ ОД СРЦА ❤️'), text_en = COALESCE(text_en, 'Fast, friendly, easy to reach and a great help. I RECOMMEND THEM WHOLEHEARTEDLY ❤️'), text_ru = COALESCE(text_ru, 'Быстрые, вежливые, легко доступные и очень помогли. РЕКОМЕНДУЮ ОТ ВСЕГО СЕРДЦА ❤️'), text_de = COALESCE(text_de, 'Schnell, freundlich, gut erreichbar und eine große Hilfe. ICH EMPFEHLE SIE VON HERZEN ❤️'), text_tr = COALESCE(text_tr, 'Hızlı, nazik, kolay ulaşılabilir ve çok yardımcı oldular. GÖNÜLDEN TAVSİYE EDİYORUM ❤️') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tjeWFWUlhialJIY2tVd2IyeFphSFJMVVhOalZsRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Дивна докторка Јелена је дошла у року од 20 минута и ријешила проблем. Све похвале за Medical Vranes, брзи, темељни, стручни и пријатни.'), text_en = COALESCE(text_en, 'The wonderful Dr. Jelena arrived within 20 minutes and solved the problem. All praise for Medical Vranes — fast, thorough, professional and pleasant.'), text_ru = COALESCE(text_ru, 'Замечательная доктор Елена приехала в течение 20 минут и решила проблему. Все похвалы Medical Vranes — быстрые, обстоятельные, профессиональные и приятные.'), text_de = COALESCE(text_de, 'Die wunderbare Ärztin Jelena kam innerhalb von 20 Minuten und hat das Problem gelöst. Großes Lob an Medical Vranes – schnell, gründlich, kompetent und angenehm.'), text_tr = COALESCE(text_tr, 'Harika doktor Jelena 20 dakika içinde geldi ve sorunu çözdü. Medical Vranes\'e tüm övgüler: hızlı, titiz, uzman ve güler yüzlü.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21nd2R6aDBVR0ZqV0dSaVRGOUxkRW90Y25sSlYwRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Brza i profesionalna usluga.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Брза и професионална услуга.'), text_en = COALESCE(text_en, 'Fast and professional service.'), text_ru = COALESCE(text_ru, 'Быстрое и профессиональное обслуживание.'), text_de = COALESCE(text_de, 'Schneller und professioneller Service.'), text_tr = COALESCE(text_tr, 'Hızlı ve profesyonel hizmet.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2paMVF6SkJNa3d6Y0RCVU1XUnhZVk01YTNWTWRGRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Презадовољна услугом. Свака препорука!'), text_en = COALESCE(text_en, 'Extremely satisfied with the service. Highly recommended!'), text_ru = COALESCE(text_ru, 'Более чем довольна обслуживанием. Рекомендую!'), text_de = COALESCE(text_de, 'Mit dem Service äußerst zufrieden. Absolut empfehlenswert!'), text_tr = COALESCE(text_tr, 'Hizmetten son derece memnun kaldım. Kesinlikle tavsiye ederim!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xZeVlUVlFjSE4yT1ZWdFprOVZOWEp1VVVSaU5GRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Medicinska pomoć je organizovana brzo i profesionalno.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Медицинска помоћ је организована брзо и професионално.'), text_ru = COALESCE(text_ru, 'Медицинскую помощь организовали быстро и профессионально.'), text_de = COALESCE(text_de, 'Die medizinische Hilfe wurde schnell und professionell organisiert.'), text_tr = COALESCE(text_tr, 'Tıbbi yardım hızlı ve profesyonel şekilde organize edildi.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25walgyTkdXRVpZVW13M1VFdDZUekpwZUhoU2RVRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Брзо су реаговали на позив, све ријешено у року од пола сата 👍🏾'), text_en = COALESCE(text_en, 'They responded to the call quickly, everything was sorted within half an hour 👍🏾'), text_ru = COALESCE(text_ru, 'Быстро отреагировали на вызов, всё решили в течение получаса 👍🏾'), text_de = COALESCE(text_de, 'Sie haben schnell auf den Anruf reagiert, alles war innerhalb einer halben Stunde erledigt 👍🏾'), text_tr = COALESCE(text_tr, 'Çağrıya hızlıca yanıt verdiler, her şey yarım saat içinde çözüldü 👍🏾') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tGTFNrcE1ZelpEV2tOWE1WVTBMV2hVWm1RNVltYxAB';
