UPDATE reviews SET text_sr = COALESCE(text_sr, 'Odlična ljekarska pomoć, bez problema u komunikaciji.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Одлична љекарска помоћ, без проблема у комуникацији.'), text_en = COALESCE(text_en, 'Great medical help, no problems with communication.'), text_ru = COALESCE(text_ru, 'Отличная врачебная помощь, никаких проблем с общением.'), text_de = COALESCE(text_de, 'Super ärztliche Hilfe, keine Verständigungsprobleme.'), text_tr = COALESCE(text_tr, 'Harika tıbbi yardım, iletişimde hiçbir sorun yok.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21OTWRFYzFSSFp5YmpOYVF6ZEVNbkJMZWprMWFuYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Дивни, љубазни, стручни'), text_en = COALESCE(text_en, 'Wonderful, kind, professional'), text_ru = COALESCE(text_ru, 'Замечательные, вежливые, профессиональные'), text_de = COALESCE(text_de, 'Wunderbar, freundlich, kompetent'), text_tr = COALESCE(text_tr, 'Harika, nazik, işinin ehli') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21KaU1GbHhWR0YxUWxsek1ucHhUbEozT1VodVEwRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Имали смо путно осигурање. Након што смо контактирали осигурање, јавили су нам се у року од 5 минута и љекар је дошао у наш смјештај у наредних сат времена. Такође, иста докторка је дошла код нас у смјештај и на контролни преглед — љубазна, пријатна с дјецом, прецизна и тачна, и прије свега човјек. Све похвале за докторку Јелену. Били смо смјештени у Улцињу, на Великој плажи.'), text_en = COALESCE(text_en, 'We had travel insurance. After we contacted the insurer, they got back to us within 5 minutes, and a doctor came to our accommodation within the next hour. The same doctor also came to our accommodation for the follow-up check — kind, great with the children, thorough and punctual, and above all a good human being. All praise to Doctor Jelena. We were staying in Ulcinj, on Velika Plaža.'), text_ru = COALESCE(text_ru, 'У нас была туристическая страховка. После обращения в страховую с нами связались в течение 5 минут, и врач приехал к нам по месту проживания в течение часа. Та же докторша приезжала к нам и на контрольный осмотр — вежливая, приятная в общении с детьми, внимательная и пунктуальная, а главное — хороший человек. Огромная благодарность доктору Елене. Мы жили в Ульцине, на Великом пляже.'), text_de = COALESCE(text_de, 'Wir hatten eine Reiseversicherung. Nachdem wir die Versicherung kontaktiert hatten, meldete man sich innerhalb von 5 Minuten bei uns, und innerhalb der nächsten Stunde kam eine Ärztin in unsere Unterkunft. Dieselbe Ärztin kam auch zur Kontrolluntersuchung zu uns in die Unterkunft — freundlich, lieb mit den Kindern, gründlich und pünktlich und vor allem ein guter Mensch. Großes Lob an Ärztin Jelena. Wir waren in Ulcinj am Velika Plaža untergebracht.'), text_tr = COALESCE(text_tr, 'Seyahat sigortamız vardı. Sigorta şirketiyle iletişime geçtikten sonra 5 dakika içinde bize dönüş yaptılar ve bir saat içinde doktor kaldığımız yere geldi. Aynı doktor kontrol muayenesi için de yanımıza geldi — nazik, çocuklarla çok iyi anlaşan, titiz ve dakik, her şeyden önce iyi bir insan. Doktor Jelena\'ya çok teşekkürler. Ülgün\'de, Velika Plaža\'da kalıyorduk.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2s4ek5HNWlaRTloTjFwVmMwaENaR0pLWmxWaFNGRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Јако нељубазни. Даш им све податке, а послије прегледа опет морају све то да потврде, плус се наплаћује иако имам осигурање. Може да се рефундира, али боље да се плати. Било ми је заказано, а сат и по сам чекала преглед. Незадовољна.'), text_en = COALESCE(text_en, 'Very rude. You give them all your details, and after the examination they have to confirm everything again, plus you get charged even though I have insurance. It can be refunded, but it\'s better to pay. I had an appointment and still waited an hour and a half to be seen. Dissatisfied.'), text_ru = COALESCE(text_ru, 'Очень невежливые. Даёшь им все данные, а после осмотра они снова должны всё это подтверждать, плюс берут оплату, хотя у меня есть страховка. Можно получить возмещение, но лучше заплатить. У меня была запись, и всё равно я полтора часа ждала приёма. Недовольна.'), text_de = COALESCE(text_de, 'Sehr unfreundlich. Man gibt ihnen alle Daten, und nach der Untersuchung müssen sie alles noch einmal bestätigen, außerdem wird bezahlt, obwohl ich versichert bin. Es kann erstattet werden, aber besser ist es, zu bezahlen. Ich hatte einen Termin und habe trotzdem anderthalb Stunden auf die Untersuchung gewartet. Unzufrieden.'), text_tr = COALESCE(text_tr, 'Hiç nazik değiller. Onlara tüm bilgilerinizi veriyorsunuz, muayeneden sonra yine her şeyi teyit etmeleri gerekiyor, üstelik sigortam olmasına rağmen ücret alınıyor. Geri ödenebiliyor ama ödemek daha iyiymiş. Randevum vardı, yine de muayene için bir buçuk saat bekledim. Memnun değilim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21seVVrb3pUbkJyZDFSRGF6RjBabFExVTFVelZIYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Изузетно љубазни, брзи и ефикасни. По договору су нас сачекали испред ординације и прегледали дијете. Докторка веома пријатна. Све обављено преко путног осигурања. За сваку похвалу.'), text_en = COALESCE(text_en, 'Extremely kind, fast and efficient. As agreed, they waited for us in front of the practice and examined our child. The doctor was very pleasant. Everything was handled through travel insurance. Praiseworthy in every way.'), text_ru = COALESCE(text_ru, 'Исключительно вежливые, быстрые и эффективные. Как договорились, нас встретили у входа в клинику и осмотрели ребёнка. Докторша очень приятная. Всё оформили через туристическую страховку. Заслуживают всяческих похвал.'), text_de = COALESCE(text_de, 'Äußerst freundlich, schnell und effizient. Wie vereinbart haben sie vor der Praxis auf uns gewartet und unser Kind untersucht. Die Ärztin war sehr angenehm. Alles lief über die Reiseversicherung. Rundum lobenswert.'), text_tr = COALESCE(text_tr, 'Son derece nazik, hızlı ve verimliler. Anlaştığımız gibi muayenehanenin önünde bizi beklediler ve çocuğumuzu muayene ettiler. Doktor hanım çok güler yüzlüydü. Her şey seyahat sigortası üzerinden halledildi. Her türlü övgüyü hak ediyorlar.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pKeE9HNUNhRkpvYlhOMGFFc3hiREU1VkVkVFIyYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, '★★★★★

Bila sam na odmoru u Albaniji, u Valoni, kada sam dobila tešku crijevnu infekciju i bila mi je potrebna ljekarska pomoć. Kontaktirala sam svoje osiguravajuće društvo PZU i u roku od otprilike dva sata obradili su moj slučaj i kontaktirali Medical Vranes.

Ljekar iz klinike došao je kod mene tačno u dogovoreno vrijeme, samo 30 minuta kasnije. Sljedećeg dana poslali su me u svoju partnersku laboratoriju u Albaniji, gdje sam primljena bez ikakvog čekanja. Rezultati analiza bili su gotovi za nekoliko sati, a narednog dana ponovo me je posjetio drugi ljekar iz klinike.

Sve je riješeno veoma brzo, jasno i profesionalno. Tim je bio ljubazan i od pomoći tokom cijelog procesa.

Odlična usluga, toplo preporučujem!'), text_sr_cyrl = COALESCE(text_sr_cyrl, '★★★★★

Била сам на одмору у Албанији, у Валони, када сам добила тешку цријевну инфекцију и била ми је потребна љекарска помоћ. Контактирала сам своје осигуравајуће друштво PZU и у року од отприлике два сата обрадили су мој случај и контактирали Medical Vranes.

Љекар из клинике дошао је код мене тачно у договорено вријеме, само 30 минута касније. Сљедећег дана послали су ме у своју партнерску лабораторију у Албанији, гдје сам примљена без икаквог чекања. Резултати анализа били су готови за неколико сати, а наредног дана поново ме је посјетио други љекар из клинике.

Све је ријешено веома брзо, јасно и професионално. Тим је био љубазан и од помоћи током цијелог процеса.

Одлична услуга, топло препоручујем!'), text_ru = COALESCE(text_ru, '★★★★★

Я отдыхала в Албании, во Влёре, когда у меня началась тяжёлая кишечная инфекция и понадобилась медицинская помощь. Я связалась со своей страховой компанией PZU, и примерно за два часа они обработали мой случай и связались с Medical Vranes.

Врач из клиники приехал ко мне точно в условленное время, всего через 30 минут. На следующий день меня направили в их партнёрскую лабораторию в Албании, где меня приняли без всякого ожидания. Результаты анализов были готовы через несколько часов, а на следующий день ко мне снова приехал другой врач из клиники.

Всё было сделано очень быстро, понятно и профессионально. Команда была дружелюбной и отзывчивой на всех этапах.

Отличный сервис, очень рекомендую!'), text_de = COALESCE(text_de, '★★★★★

Ich war im Urlaub in Albanien, in Vlora, als ich eine schwere Magen-Darm-Infektion bekam und ärztliche Hilfe brauchte. Ich kontaktierte meine Versicherung PZU, und innerhalb von etwa zwei Stunden bearbeitete sie meinen Fall und kontaktierte Medical Vranes.

Ein Arzt der Klinik kam genau zur vereinbarten Zeit zu mir, nur 30 Minuten später. Am nächsten Tag schickten sie mich in ihr Partnerlabor in Albanien, wo ich ohne jede Wartezeit drankam. Die Testergebnisse lagen innerhalb weniger Stunden vor, und am folgenden Tag besuchte mich erneut ein anderer Arzt der Klinik.

Alles wurde sehr schnell, klar und professionell abgewickelt. Das Team war während des gesamten Ablaufs freundlich und hilfsbereit.

Ausgezeichneter Service, sehr zu empfehlen!'), text_tr = COALESCE(text_tr, '★★★★★

Arnavutluk\'ta, Avlonya\'da tatildeyken ağır bir mide-bağırsak enfeksiyonu geçirdim ve tıbbi yardıma ihtiyacım oldu. Sigorta şirketim PZU ile iletişime geçtim; yaklaşık iki saat içinde dosyamı işleme alıp Medical Vranes ile iletişim kurdular.

Klinikten bir doktor tam kararlaştırılan saatte, sadece 30 dakika sonra yanıma geldi. Ertesi gün beni Arnavutluk\'taki anlaşmalı laboratuvarlarına gönderdiler; orada hiç beklemeden ilgilenildim. Test sonuçları birkaç saat içinde hazırdı ve bir sonraki gün klinikten başka bir doktor beni tekrar ziyaret etti.

Her şey çok hızlı, anlaşılır ve profesyonelce halledildi. Ekip süreç boyunca güler yüzlü ve yardımseverdi.

Mükemmel hizmet, kesinlikle tavsiye ederim!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25SbWFWUkpXR3MwY0dGNWFGcHRRMlZrT1VaRE5HYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Odlična medicinska njega; od samog dolaska naišli smo na veliko razumijevanje, a medicinske sestre i osoblje bili su ljubazni i empatični. Konsultacija je protekla bez problema, a sve preporuke su nam jasno objašnjene :)'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Одлична медицинска њега; од самог доласка наишли смо на велико разумијевање, а медицинске сестре и особље били су љубазни и емпатични. Консултација је протекла без проблема, а све препоруке су нам јасно објашњене :)'), text_ru = COALESCE(text_ru, 'Отличная медицинская помощь: с самого прихода к нам отнеслись с большим пониманием, медсёстры и персонал были приветливыми и чуткими. Консультация прошла гладко, а все рекомендации нам понятно объяснили :)'), text_de = COALESCE(text_de, 'Hervorragende medizinische Versorgung; vom ersten Moment an begegnete man uns mit großem Verständnis, und die Pflegekräfte und das Personal waren freundlich und einfühlsam. Die Beratung verlief reibungslos, und alle Empfehlungen wurden uns klar erklärt :)'), text_tr = COALESCE(text_tr, 'Mükemmel tıbbi bakım; geldiğimiz andan itibaren büyük bir anlayışla karşılandık, hemşireler ve personel güler yüzlü ve empatikti. Konsültasyon sorunsuz geçti ve tüm öneriler bize açıkça anlatıldı :)') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21kMVNqbDJNVFZ5YjA1eU5UWlpNRGxXYmxoRlkxRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све је било брзо, професионално и организовано. Особље љубазно, а све што нам је било потребно завршили смо без чекања и компликација. Све препоруке!'), text_en = COALESCE(text_en, 'Everything was fast, professional and well organized. The staff were kind, and we got everything we needed done without waiting or complications. Highly recommended!'), text_ru = COALESCE(text_ru, 'Всё было быстро, профессионально и организованно. Персонал вежливый, а всё необходимое мы сделали без ожидания и сложностей. Рекомендую!'), text_de = COALESCE(text_de, 'Alles lief schnell, professionell und gut organisiert. Das Personal war freundlich, und alles, was wir brauchten, haben wir ohne Wartezeit und Komplikationen erledigt. Absolut empfehlenswert!'), text_tr = COALESCE(text_tr, 'Her şey hızlı, profesyonel ve düzenliydi. Personel nazikti; ihtiyacımız olan her şeyi beklemeden ve sorunsuz hallettik. Kesinlikle tavsiye ederim!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tSUFZUWnRVRFZJUkZKQ2VuZ3hSblZSV1hGNFYzYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све похвале за професионалност и брзину услуге! Докторка Јелена нам је дошла у смјештај да прегледа бебу и препише терапију!'), text_en = COALESCE(text_en, 'All praise for the professionalism and speed of service! Doctor Jelena came to our accommodation to examine the baby and prescribe treatment!'), text_ru = COALESCE(text_ru, 'Огромное спасибо за профессионализм и быстроту обслуживания! Доктор Елена приехала к нам по месту проживания, чтобы осмотреть малыша и назначить лечение!'), text_de = COALESCE(text_de, 'Großes Lob für die Professionalität und den schnellen Service! Ärztin Jelena kam zu uns in die Unterkunft, um das Baby zu untersuchen und eine Behandlung zu verschreiben!'), text_tr = COALESCE(text_tr, 'Profesyonellikleri ve hızlı hizmetleri için tebrikler! Doktor Jelena bebeği muayene etmek ve tedavi yazmak için kaldığımız yere geldi!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xCWU4ydHZiRlJ5TlVwTFNUQnRXR2hCZWtSTVFtYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Професионалан приступ и брз одзив, уз приједлог посјете доктора на нашој локацији. Све похвале за ординацију Vraneš.'), text_en = COALESCE(text_en, 'A professional approach and a quick response, including the offer of a doctor\'s visit at our location. All praise to the Vraneš practice.'), text_ru = COALESCE(text_ru, 'Профессиональный подход и быстрый отклик, а также предложение вызвать врача к нам на место. Огромное спасибо клинике Vraneš.'), text_de = COALESCE(text_de, 'Professionelles Vorgehen und schnelle Reaktion, inklusive des Angebots eines Arztbesuchs bei uns vor Ort. Großes Lob an die Praxis Vraneš.'), text_tr = COALESCE(text_tr, 'Profesyonel yaklaşım ve hızlı geri dönüş; ayrıca doktorun bulunduğumuz yere gelmesi önerildi. Vraneš muayenehanesine çok teşekkürler.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21OTGFrSjFlazQxUlhwUExVazNlRlV0Vm5CV2JVRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Изузетно брзо, професионално. Свака част. Живјели'), text_en = COALESCE(text_en, 'Extremely fast, professional. Hats off. Cheers'), text_ru = COALESCE(text_ru, 'Очень быстро, профессионально. Респект. Всего доброго'), text_de = COALESCE(text_de, 'Äußerst schnell, professionell. Hut ab. Prost'), text_tr = COALESCE(text_tr, 'Son derece hızlı, profesyonel. Helal olsun. Şerefe') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xCbGNYTTFNSEl3TjJONFFYSnVPWEF3U0U5MU1VRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Došao je odličan ljekar i pomogao mom sinu!!!'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Дошао је одличан љекар и помогао мом сину!!!'), text_en = COALESCE(text_en, 'An excellent doctor came and helped my son!!!'), text_de = COALESCE(text_de, 'Ein ausgezeichneter Arzt kam und half meinem Sohn!!!'), text_tr = COALESCE(text_tr, 'Mükemmel bir doktor geldi ve oğluma yardım etti!!!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT200NVpYZFFZVGgwVlhaT1dHcFVka3hQUjNwdmExRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Након пријаве осигурању, докторка је била код нас у року од 40 минута, што нам је изузетно значило. Била је изузетна, љубазна и професионална. Све похвале!'), text_en = COALESCE(text_en, 'After we notified the insurance company, the doctor was with us within 40 minutes, which meant a great deal to us. She was outstanding, kind and professional. All praise!'), text_ru = COALESCE(text_ru, 'После обращения в страховую докторша была у нас уже через 40 минут, что для нас было очень важно. Она была замечательной, вежливой и профессиональной. Огромное спасибо!'), text_de = COALESCE(text_de, 'Nachdem wir es der Versicherung gemeldet hatten, war die Ärztin innerhalb von 40 Minuten bei uns, was uns sehr viel bedeutet hat. Sie war hervorragend, freundlich und professionell. Großes Lob!'), text_tr = COALESCE(text_tr, 'Sigortaya bildirdikten sonra doktor hanım 40 dakika içinde yanımızdaydı; bu bizim için çok önemliydi. Harikaydı, nazik ve profesyoneldi. Çok teşekkürler!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25NMGNFUklSMmhKY2xsNk0wZExRWGhTWTBkMGQzYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Одлична и брза услуга, љубазни доктори! Др Јелена је феноменална!'), text_en = COALESCE(text_en, 'Excellent and fast service, kind doctors! Dr. Jelena is phenomenal!'), text_ru = COALESCE(text_ru, 'Отличное и быстрое обслуживание, вежливые врачи! Доктор Елена просто феноменальная!'), text_de = COALESCE(text_de, 'Ausgezeichneter und schneller Service, freundliche Ärzte! Dr. Jelena ist phänomenal!'), text_tr = COALESCE(text_tr, 'Mükemmel ve hızlı hizmet, nazik doktorlar! Dr. Jelena olağanüstü!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2w5V2FteHNlSGN0YjIxbGExUkhRM2RIWjJJMFMyYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Posjetili smo kliniku s kćerkom dok smo putovali, a bolest u drugoj zemlji je uvijek veoma stresna. Trebalo nam je malo vremena da pronađemo ulaz, ali sve ostalo je proteklo bez problema. Brzo su nas primili, ljekar ju je temeljno pregledao, saslušao sve naše brige i dao jasne i djelotvorne preporuke kako bismo se bezbjedno oporavili bez potrebe za hospitalizacijom. Hvala vam puno na brizi i podršci!'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Посјетили смо клинику с кћерком док смо путовали, а болест у другој земљи је увијек веома стресна. Требало нам је мало времена да пронађемо улаз, али све остало је протекло без проблема. Брзо су нас примили, љекар ју је темељно прегледао, саслушао све наше бриге и дао јасне и дјелотворне препоруке како бисмо се безбједно опоравили без потребе за хоспитализацијом. Хвала вам пуно на бризи и подршци!'), text_ru = COALESCE(text_ru, 'Мы обратились в клинику с дочерью во время путешествия, а болеть в другой стране — это всегда большой стресс. Мы не сразу нашли вход, но в остальном всё прошло гладко. Нас быстро приняли, врач тщательно осмотрел дочь, выслушал все наши опасения и дал чёткие и действенные рекомендации, чтобы мы могли спокойно поправиться без госпитализации. Большое спасибо за заботу и поддержку!'), text_de = COALESCE(text_de, 'Wir waren mit unserer Tochter auf Reisen in der Klinik, und krank zu sein in einem anderen Land ist immer sehr belastend. Wir haben etwas gebraucht, um den Eingang zu finden, aber alles andere lief reibungslos. Wir kamen schnell dran, der Arzt hat sie gründlich untersucht, sich all unsere Sorgen angehört und klare, wirksame Empfehlungen gegeben, damit wir uns ohne Krankenhausaufenthalt sicher erholen konnten. Vielen Dank für Ihre Fürsorge und Unterstützung!'), text_tr = COALESCE(text_tr, 'Seyahat ederken kızımla kliniğe gittik; başka bir ülkede hastalanmak her zaman çok stresli. Girişi bulmamız biraz zaman aldı ama geri kalan her şey sorunsuz geçti. Hemen ilgilenildik, doktor kızımı ayrıntılı muayene etti, tüm endişelerimizi dinledi ve hastaneye yatmaya gerek kalmadan güvenle iyileşebilmemiz için açık ve etkili önerilerde bulundu. İlginiz ve desteğiniz için çok teşekkür ederiz!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pNeGJFSnRaRkJETlU4d1lVeENORTlmWkhvMWFtYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све препоруке. Брзи, поуздани, ријешили су нам све брзо.'), text_en = COALESCE(text_en, 'Highly recommended. Fast, reliable, they sorted everything out for us quickly.'), text_ru = COALESCE(text_ru, 'Рекомендую. Быстрые, надёжные, всё нам быстро решили.'), text_de = COALESCE(text_de, 'Absolut empfehlenswert. Schnell, zuverlässig, sie haben alles schnell für uns geregelt.'), text_tr = COALESCE(text_tr, 'Kesinlikle tavsiye ederim. Hızlı, güvenilir; her şeyi çabucak hallettiler.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25CVWJUTjVWMFJzT1VkbWNIUkphelZSVlhoMWJWRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Obratili smo se (u avgustu 2026) s bolesnim dječakom (preko osiguranja). Doktorka koja nas je pregledala pokazala se kao odličan stručnjak i osjećajna osoba. Prepisala je sinu potrebnu terapiju, napisala recept za lijekove i zajedno s nama otišla do apoteke i pomogla nam da ih kupimo.
Potpuno smo zadovoljni pregledom i veoma zahvalni!
Ovu zdravstvenu ustanovu toplo preporučujemo!'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Обратили смо се (у августу 2026) с болесним дјечаком (преко осигурања). Докторка која нас је прегледала показала се као одличан стручњак и осјећајна особа. Преписала је сину потребну терапију, написала рецепт за лијекове и заједно с нама отишла до апотеке и помогла нам да их купимо.
Потпуно смо задовољни прегледом и веома захвални!
Ову здравствену установу топло препоручујемо!'), text_en = COALESCE(text_en, 'We came in (in August 2026) with our sick boy (on insurance). The doctor who examined us turned out to be an excellent specialist and a caring person. She prescribed the necessary treatment for our son, wrote a prescription for the medicines, and even walked with us to the pharmacy and helped us buy them.
We were completely satisfied with the appointment and are very grateful!
We highly recommend this medical facility!'), text_ru = COALESCE(text_ru, 'Мы обращались (в августе 2026 года) с заболевшим мальчиком (по страховке). Врач, которая нас осматривала, оказалась прекрасным специалистом и чутким человеком. Она назначила сыну необходимое лечение, выписала рецепт на лекарства и вместе с нами пришла в аптеку и помогла их купить.
Мы остались полностью довольны приёмом и очень благодарны!
Очень рекомендуем это медицинское учреждение!'), text_de = COALESCE(text_de, 'Wir kamen (im August 2026) mit unserem kranken Jungen (über die Versicherung). Die Ärztin, die uns untersuchte, erwies sich als hervorragende Fachfrau und einfühlsamer Mensch. Sie verordnete unserem Sohn die notwendige Behandlung, stellte ein Rezept für die Medikamente aus und ging sogar mit uns zur Apotheke und half uns, sie zu kaufen.
Wir waren mit dem Termin rundum zufrieden und sind sehr dankbar!
Wir können diese medizinische Einrichtung sehr empfehlen!'), text_tr = COALESCE(text_tr, '(Ağustos 2026\'da) hasta oğlumuzla (sigorta kapsamında) başvurduk. Bizi muayene eden doktor hanım mükemmel bir uzman ve duyarlı bir insan çıktı. Oğlumuza gerekli tedaviyi verdi, ilaçlar için reçete yazdı, hatta bizimle birlikte eczaneye gelip ilaçları almamıza yardım etti.
Muayeneden tamamen memnun kaldık ve çok minnettarız!
Bu sağlık kuruluşunu kesinlikle tavsiye ediyoruz!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xjd2NHMTViVEZ0U0RKdmNEVTNRV013VWxSTFkyYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома задовољна! Пажњом, лијечењем и брзином изласка на терен, као и правом терапијом, што је утицало на брзо побољшање здравственог стања.'), text_en = COALESCE(text_en, 'Very satisfied! With the attention, the treatment and how quickly they came out to us, as well as with the right therapy, which made my health improve quickly.'), text_ru = COALESCE(text_ru, 'Очень довольна! Вниманием, лечением и тем, как быстро приехали на вызов, а также правильно подобранной терапией — благодаря этому самочувствие быстро улучшилось.'), text_de = COALESCE(text_de, 'Sehr zufrieden! Mit der Aufmerksamkeit, der Behandlung und wie schnell sie zu uns rausgekommen sind, sowie mit der richtigen Therapie, durch die sich mein Gesundheitszustand schnell gebessert hat.'), text_tr = COALESCE(text_tr, 'Çok memnunum! Gösterilen ilgi, tedavi, ne kadar çabuk geldikleri ve sağlığımın hızla düzelmesini sağlayan doğru tedavi için.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2s1cWRXdHVVbFJCZGtSbVp6Sm5lbUpOV0ZSb1VGRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Tokom boravka u inostranstvu dobila sam upalu sinusa, kašalj i bol u uhu. Vrlo brzo mi je pružena pomoć — došao je ljekar s osobom koja je govorila i razumjela poljski, pa je pregled obavljen prilično brzo i temeljno. Preporuke su mi objašnjene i prevedene preko prevodioca, da se uvjere da sam sve razumjela. Bila sam veoma iznenađena pomoći koju sam dobila za tako kratko vrijeme.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Током боравка у иностранству добила сам упалу синуса, кашаљ и бол у уху. Врло брзо ми је пружена помоћ — дошао је љекар с особом која је говорила и разумјела пољски, па је преглед обављен прилично брзо и темељно. Препоруке су ми објашњене и преведене преко преводиоца, да се увјере да сам све разумјела. Била сам веома изненађена помоћи коју сам добила за тако кратко вријеме.'), text_en = COALESCE(text_en, 'While staying abroad I came down with sinusitis, a cough and ear pain. I got help very quickly — a doctor came along with someone who spoke and understood Polish, so the visit was carried out fairly quickly and thoroughly. The recommendations were explained to me and translated with a translator app to make sure I understood everything. I was very surprised by how quickly I received help.'), text_ru = COALESCE(text_ru, 'Во время пребывания за границей я заболела: синусит, кашель и боль в ухе. Помощь мне оказали очень быстро — приехал врач вместе с человеком, который говорил и понимал по-польски, поэтому визит прошёл довольно быстро и обстоятельно. Рекомендации мне объяснили и перевели через переводчик, чтобы убедиться, что я всё поняла. Я была очень удивлена, что мне помогли так быстро.'), text_de = COALESCE(text_de, 'Während meines Auslandsaufenthalts bekam ich eine Nebenhöhlenentzündung, Husten und Ohrenschmerzen. Mir wurde sehr schnell geholfen — ein Arzt kam zusammen mit einer Person, die Polnisch sprach und verstand, sodass der Besuch recht zügig und gründlich ablief. Die Empfehlungen wurden mir erklärt und mit einem Übersetzer übersetzt, um sicherzugehen, dass ich alles verstanden hatte. Ich war sehr überrascht, wie schnell mir geholfen wurde.'), text_tr = COALESCE(text_tr, 'Yurt dışında kaldığım sırada sinüzit, öksürük ve kulak ağrısıyla hastalandım. Bana çok hızlı yardım edildi — doktor, Lehçe konuşup anlayan biriyle birlikte geldi, bu sayede muayene oldukça hızlı ve özenli bir şekilde yapıldı. Her şeyi anladığımdan emin olmak için öneriler bana açıklandı ve çeviri uygulamasıyla tercüme edildi. Bu kadar kısa sürede aldığım yardıma çok şaşırdım.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21odlFYRnBUa05WU1dsa2RraE1iMloxYmtodmVXYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Брзи, професионални, љубазни. Чиста десетка.'), text_en = COALESCE(text_en, 'Fast, professional, friendly. A solid ten out of ten.'), text_ru = COALESCE(text_ru, 'Быстрые, профессиональные, вежливые. Твёрдая десятка.'), text_de = COALESCE(text_de, 'Schnell, professionell, freundlich. Glatte zehn von zehn.'), text_tr = COALESCE(text_tr, 'Hızlı, profesyonel, nazik. Tam on üzerinden on.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xWQ1dVRnRZWFJSYzAxb2VrSkNNMWRDYTFNelNVRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све је било професионално. Услугу смо добили истог дана. Преглед је обављен у апартману у ком смо боравили. Све похвале.'), text_en = COALESCE(text_en, 'Everything was professional. We got the service the same day. The examination was done in the apartment where we were staying. Full praise.'), text_ru = COALESCE(text_ru, 'Всё было профессионально. Услугу получили в тот же день. Осмотр провели в апартаментах, где мы жили. Только похвалы.'), text_de = COALESCE(text_de, 'Alles war professionell. Wir haben die Leistung noch am selben Tag erhalten. Die Untersuchung fand in der Ferienwohnung statt, in der wir untergebracht waren. Großes Lob.'), text_tr = COALESCE(text_tr, 'Her şey profesyoneldi. Hizmeti aynı gün aldık. Muayene, kaldığımız dairede yapıldı. Tebrikler.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tscmEwTllXbWhOYkVZM1IxZDBUblV3Y1dwM2VsRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Hvala kompaniji: pomogli su nam da brzo dođemo do dobrog pedijatra i riješili su djetetu i problem s bolesnim uhom i bronhitis koji je počinjao. Brzo su organizovali ljekare i ponovo nas zakazali za pregled. Uvijek su na vezi.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Хвала компанији: помогли су нам да брзо дођемо до доброг педијатра и ријешили су дјетету и проблем с болесним ухом и бронхитис који је почињао. Брзо су организовали љекаре и поново нас заказали за преглед. Увијек су на вези.'), text_en = COALESCE(text_en, 'Thanks to the company: they helped us quickly get to a good pediatrician and sorted out both our child\'s sore ear and the onset of bronchitis. They promptly arranged the doctors and booked us in again for a follow-up. Always reachable.'), text_de = COALESCE(text_de, 'Danke an das Unternehmen: Sie haben uns schnell zu einem guten Kinderarzt verholfen und dem Kind geholfen, sowohl die Ohrenbeschwerden als auch die beginnende Bronchitis in den Griff zu bekommen. Die Ärzte wurden zügig organisiert, und wir bekamen erneut einen Untersuchungstermin. Immer erreichbar.'), text_tr = COALESCE(text_tr, 'Şirkete teşekkürler: hızlıca iyi bir çocuk doktoruna ulaşmamıza yardımcı oldular ve çocuğumuzun hem ağrıyan kulağı hem de başlamakta olan bronşiti sorununu çözdüler. Doktorları hızla ayarladılar, kontrol muayenesi için yeniden randevu verdiler. Her zaman ulaşılabilirler.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2paRmJrRjBVVkZ5VlY5Uk16QmZjVXR4U1hoUmJIYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Veoma brza i djelotvorna pomoć. Preporučujem.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома брза и дјелотворна помоћ. Препоручујем.'), text_en = COALESCE(text_en, 'Very efficient, effective help. I recommend them.'), text_ru = COALESCE(text_ru, 'Очень оперативная и действенная помощь. Рекомендую.'), text_de = COALESCE(text_de, 'Sehr zügige, wirksame Hilfe. Empfehlenswert.'), text_tr = COALESCE(text_tr, 'Çok hızlı ve etkili yardım. Tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2kweU5tdERaa0ZPYzNCcmFUSXdXa2g1Y0ZoUVJXYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Tokom boravka u Crnoj Gori trebala mi je ljekarska pomoć zbog bola u uhu. Klinika mi je prilično brzo našla termin. U komunikaciji na engleskom dobila sam tačnu lokaciju i brze odgovore na sva moja pitanja. Preporučujem :)'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Током боравка у Црној Гори требала ми је љекарска помоћ због бола у уху. Клиника ми је прилично брзо нашла термин. У комуникацији на енглеском добила сам тачну локацију и брзе одговоре на сва моја питања. Препоручујем :)'), text_en = COALESCE(text_en, 'During my stay in Montenegro I needed medical help for ear pain. The clinic found me an appointment quite quickly. Communicating in English, I got the exact location and quick answers to all my questions. Recommended :)'), text_ru = COALESCE(text_ru, 'Во время пребывания в Черногории мне понадобилась медицинская помощь из-за боли в ухе. Клиника довольно быстро нашла для меня время приёма. Общались на английском: мне прислали точное местоположение и быстро отвечали на все мои вопросы. Рекомендую :)'), text_de = COALESCE(text_de, 'Während meines Aufenthalts in Montenegro brauchte ich wegen Ohrenschmerzen ärztliche Hilfe. Die Klinik hat recht zügig einen Termin für mich gefunden. Die Kommunikation lief auf Englisch, ich bekam den genauen Standort und schnelle Antworten auf alle meine Fragen. Empfehlenswert :)'), text_tr = COALESCE(text_tr, 'Karadağ\'da kaldığım süre boyunca kulak ağrısı nedeniyle tıbbi yardıma ihtiyacım oldu. Klinik bana oldukça hızlı bir randevu buldu. İngilizce iletişim kurdum; tam konumu ve tüm sorularıma hızlı yanıtlar aldım. Tavsiye ederim :)') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT201RFVVVnRkRkJLZDJ0VVFuSjZURkZNWms5WmFVRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Свака комуникација је на високом нивоу. Такође смо врло брзо добили термин, иако нам се клиника јавила послије пријаве осигурању да нам је неопходан доктор за дијете. Хвала на бризи.'), text_en = COALESCE(text_en, 'All communication was top-notch. We also got an appointment very quickly, even though the clinic reached out to us after we had notified our insurer that we needed a doctor for our child. Thank you for your care.'), text_ru = COALESCE(text_ru, 'Всё общение на высоком уровне. К тому же мы очень быстро получили запись, хотя клиника связалась с нами уже после того, как мы сообщили страховой, что ребёнку нужен врач. Спасибо за заботу.'), text_de = COALESCE(text_de, 'Die gesamte Kommunikation ist auf hohem Niveau. Außerdem haben wir sehr schnell einen Termin bekommen, obwohl sich die Klinik erst bei uns gemeldet hat, nachdem wir der Versicherung mitgeteilt hatten, dass wir einen Arzt für unser Kind brauchen. Danke für die Fürsorge.'), text_tr = COALESCE(text_tr, 'Tüm iletişim üst düzeyde. Ayrıca klinik bizimle, sigortaya çocuğumuz için doktora ihtiyacımız olduğunu bildirdikten sonra iletişime geçmesine rağmen çok hızlı randevu aldık. İlginiz için teşekkürler.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2sxdmNqZDVSMTlvZFVwWk4yOTBNbTFrT0Vkd01FRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Убрзо послије разговора све су организовали са доктором који је дошао на адресу. Свака препорука.'), text_en = COALESCE(text_en, 'Shortly after the call they arranged everything, with a doctor who came to our address. Highly recommended.'), text_ru = COALESCE(text_ru, 'Вскоре после разговора всё организовали — врач приехал по адресу. Однозначно рекомендую.'), text_de = COALESCE(text_de, 'Kurz nach dem Gespräch war alles organisiert, ein Arzt kam direkt zu uns. Absolut empfehlenswert.'), text_tr = COALESCE(text_tr, 'Görüşmeden kısa süre sonra her şeyi ayarladılar; doktor adresimize geldi. Kesinlikle tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tKak9IUk5RVUpNVkRoaWRVWmhSbEpQV1VseExVRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома стручни у свом послу, свака похвала, са великим поштовањем.'), text_en = COALESCE(text_en, 'Very skilled at what they do. Full praise, with great respect.'), text_ru = COALESCE(text_ru, 'Настоящие профессионалы своего дела. Только похвалы, с большим уважением.'), text_de = COALESCE(text_de, 'Sehr kompetent in ihrem Fach. Großes Lob, mit großem Respekt.'), text_tr = COALESCE(text_tr, 'İşlerinde çok uzmanlar. Tebrikler, büyük saygılarımla.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xkNExXcFNObmt3YkRVNU4zcGxObGM1TW5CSFIxRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Брза реакција и професионализам! Хвала пуно на помоћи. 🩷'), text_en = COALESCE(text_en, 'Quick response and professionalism! Thanks so much for the help. 🩷'), text_ru = COALESCE(text_ru, 'Быстрая реакция и профессионализм! Огромное спасибо за помощь. 🩷'), text_de = COALESCE(text_de, 'Schnelle Reaktion und Professionalität! Vielen Dank für die Hilfe. 🩷'), text_tr = COALESCE(text_tr, 'Hızlı müdahale ve profesyonellik! Yardımınız için çok teşekkürler. 🩷') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT20xUVRqSnBYMVpFVFRWeE5tRjVOR1EzY0ZSQ1pHYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома експедитивни и професионални... изузетно смо задовољни. Само тако наставите...🙂'), text_en = COALESCE(text_en, 'Very prompt and professional... we are extremely satisfied. Keep it up...🙂'), text_ru = COALESCE(text_ru, 'Очень оперативные и профессиональные... мы крайне довольны. Так держать...🙂'), text_de = COALESCE(text_de, 'Sehr zügig und professionell... wir sind äußerst zufrieden. Macht weiter so...🙂'), text_tr = COALESCE(text_tr, 'Çok hızlı ve profesyoneller... son derece memnunuz. Böyle devam edin...🙂') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21SVFJGUTJZbWxFZEZoUGRGcGhkRkZMUjFWbldVRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Odlična usluga i veoma ljubazno osoblje. Bili su profesionalni, uslužni i brižni. Liječenje me je veoma zadovoljilo i toplo preporučujem Medical Vranes. Hvala vam! 😊'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Одлична услуга и веома љубазно особље. Били су професионални, услужни и брижни. Лијечење ме је веома задовољило и топло препоручујем Medical Vranes. Хвала вам! 😊'), text_ru = COALESCE(text_ru, 'Отличный сервис и очень доброжелательный персонал. Профессиональные, отзывчивые и заботливые. Лечение меня очень порадовало, и я настоятельно рекомендую Medical Vranes. Спасибо! 😊'), text_de = COALESCE(text_de, 'Ausgezeichneter Service und sehr freundliches Personal. Sie waren professionell, hilfsbereit und fürsorglich. Ich bin mit der Behandlung sehr zufrieden und kann Medical Vranes wärmstens empfehlen. Vielen Dank! 😊'), text_tr = COALESCE(text_tr, 'Mükemmel hizmet ve çok güler yüzlü personel. Profesyonel, yardımsever ve ilgiliydiler. Tedaviden çok memnunum ve Medical Vranes\'i şiddetle tavsiye ederim. Teşekkürler! 😊') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21kRmNXOWFTVVJrTjFnNFlYSmFNR1paYjB0MFNYYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Bili smo prijatno iznenađeni brzinom reagovanja. Specifičan lijek je kćerki odmah prepisan u apoteci. Sve je prošlo veoma dobro 👍'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Били смо пријатно изненађени брзином реаговања. Специфичан лијек је кћерки одмах преписан у апотеци. Све је прошло веома добро 👍'), text_en = COALESCE(text_en, 'We were pleasantly surprised by how fast they acted. A specific medicine was prescribed for our daughter right away at the pharmacy. Everything went very well 👍'), text_ru = COALESCE(text_ru, 'Мы были приятно удивлены скоростью работы. Дочери сразу же выписали особое лекарство в аптеке. Всё прошло очень хорошо 👍'), text_de = COALESCE(text_de, 'Wir waren positiv überrascht, wie schnell alles ging. Ein spezielles Medikament wurde unserer Tochter sofort in der Apotheke verschrieben. Alles lief sehr gut 👍'), text_tr = COALESCE(text_tr, 'Ne kadar hızlı hareket ettiklerine olumlu anlamda şaşırdık. Kızımıza özel bir ilaç hemen eczanede reçete edildi. Her şey çok iyi gitti 👍') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25kRFNrOTNXbGxDTWxoTU1VTkxVbTlCZFd4bFFsRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Прелијепо искуство са вашим тимом.

Докторица је дошла до нас, изузетно је љубазна и професионална. Преглед је заиста био детаљан и максимално је посветила пажњу дјетету.'), text_en = COALESCE(text_en, 'A lovely experience with your team.

The doctor came to us; she is extremely kind and professional. The examination was really thorough and she gave the child her full attention.'), text_ru = COALESCE(text_ru, 'Прекрасный опыт общения с вашей командой.

Доктор приехала к нам, она очень любезная и профессиональная. Осмотр был действительно подробным, и она уделила ребёнку максимум внимания.'), text_de = COALESCE(text_de, 'Eine wunderbare Erfahrung mit Ihrem Team.

Die Ärztin kam zu uns, sie ist äußerst freundlich und professionell. Die Untersuchung war wirklich gründlich, und sie hat sich dem Kind mit voller Aufmerksamkeit gewidmet.'), text_tr = COALESCE(text_tr, 'Ekibinizle harika bir deneyim.

Doktor hanım yanımıza geldi; son derece nazik ve profesyonel. Muayene gerçekten ayrıntılıydı ve çocuğa azami ilgi gösterdi.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tkR2RFWkdibFpmVlZKc1RVNU5iMUl3ZUhRNWFtYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Sve je riješeno brzo i efikasno. Ljekar je došao u hotel zajedno s medicinskom sestrom, pregledao, postavio dijagnozu, objasnio i dao preporuke. Koljeno me skoro više ne boli.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све је ријешено брзо и ефикасно. Љекар је дошао у хотел заједно с медицинском сестром, прегледао, поставио дијагнозу, објаснио и дао препоруке. Кољено ме скоро више не боли.'), text_en = COALESCE(text_en, 'Everything was handled quickly and efficiently. The doctor came to the hotel together with a nurse, examined, diagnosed, explained and gave recommendations. My knee hardly hurts anymore.'), text_ru = COALESCE(text_ru, 'Всё решили быстро и чётко. Врач приехал в отель вместе с медсестрой: осмотрел, поставил диагноз, объяснил и дал рекомендации. Колено уже почти не болит.'), text_de = COALESCE(text_de, 'Alles wurde schnell und reibungslos erledigt. Der Arzt kam zusammen mit einer Krankenschwester ins Hotel, hat untersucht, eine Diagnose gestellt, alles erklärt und Empfehlungen gegeben. Das Knie tut schon fast nicht mehr weh.'), text_tr = COALESCE(text_tr, 'Her şey hızlı ve sorunsuz halledildi. Doktor bir hemşireyle birlikte otele geldi; muayene etti, teşhis koydu, açıkladı ve önerilerde bulundu. Dizim artık neredeyse hiç ağrımıyor.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21jMFIxZ3RkRGREZWxwSVZrZFdkWEJoVW5SZlMzYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Uslugu smo koristili tokom odmora u avgustu. Kućna posjeta i vakcinacija protiv tetanusa – sve je bilo profesionalno i kvalitetno.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Услугу смо користили током одмора у августу. Кућна посјета и вакцинација против тетануса – све је било професионално и квалитетно.'), text_ru = COALESCE(text_ru, 'Пользовались услугами во время отпуска в августе. Визит врача на дом и прививка от столбняка — всё было профессионально и качественно.'), text_de = COALESCE(text_de, 'Wir haben den Service während unseres Urlaubs im August genutzt. Hausbesuch und Tetanusimpfung – alles war professionell und von hoher Qualität.'), text_tr = COALESCE(text_tr, 'Ağustostaki tatilimiz sırasında bu hizmeti kullandık. Ev ziyareti ve tetanos aşısı – her şey profesyonel ve kaliteliydi.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2t4Q1VtNU5TWEpXVWxFMU5FTjBjRXB6VFVjd1MyYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Od samog početka osjećaj je bio da sam u sigurnim rukama i da me shvataju ozbiljno. Dr Milenka Vraneš Grujičić odvojila je mnogo vremena i veoma brižno se pobrinula za mene. Liječenje je odmah pomoglo, pa sam ubrzo mogao da nastavim odmor. Veliko hvala na brzoj i nekomplikovanoj pomoći u kratkom roku – svakako preporučujem!'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Од самог почетка осјећај је био да сам у сигурним рукама и да ме схватају озбиљно. Др Миленка Вранеш Грујичић одвојила је много времена и веома брижно се побринула за мене. Лијечење је одмах помогло, па сам убрзо могао да наставим одмор. Велико хвала на брзој и некомпликованој помоћи у кратком року – свакако препоручујем!'), text_en = COALESCE(text_en, 'From the very start I felt I was in very good hands and taken seriously. Dr. Milenka Vraneš Grujičić took plenty of time and looked after me with great care. The treatment helped right away, so I was soon able to continue my holiday. Many thanks for the quick, uncomplicated help at short notice – a clear recommendation!'), text_ru = COALESCE(text_ru, 'С самого начала было ощущение, что я в надёжных руках и ко мне относятся серьёзно. Доктор Миленка Вранеш Груичич уделила мне много времени и очень заботливо ко мне отнеслась. Лечение помогло сразу, так что вскоре можно было продолжить отпуск. Большое спасибо за быструю помощь без лишних формальностей и в короткие сроки — однозначно рекомендую!'), text_tr = COALESCE(text_tr, 'En başından itibaren kendimi emin ellerde ve ciddiye alınmış hissettim. Dr. Milenka Vraneš Grujičić bana çok zaman ayırdı ve benimle büyük bir özenle ilgilendi. Tedavi hemen işe yaradı, böylece tatilime kısa sürede devam edebildim. Kısa sürede sağlanan hızlı ve zahmetsiz yardım için çok teşekkürler – kesinlikle tavsiye ederim!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xkS1JEWmZObFJmVkhoa2RqSkdjVzVvWmtaQ1ZWRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Дошли смо преко путног осигурања, одушевљени смо. Љубазност, приступ, све је на највишем могућем нивоу. Докторка детаљна, професионална, све је објаснила. Сестра приликом заказивања такође љубазна, учтива. Чиста десетка.'), text_en = COALESCE(text_en, 'We came through our travel insurance and were delighted. Kindness, approach – everything is at the highest possible level. The doctor was thorough and professional and explained everything. The nurse who booked the appointment was also kind and polite. A solid ten out of ten.'), text_ru = COALESCE(text_ru, 'Пришли через туристическую страховку — в восторге. Вежливость, подход — всё на высшем уровне. Доктор внимательная, профессиональная, всё объяснила. Медсестра при записи тоже вежливая, учтивая. Твёрдая десятка.'), text_de = COALESCE(text_de, 'Wir kamen über unsere Reiseversicherung und sind begeistert. Freundlichkeit, Umgang – alles auf höchstem Niveau. Die Ärztin war gründlich, professionell und hat alles erklärt. Auch die Schwester bei der Terminvergabe war freundlich und höflich. Glatte zehn von zehn.'), text_tr = COALESCE(text_tr, 'Seyahat sigortası aracılığıyla geldik ve çok memnun kaldık. Nezaket, yaklaşım, her şey mümkün olan en üst düzeyde. Doktor hanım titiz ve profesyoneldi, her şeyi açıkladı. Randevu sırasında hemşire de nazik ve kibardı. Tam on üzerinden on.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25keFEzbFFjamxpWmpWU2IzTndOVmhpVmpWVlIwRRAB';
UPDATE reviews SET text_en = COALESCE(text_en, 'To my great surprise and disbelief – but I state this with full responsibility – this healthcare facility left me without medical care. I have never experienced such treatment anywhere, and unfortunately we have had occasion to turn to many clinics.
They communicate with patients via WhatsApp, by message. When you call that number, they don\'t answer, and at 6 p.m. they have no doctor available, so for an urgent call they book an examination for 9 a.m. the next day.
They kept me in the dark until almost 8 p.m., when you are no longer able to turn to anyone else for help. Even though I stressed how serious the situation was, they did nothing because they have no doctors!?! In the end I was admitted to hospital as an emergency. I will initiate proceedings against this facility, because I have documented the communication, even though the facility protected itself against leaving a trace by using disappearing messages. Shameful.
I am writing this review to warn the public.
Help was requested on 7 August 2026.'), text_ru = COALESCE(text_ru, 'К моему большому удивлению, в это трудно поверить, но я ответственно заявляю: это медицинское учреждение оставило меня без медицинской помощи. Такого отношения я никогда и нигде не встречала, а нам, к сожалению, доводилось обращаться во многие клиники.
С пациентами они общаются через WhatsApp, сообщениями. Если позвонить на этот номер, трубку не берут, а в 18 часов у них нет свободного врача, поэтому на срочный вызов записывают на осмотр на следующий день в 9 утра.
Меня держали в неведении почти до 20 часов, когда обратиться за помощью куда-то ещё уже нет возможности. Хотя я подчеркнула серьёзность ситуации, они ничего не предприняли, потому что у них нет врачей!?! В итоге меня экстренно госпитализировали. Я начну разбирательство против этого учреждения, потому что задокументировала переписку, хотя учреждение и подстраховалось от сохранения следов, включив исчезающие сообщения. Позор.
Пишу этот отзыв, чтобы предупредить людей.
За помощью обратились 7 августа 2026 года.'), text_de = COALESCE(text_de, 'Zu meiner großen Überraschung und kaum zu glauben – aber ich sage es mit voller Verantwortung: Diese Gesundheitseinrichtung hat mir keine medizinische Hilfe geleistet. Eine solche Behandlung habe ich nie und nirgends erlebt, und leider mussten wir uns schon an zahlreiche Kliniken wenden.
Die Kommunikation mit Patienten läuft über WhatsApp, per Nachricht. Ruft man diese Nummer an, geht niemand ran, und um 18 Uhr haben sie keinen Arzt verfügbar, sodass sie bei einem dringenden Anruf eine Untersuchung für den nächsten Tag um 9 Uhr morgens ansetzen.
Man hat mich bis fast 20 Uhr im Ungewissen gelassen, wenn man sich nicht mehr an andere um Hilfe wenden kann. Obwohl ich auf den Ernst der Lage hingewiesen habe, haben sie nichts unternommen, weil sie keinen Arzt haben!?! Schließlich wurde ich als Notfall ins Krankenhaus aufgenommen. Ich werde ein Verfahren gegen diese Einrichtung einleiten, denn ich habe die Kommunikation dokumentiert, obwohl sich die Einrichtung mit verschwindenden Nachrichten dagegen abgesichert hat, Spuren zu hinterlassen. Eine Schande.
Ich schreibe diese Bewertung, um die Öffentlichkeit zu warnen.
Um Hilfe wurde am 7. August 2026 gebeten.'), text_tr = COALESCE(text_tr, 'Büyük bir şaşkınlıkla ve inanması güç olsa da sorumluluk bilinciyle söylüyorum: bu sağlık kuruluşu beni tıbbi yardımdan yoksun bıraktı. Böyle bir muameleyi hiçbir zaman ve hiçbir yerde yaşamadım; ne yazık ki pek çok kliniğe başvurmak zorunda kalmıştık.
Hastalarla WhatsApp üzerinden, mesajla iletişim kuruyorlar. O numarayı aradığınızda açmıyorlar; saat 18.00\'de müsait doktorları yok, bu yüzden acil bir çağrı için ertesi gün sabah 9\'a muayene randevusu veriyorlar.
Beni neredeyse saat 20.00\'ye kadar belirsizlik içinde bıraktılar; o saatte artık başka birinden yardım isteme imkânınız kalmıyor. Durumun ciddiyetini vurgulamama rağmen hiçbir şey yapmadılar, çünkü doktorları yok!?! Sonunda acil vaka olarak hastaneye kaldırıldım. Bu kuruluş hakkında yasal süreç başlatacağım; her ne kadar kuruluş kaybolan mesajlar seçeneğiyle iz bırakmamak için önlem almış olsa da yazışmaları belgeledim. Utanç verici.
Bu yorumu kamuoyunu uyarmak için yazıyorum.
Yardım 7 Ağustos 2026\'da talep edildi.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25sZmVIcENjbmwzT1ZZMVQzUkZkQzF1Unpkb1MyYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Вашу клинику смо добили преко DDOR осигурања и комуникација је била супер. Докторка је дивна, љубазна и стручна и јако смо задовољни услугом. Хвала!'), text_en = COALESCE(text_en, 'We were referred to your clinic through DDOR insurance and the communication was great. The doctor is wonderful, kind and knowledgeable, and we are very happy with the service. Thank you!'), text_ru = COALESCE(text_ru, 'Нас направили в вашу клинику через страховую DDOR, и общение было отличным. Доктор чудесная, вежливая и компетентная, мы очень довольны услугой. Спасибо!'), text_de = COALESCE(text_de, 'Wir sind über die DDOR-Versicherung zu Ihrer Klinik gekommen, und die Kommunikation war super. Die Ärztin ist wunderbar, freundlich und kompetent, und wir sind mit dem Service sehr zufrieden. Danke!'), text_tr = COALESCE(text_tr, 'Kliniğinize DDOR sigortası aracılığıyla yönlendirildik ve iletişim harikaydı. Doktor hanım harika, nazik ve işinin ehli; hizmetten çok memnunuz. Teşekkürler!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pGNVdWOUxjRkk1V0d0dk1IcG5jMFJJWjJKaE1sRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Od srca vam hvala na izuzetnoj brizi! I saradnja s doktorom i cjelokupna organizacija u Klinici su na najvišem nivou. Molimo vas da našu zahvalnost prenesete cijelom osoblju. Bez oklijevanja ćemo preporučivati vaše usluge prijateljima i porodici. Želimo vam dalji uspjeh i razvoj. Ovo je uzor za cijelo poljsko zdravstvo – odnos prema pacijentu i profesionalna usluga za svaku pohvalu! Još jednom hvala doktoru na profesionalizmu.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Од срца вам хвала на изузетној бризи! И сарадња с доктором и цјелокупна организација у Клиници су на највишем нивоу. Молимо вас да нашу захвалност пренесете цијелом особљу. Без оклијевања ћемо препоручивати ваше услуге пријатељима и породици. Желимо вам даљи успјех и развој. Ово је узор за цијело пољско здравство – однос према пацијенту и професионална услуга за сваку похвалу! Још једном хвала доктору на професионализму.'), text_en = COALESCE(text_en, 'Heartfelt thanks for the exceptional care! Both working with the doctor and the whole organization at the Clinic are of the highest standard. Please pass on our thanks to all the staff. We will recommend your services to friends and family without hesitation. We wish you continued success and growth. This is a model for the entire Polish healthcare system to follow – the approach to the patient and the professional service deserve a medal! Once again, thank you to the doctor for his professionalism.'), text_ru = COALESCE(text_ru, 'Сердечно благодарим за исключительную заботу! И работа с доктором, и вся организация в клинике — на высшем уровне. Пожалуйста, передайте нашу благодарность всему персоналу. Мы без колебаний будем рекомендовать ваши услуги друзьям и родным. Желаем дальнейших успехов и развития. Это образец для подражания для всего польского здравоохранения — отношение к пациенту и профессиональное обслуживание на пять с плюсом! Ещё раз спасибо доктору за профессионализм.'), text_de = COALESCE(text_de, 'Herzlichen Dank für die außergewöhnliche Betreuung! Sowohl die Zusammenarbeit mit dem Arzt als auch die gesamte Organisation in der Klinik sind auf höchstem Niveau. Bitte richten Sie unseren Dank dem gesamten Personal aus. Wir werden Ihre Leistungen ohne Zögern Freunden und Familie empfehlen. Wir wünschen Ihnen weiterhin viel Erfolg und Wachstum. Ein Vorbild für das gesamte polnische Gesundheitswesen – der Umgang mit Patienten und der professionelle Service verdienen eine Medaille! Nochmals vielen Dank an den Arzt für seine Professionalität.'), text_tr = COALESCE(text_tr, 'Olağanüstü ilginiz için yürekten teşekkür ederiz! Hem doktor beyle çalışmak hem de Klinik\'teki tüm organizasyon en üst düzeyde. Lütfen teşekkürlerimizi tüm personele iletin. Hizmetlerinizi arkadaşlarımıza ve ailemize tereddütsüz tavsiye edeceğiz. Başarılarınızın ve gelişiminizin devamını dileriz. Hastaya yaklaşımı ve profesyonel hizmetiyle tüm Polonya sağlık sistemine örnek olacak bir model – madalyayı hak ediyor! Profesyonelliği için doktor beye bir kez daha teşekkür ederiz.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pCUE1sRXRia2w1TW5OV1RsUlBkVm90ZEVKcFduYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Презадовољни: услуга и помоћ у рекордном року, љубазност, поштовање и адекватан приступ и објашњење за даље лијечење. За почетак људскост, и знање. Хвала на свему 🥰🥰🥰🌊'), text_en = COALESCE(text_en, 'Extremely satisfied: service and help in record time, kindness, respect, and a proper approach and explanation for further treatment. Humanity first, and knowledge. Thank you for everything 🥰🥰🥰🌊'), text_ru = COALESCE(text_ru, 'Очень довольны: обслуживание и помощь в рекордные сроки, любезность, уважение, правильный подход и объяснение дальнейшего лечения. Прежде всего человечность — и знания. Спасибо за всё 🥰🥰🥰🌊'), text_de = COALESCE(text_de, 'Überaus zufrieden: Service und Hilfe in Rekordzeit, Freundlichkeit, Respekt sowie ein angemessener Umgang und eine Erklärung zur weiteren Behandlung. Vor allem Menschlichkeit – und Fachwissen. Danke für alles 🥰🥰🥰🌊'), text_tr = COALESCE(text_tr, 'Son derece memnunuz: rekor sürede hizmet ve yardım, nezaket, saygı, uygun yaklaşım ve sonraki tedavi için açıklama. Her şeyden önce insanlık ve bilgi. Her şey için teşekkürler 🥰🥰🥰🌊') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tOdGQwZDZNbUZKZFdoV2EySktTVUpJVEVneWRGRRAB';
UPDATE reviews SET text_en = COALESCE(text_en, 'Dr. Natalija Petrović is very knowledgeable and kind. The service is fast and professional. The staff are helpful and friendly.'), text_ru = COALESCE(text_ru, 'Доктор Наталия Петрович — очень компетентный и любезный врач. Обслуживание быстрое и профессиональное. Персонал услужливый и вежливый.'), text_de = COALESCE(text_de, 'Dr. Natalija Petrović ist sehr kompetent und freundlich. Der Service ist schnell und professionell. Das Personal ist hilfsbereit und freundlich.'), text_tr = COALESCE(text_tr, 'Dr. Natalija Petrović çok yetkin ve nazik. Hizmet hızlı ve profesyonel. Personel yardımsever ve güler yüzlü.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xWMGNqQnZlRmN6TkVZMGJVZ3phRFZsYjFwdGQxRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Сјајно медицинско особље ми је у врло кратком року помогло. Све најбоље у будућем раду!'), text_en = COALESCE(text_en, 'The wonderful medical staff helped me very quickly. All the best in your future work!'), text_ru = COALESCE(text_ru, 'Замечательный медицинский персонал помог мне в очень короткий срок. Всего наилучшего в дальнейшей работе!'), text_de = COALESCE(text_de, 'Das großartige medizinische Personal hat mir sehr schnell geholfen. Alles Gute für Ihre weitere Arbeit!'), text_tr = COALESCE(text_tr, 'Harika sağlık ekibi bana çok kısa sürede yardımcı oldu. Gelecekteki çalışmalarınızda başarılar!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21nNE4wTnRVMDFzU1RoeFJFNWhORGhJV1haMWMxRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Sve odlično!'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све одлично!'), text_ru = COALESCE(text_ru, 'Всё отлично!'), text_de = COALESCE(text_de, 'Alles ausgezeichnet!'), text_tr = COALESCE(text_tr, 'Her şey mükemmel!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT200M1NVVmFXVzgxZFdKUlFqaHhPRmwzTUZGVk1IYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Veoma brz kontakt s pacijentom, posjeta u hotelu bez ikakvih problema, jer nismo mogli da dođemo u kliniku. Stručna konsultacija, toplo preporučujem.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома брз контакт с пацијентом, посјета у хотелу без икаквих проблема, јер нисмо могли да дођемо у клинику. Стручна консултација, топло препоручујем.'), text_en = COALESCE(text_en, 'Very quick contact with the patient and a hassle-free visit to our hotel, since we couldn\'t come to the clinic. Professional consultation, highly recommended.'), text_ru = COALESCE(text_ru, 'Очень быстрая связь с пациентом, визит в отель прошёл без проблем — мы не могли приехать в клинику. Профессиональная консультация, очень рекомендую.'), text_de = COALESCE(text_de, 'Sehr schneller Kontakt mit dem Patienten, problemloser Besuch im Hotel, da wir nicht in die Klinik kommen konnten. Fachkundige Beratung, sehr empfehlenswert.'), text_tr = COALESCE(text_tr, 'Hastayla çok hızlı iletişim kuruldu, kliniğe gelemediğimiz için otelde sorunsuz bir muayene yapıldı. Profesyonel bir konsültasyon, kesinlikle tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2sxc1RuRlRabHBmZGxsVU1qTXhXVkYyUTJOUGRIYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Свака част клиници и љекарима који раде у њој. Мој дјечак од двије године је тако лијепо примљен и прегледан, а докторка педијатар која је прегледала мог сина била је толико стручна и брижна да је дијете то осјетило.'), text_en = COALESCE(text_en, 'Hats off to the clinic and the doctors who work there. My two-year-old boy was received and examined so nicely, and the pediatrician who examined my son was so skilled and caring that the child could feel it.'), text_ru = COALESCE(text_ru, 'Браво клинике и работающим в ней врачам! Моего двухлетнего сына так хорошо приняли и осмотрели, а педиатр, которая его осматривала, была настолько профессиональной и заботливой, что ребёнок это почувствовал.'), text_de = COALESCE(text_de, 'Hut ab vor der Klinik und den Ärzten, die dort arbeiten. Mein zweijähriger Junge wurde so herzlich empfangen und untersucht, und die Kinderärztin, die meinen Sohn untersucht hat, war so kompetent und fürsorglich, dass das Kind es gespürt hat.'), text_tr = COALESCE(text_tr, 'Kliniği ve orada çalışan doktorları tebrik ediyorum. İki yaşındaki oğlum çok güzel karşılandı ve muayene edildi; oğlumu muayene eden çocuk doktoru o kadar yetkin ve şefkatliydi ki çocuk bunu hissetti.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT201QlRrRTBWa3R1WjBFeE5sWlBiRUk0ZW1Oc1FsRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома смо задовољни вашим услугама. Хвала!'), text_en = COALESCE(text_en, 'We are very satisfied with your services. Thank you!'), text_ru = COALESCE(text_ru, 'Мы очень довольны вашими услугами. Спасибо!'), text_de = COALESCE(text_de, 'Wir sind mit Ihren Leistungen sehr zufrieden. Danke!'), text_tr = COALESCE(text_tr, 'Hizmetlerinizden çok memnunuz. Teşekkürler!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2w5WGJIUnNPRVZWWm1wYWVYY3pNMWhTZVU4eVpXYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Довели смо дијете; имало је температуру 38 и били смо веома забринути. Доктор је прегледао дијете и преписао антибиотике. Хвала вам на помоћи.'), text_en = COALESCE(text_en, 'We brought our child in; they had a temperature of 38 and we were very worried. The doctor examined the child and prescribed antibiotics. Thank you for your help.'), text_ru = COALESCE(text_ru, 'Мы привели ребёнка: у него была температура 38, и мы очень волновались. Врач осмотрел ребёнка и назначил антибиотики. Спасибо вам за помощь.'), text_de = COALESCE(text_de, 'Wir haben unser Kind gebracht; es hatte 38 Grad Fieber und wir waren sehr besorgt. Der Arzt hat das Kind untersucht und Antibiotika verschrieben. Vielen Dank für Ihre Hilfe.'), text_tr = COALESCE(text_tr, 'Çocuğumuzu getirdik; ateşi 38\'di ve çok endişeliydik. Doktor çocuğu muayene etti ve antibiyotik yazdı. Yardımınız için teşekkür ederiz.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2w5b2VucFZkemxVYUd4VGRVcHZUalZMZW0xRFEwRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Dobar odnos, doktorka je bila veoma pažljiva, ali je bilo malih problema s jezikom, pa nam je pomogla koleginica iz centra, koja je, inače, bila veoma ljubazna.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Добар однос, докторка је била веома пажљива, али је било малих проблема с језиком, па нам је помогла колегиница из центра, која је, иначе, била веома љубазна.'), text_en = COALESCE(text_en, 'Good treatment; the doctor was very attentive, but there was a small language problem and a colleague from the center helped us — very kind, by the way.'), text_ru = COALESCE(text_ru, 'Хорошее отношение, врач была очень внимательна, но возникла небольшая проблема с языком, и нам помогла сотрудница центра — кстати, очень любезная.'), text_de = COALESCE(text_de, 'Guter Umgang, die Ärztin war sehr aufmerksam, aber es gab ein kleines Sprachproblem, und eine Kollegin aus dem Zentrum hat uns geholfen – übrigens sehr freundlich.'), text_tr = COALESCE(text_tr, 'İlgi iyiydi, doktor çok özenliydi ama küçük bir dil sorunu yaşandı ve merkezden bir çalışan bize yardım etti; bu arada kendisi çok nazikti.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21jMlIzbGxZWHA1UlhCT1NXVXpZelF6WVU5MFNtYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Veoma brza i stručna usluga. Super smo zadovoljni. Ako zatreba, preporučujem!'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома брза и стручна услуга. Супер смо задовољни. Ако затреба, препоручујем!'), text_en = COALESCE(text_en, 'Very fast and professional service. We are super satisfied. If you need it, I recommend them!'), text_ru = COALESCE(text_ru, 'Очень быстрое и профессиональное обслуживание. Мы супердовольны. Если понадобится — рекомендую!'), text_de = COALESCE(text_de, 'Sehr schneller und kompetenter Service. Wir sind mega zufrieden. Wenn nötig – sehr zu empfehlen!'), text_tr = COALESCE(text_tr, 'Çok hızlı ve profesyonel hizmet. Süper memnunuz. İhtiyacınız olursa tavsiye ederim!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xKWU5rbEtlbU5hTUVKMmJuVjBaRFJTWjFKb09YYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Posjeta je protekla brzo i efikasno. Doktorka je govorila engleski. Prepisala je i dala lijekove koji su pomogli praktično odmah. Preporučujem.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Посјета је протекла брзо и ефикасно. Докторка је говорила енглески. Преписала је и дала љекове који су помогли практично одмах. Препоручујем.'), text_en = COALESCE(text_en, 'The visit went quickly and smoothly. The doctor spoke English. She prescribed and gave medication that helped almost immediately. Recommended.'), text_ru = COALESCE(text_ru, 'Визит прошёл быстро и чётко. Врач говорила по-английски. Она выписала и выдала лекарства, которые помогли практически сразу. Рекомендую.'), text_de = COALESCE(text_de, 'Der Besuch verlief schnell und reibungslos. Die Ärztin sprach Englisch. Sie verschrieb und gab Medikamente, die praktisch sofort geholfen haben. Empfehlenswert.'), text_tr = COALESCE(text_tr, 'Muayene hızlı ve sorunsuz geçti. Doktor İngilizce konuşuyordu. Neredeyse hemen etki eden ilaçlar yazdı ve verdi. Tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2poYU5UaFhhRVF0TnpkVFNuVjJObkkwT0RGMk9YYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Divno iskustvo, brzi odgovori i veoma ljubazno osoblje.
Toplo preporučujem.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Дивно искуство, брзи одговори и веома љубазно особље.
Топло препоручујем.'), text_ru = COALESCE(text_ru, 'Прекрасный опыт, быстрые ответы и очень доброжелательный персонал.
Очень рекомендую.'), text_de = COALESCE(text_de, 'Wunderbare Erfahrung, schnelle Antworten und sehr freundliches Personal.
Sehr empfehlenswert.'), text_tr = COALESCE(text_tr, 'Harika bir deneyim, hızlı yanıtlar ve çok güler yüzlü personel.
Kesinlikle tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25KNGJsbExjWFU1WlhCRWVFeHRNMWhWYjIxdk9FRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Imala sam napad išijasa. Doktorka me je detaljno pregledala, uzela anamnezu, dobila sam lijekove i preporuke za ubuduće – šta da izbjegavam, a šta da radim da sebi pomognem. Veoma prijatna doktorka, komunikativna, brižna, posvećena pacijentu. Preporučujem.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Имала сам напад ишијаса. Докторка ме је детаљно прегледала, узела анамнезу, добила сам љекове и препоруке за убудуће – шта да избјегавам, а шта да радим да себи помогнем. Веома пријатна докторка, комуникативна, брижна, посвећена пацијенту. Препоручујем.'), text_en = COALESCE(text_en, 'I had a sciatica attack. The doctor examined me thoroughly, took my history, and I got medication and advice for the future on what to avoid and what to do to help myself. A very nice doctor: approachable, caring and patient-focused. Recommended.'), text_ru = COALESCE(text_ru, 'У меня был приступ ишиаса. Врач тщательно меня осмотрела, собрала анамнез, мне дали лекарства и рекомендации на будущее: чего избегать и что делать, чтобы себе помочь. Очень приятный врач — контактная, заботливая, ориентированная на пациента. Рекомендую.'), text_de = COALESCE(text_de, 'Ich hatte einen Ischias-Anfall. Die Ärztin hat mich gründlich untersucht und eine Anamnese erhoben; ich bekam Medikamente und Empfehlungen für die Zukunft, was ich vermeiden und was ich tun sollte, um mir selbst zu helfen. Eine sehr nette Ärztin – zugänglich, fürsorglich und ganz auf den Patienten eingestellt. Empfehlenswert.'), text_tr = COALESCE(text_tr, 'Siyatik krizi geçirdim. Doktor beni dikkatlice muayene etti, anamnezimi aldı; ilaç ve gelecekte nelerden kaçınmam, kendime yardımcı olmak için neler yapmam gerektiğine dair öneriler aldım. Çok hoş bir doktor: iletişimi güçlü, şefkatli ve hastaya odaklı. Tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2t0RlYwdE1hMUZzWTJ0VVlXOVpjemxSY1V3d00yYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Мој син је био код докторке за уши... Веома љубазна и пажљива. Мој син од 12 година ме је замолио да напишем рецензију јер је био веома задовољан. Каже да је докторка Рускиња/Украјинка, али да су се ипак споразумјели. Били су доступни и послије, преко WhatsApp-а, и одговорили су на питања. Хвала.'), text_en = COALESCE(text_en, 'My son saw the doctor about his ears... Very kind and attentive. My 12-year-old son asked me to write a review because he was very satisfied. He says the doctor is Russian/Ukrainian, but they understood each other anyway. They were also available afterwards via WhatsApp and answered our questions. Thank you.'), text_ru = COALESCE(text_ru, 'Мой сын был у врача по поводу ушей... Очень любезная и внимательная. Мой 12-летний сын попросил меня написать отзыв, потому что остался очень доволен. Говорит, что врач — русская/украинка, но они всё равно поняли друг друга. Потом они были на связи в WhatsApp и ответили на вопросы. Спасибо.'), text_de = COALESCE(text_de, 'Mein Sohn war wegen seiner Ohren bei der Ärztin... Sehr freundlich und aufmerksam. Mein 12-jähriger Sohn hat mich gebeten, eine Bewertung zu schreiben, weil er sehr zufrieden war. Er sagt, die Ärztin sei Russin/Ukrainerin, aber sie hätten sich trotzdem verständigt. Auch danach waren sie über WhatsApp erreichbar und haben unsere Fragen beantwortet. Danke.'), text_tr = COALESCE(text_tr, 'Oğlum kulakları için doktora gitti... Çok nazik ve özenli. 12 yaşındaki oğlum çok memnun kaldığı için benden bir yorum yazmamı istedi. Doktorun Rus/Ukraynalı olduğunu ama yine de anlaştıklarını söylüyor. Sonrasında WhatsApp üzerinden de ulaşılabilir oldular ve sorularımızı yanıtladılar. Teşekkürler.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pONGVsbE1lVVJpVFZrMU4xWnpjVTE0WWpkR1NHYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Одлична услуга, дивна докторка педијатар која се максимално посветила нашој беби.
Све похвале.'), text_en = COALESCE(text_en, 'Excellent service, a wonderful pediatrician who gave our baby her full attention.
All praise.'), text_ru = COALESCE(text_ru, 'Отличное обслуживание, чудесный педиатр, которая максимально уделила внимание нашему малышу.
Только похвалы.'), text_de = COALESCE(text_de, 'Ausgezeichneter Service, eine wunderbare Kinderärztin, die sich unserem Baby voll und ganz gewidmet hat.
Großes Lob.'), text_tr = COALESCE(text_tr, 'Mükemmel hizmet, bebeğimizle son derece ilgilenen harika bir çocuk doktoru.
Tebrikler.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xJelFUaE5OVXg2TlhBNVVteGlZbDlXVDJWeVMyYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Veoma smo zadovoljni njihovom brigom i pomoći. Tim je bio sjajan. Djelovali su veoma brzo i efikasno. Hvala vam mnogo na svemu.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома смо задовољни њиховом бригом и помоћи. Тим је био сјајан. Дјеловали су веома брзо и ефикасно. Хвала вам много на свему.'), text_ru = COALESCE(text_ru, 'Мы очень довольны их заботой и помощью. Команда была потрясающей. Действовали очень быстро и эффективно. Большое спасибо за всё.'), text_de = COALESCE(text_de, 'Wir sind mit ihrer Betreuung und Hilfe sehr zufrieden. Das Team war großartig. Sie haben sehr schnell und effizient gehandelt. Vielen herzlichen Dank für alles.'), text_tr = COALESCE(text_tr, 'İlgileri ve yardımlarından çok memnunuz. Ekip harikaydı. Çok hızlı ve etkili hareket ettiler. Her şey için çok teşekkür ederiz.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xaQlUwOU5jV1Z2VG1SMFNVa3RjWEJYVUdNM2JWRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Професионално особље које је одмах ријешило здравствени проблем мог дјетета, и то у касним вечерњим сатима. Од мене оцјена 10 за Medical Vranes 🤗'), text_en = COALESCE(text_en, 'Professional staff who immediately solved my child\'s health problem, and late in the evening at that. From me, a 10 out of 10 for Medical Vranes 🤗'), text_ru = COALESCE(text_ru, 'Профессиональный персонал, который сразу решил проблему со здоровьем моего ребёнка, причём поздно вечером. От меня оценка 10 для Medical Vranes 🤗'), text_de = COALESCE(text_de, 'Professionelles Personal, das das gesundheitliche Problem meines Kindes sofort gelöst hat – und das spät am Abend. Von mir eine 10 von 10 für Medical Vranes 🤗'), text_tr = COALESCE(text_tr, 'Çocuğumun sağlık sorununu hemen, üstelik gece geç saatlerde çözen profesyonel bir ekip. Benden Medical Vranes\'e 10 üzerinden 10 🤗') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xWd2IwbElXbVZLWVRabVdsTkpkV1o0VVVOamQyYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома сам захвална и задовољна екипом љекара којој није био проблем да дођу на кућну адресу због мале дјевојчице која је имала високу температуру, иако је било касно вече. Изузетно љубазни и дивни људи. За сваку препоруку!'), text_en = COALESCE(text_en, 'I am very grateful to and satisfied with the team of doctors, who had no problem coming to our home for a little girl with a high fever, even though it was late in the evening. Exceptionally kind and wonderful people. Highly recommended!'), text_ru = COALESCE(text_ru, 'Я очень благодарна и довольна командой врачей, которым было не трудно приехать на дом к маленькой девочке с высокой температурой, хотя был уже поздний вечер. Исключительно любезные и замечательные люди. Однозначно рекомендую!'), text_de = COALESCE(text_de, 'Ich bin dem Ärzteteam sehr dankbar und mit ihm sehr zufrieden – es war für sie kein Problem, zu uns nach Hause zu kommen, um ein kleines Mädchen mit hohem Fieber zu behandeln, obwohl es schon spät am Abend war. Außerordentlich freundliche und wunderbare Menschen. Absolut empfehlenswert!'), text_tr = COALESCE(text_tr, 'Gece geç saat olmasına rağmen yüksek ateşi olan küçük bir kız çocuğu için eve gelmekte hiç sorun görmeyen doktor ekibine çok minnettarım ve çok memnunum. Son derece nazik ve harika insanlar. Kesinlikle tavsiye ederim!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21wVlJIb3pjMDVGWDFRM1FWQm9jbEJMYmtWbWQzYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Hvala na brizi i terminu. Posjeta je protekla veoma dobro, a doktorka je stvar riješila veoma profesionalno – konkretno, skidanje konaca nakon povrede glave.
Hvala vam; preporučujem je.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Хвала на бризи и термину. Посјета је протекла веома добро, а докторка је ствар ријешила веома професионално – конкретно, скидање конаца након повреде главе.
Хвала вам; препоручујем је.'), text_ru = COALESCE(text_ru, 'Спасибо за заботу и за приём. Визит прошёл очень хорошо, врач подошла к делу очень профессионально — а именно сняла швы после травмы головы.
Спасибо, рекомендую её.'), text_de = COALESCE(text_de, 'Danke für die Betreuung und den Termin. Der Besuch verlief sehr gut, und die Ärztin hat die Angelegenheit äußerst professionell erledigt – konkret das Ziehen der Fäden nach einer Kopfverletzung.
Danke; ich kann sie empfehlen.'), text_tr = COALESCE(text_tr, 'İlginiz ve randevu için teşekkürler. Muayene çok iyi geçti ve doktor işi son derece profesyonelce halletti; yani kafa yaralanmasının ardından dikişlerin alınmasını.
Teşekkürler, kendisini tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25aalFUVTROakptYzNrMk1UTlljREJDTUZGQ2NHYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Брз договор преко Viber-а. Све препоруке!!!'), text_en = COALESCE(text_en, 'Quick arrangement via Viber. Highly recommended!!!'), text_ru = COALESCE(text_ru, 'Быстро договорились через Viber. Всем рекомендую!!!'), text_de = COALESCE(text_de, 'Schnelle Absprache über Viber. Absolut empfehlenswert!!!'), text_tr = COALESCE(text_tr, 'Viber üzerinden hızlıca anlaştık. Kesinlikle tavsiye ederim!!!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21WbFdtSlNiVGhuUVdsR1FYUnBZalJLVVc5eU4yYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Zaista dobra usluga i visokokvalifikovano osoblje, svakako ću preporučiti!'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Заиста добра услуга и висококвалификовано особље, свакако ћу препоручити!'), text_ru = COALESCE(text_ru, 'Действительно хорошее обслуживание и высококвалифицированный персонал, обязательно буду рекомендовать!'), text_de = COALESCE(text_de, 'Wirklich guter Service und hochqualifiziertes Personal, ich werde es auf jeden Fall weiterempfehlen!'), text_tr = COALESCE(text_tr, 'Gerçekten iyi hizmet ve son derece nitelikli personel, kesinlikle tavsiye edeceğim!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pKSVdHUmxObFZCZUhNeFNFTnVNbE5pU1VkelZHYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све што су написали други могу да потврдим, што се тиче Medical Vranes све најбоље, од комуникације до доласка докторке која је пажљива и брижна, а наравно и сјајан дијагностичар и љекар, све похвале!'), text_en = COALESCE(text_en, 'I can confirm everything others have written: as for Medical Vranes, nothing but the best, from the communication to the visit of the doctor, who is attentive and caring and, of course, an excellent diagnostician and physician. Full praise!'), text_ru = COALESCE(text_ru, 'Могу подтвердить всё, что написали другие: о Medical Vranes — только лучшее, от общения до визита врача, которая внимательна и заботлива и, конечно же, прекрасный диагност и доктор. Все похвалы!'), text_de = COALESCE(text_de, 'Ich kann alles bestätigen, was andere geschrieben haben: Bei Medical Vranes ist alles bestens, von der Kommunikation bis zum Besuch der Ärztin, die aufmerksam und fürsorglich und natürlich eine hervorragende Diagnostikerin und Ärztin ist. Volles Lob!'), text_tr = COALESCE(text_tr, 'Başkalarının yazdığı her şeyi onaylayabilirim: Medical Vranes konusunda her şey mükemmel, iletişimden doktor hanımın ziyaretine kadar. Kendisi dikkatli ve ilgili, elbette aynı zamanda harika bir teşhisçi ve hekim. Tüm övgüler!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21Kb1drZFlNVFJmVkRNd2VEVnRkRTlPUWpOVFgyYxAB';
UPDATE reviews SET text_en = COALESCE(text_en, 'I would like to praise the courtesy, professionalism and efficiency of the medical staff. During our holiday we used medical services through our travel insurance and the whole experience was excellent. The examination was arranged quickly, the staff were very kind and dedicated, and everything went smoothly without any problems. We thank them for their help and warmly recommend their services.'), text_ru = COALESCE(text_ru, 'Хочу отметить вежливость, профессионализм и оперативность медицинского персонала. Во время отпуска мы воспользовались медицинскими услугами по туристической страховке, и в целом впечатление было отличным. Осмотр организовали быстро, персонал был очень любезным и внимательным, всё прошло без каких-либо проблем. Благодарим за оказанную помощь и горячо рекомендуем их услуги.'), text_de = COALESCE(text_de, 'Ich möchte die Freundlichkeit, Professionalität und Effizienz des medizinischen Personals loben. Während unseres Urlaubs haben wir über unsere Reiseversicherung medizinische Leistungen in Anspruch genommen, und die gesamte Erfahrung war ausgezeichnet. Die Untersuchung wurde schnell organisiert, das Personal war sehr freundlich und engagiert, und alles verlief völlig problemlos. Wir bedanken uns für die Hilfe und empfehlen ihre Leistungen wärmstens.'), text_tr = COALESCE(text_tr, 'Sağlık personelinin nezaketini, profesyonelliğini ve verimliliğini övmek istiyorum. Tatilimiz sırasında seyahat sigortamız aracılığıyla sağlık hizmeti aldık ve genel deneyim mükemmeldi. Muayene hızla ayarlandı, personel çok nazik ve özverili idi ve her şey hiçbir sorun olmadan gerçekleşti. Yardımları için teşekkür eder, hizmetlerini içtenlikle tavsiye ederiz.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xSdGIwVmlRM1pITVVWNU5VVnNVMFJQTTNaT1EwRRAB';
UPDATE reviews SET text_en = COALESCE(text_en, 'Soon after I got in touch, I received a notification with the scheduled time when the doctor would come to the address where we were staying. The doctor is extremely kind, thorough and, above all, a good person. We are extremely satisfied with the medical service we needed! 🍀🥰🍀🏖️'), text_ru = COALESCE(text_ru, 'Вскоре после обращения я получила уведомление с назначенным временем, когда врач приедет по адресу, где мы жили. Доктор исключительно любезный, обстоятельный и прежде всего хороший человек. Мы очень довольны медицинской помощью, которая была нам так нужна! 🍀🥰🍀🏖️'), text_de = COALESCE(text_de, 'Kurz nach meiner Anmeldung erhielt ich eine Benachrichtigung mit dem vereinbarten Termin, zu dem der Arzt an die Adresse kommen würde, an der wir untergebracht waren. Der Arzt ist äußerst freundlich, gründlich und vor allem ein guter Mensch. Wir sind mit der medizinischen Leistung, die wir dringend brauchten, äußerst zufrieden! 🍀🥰🍀🏖️'), text_tr = COALESCE(text_tr, 'Başvurumdan kısa süre sonra, doktorun kaldığımız adrese geleceği randevu saatini içeren bir bildirim aldım. Doktor son derece nazik, titiz ve her şeyden önce iyi bir insan. İhtiyaç duyduğumuz sağlık hizmetinden son derece memnunuz! 🍀🥰🍀🏖️') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xrNGNtZEpkVEkxZWpaVVFsOXdRbmx2Y0VwTU0yYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Oba moja sina su imala problema tokom našeg boravka u Budvi: jedan je dobio stomačni virus, a drugi je pao i povrijedio glavu. Usluga je bila veoma brza i kvalitetna.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Оба моја сина су имала проблема током нашег боравка у Будви: један је добио стомачни вирус, а други је пао и повриједио главу. Услуга је била веома брза и квалитетна.'), text_ru = COALESCE(text_ru, 'Во время нашего пребывания в Будве у обоих моих сыновей были проблемы: один подхватил кишечную инфекцию, другой упал и ударился головой. Помощь была очень быстрой и качественной.'), text_de = COALESCE(text_de, 'Beide meiner Söhne hatten während unseres Aufenthalts in Budva Probleme: Einer hatte einen Magen-Darm-Infekt, der andere ist gestürzt und hat sich am Kopf verletzt. Der Service war sehr schnell und von hoher Qualität.'), text_tr = COALESCE(text_tr, 'Budva\'da kaldığımız süre boyunca iki oğlum da sorun yaşadı: biri mide virüsüne yakalandı, diğeri düşüp başını yaraladı. Hizmet çok hızlı ve kaliteliydi.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21KclFrdG1WRTFxV2pkWmJEbFRjRFp2YUVSNWMwRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Пријатно и љубазно особље 10+'), text_en = COALESCE(text_en, 'Pleasant and friendly staff 10+'), text_ru = COALESCE(text_ru, 'Приятный и вежливый персонал 10+'), text_de = COALESCE(text_de, 'Angenehmes und freundliches Personal 10+'), text_tr = COALESCE(text_tr, 'Hoş ve nazik personel 10+') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT213NVlXTXpiMVEyVVdJMGRtSlBOelk0YkcxcWVVRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Организовали су све тако да не морам далеко да идем од мјеста гдје сам смјештена, као и ортопеда који је дошао код мене у смјештај да ја не бих путовала далеко на преглед.'), text_en = COALESCE(text_en, 'They arranged everything so that I didn\'t have to go far from where I was staying, including an orthopedist who came to my accommodation so I wouldn\'t have to travel far for the examination.'), text_ru = COALESCE(text_ru, 'Всё организовали так, чтобы мне не пришлось далеко ехать от места, где я остановилась, — в том числе ортопеда, который приехал ко мне по месту проживания, чтобы мне не ездить далеко на осмотр.'), text_de = COALESCE(text_de, 'Sie haben alles so organisiert, dass ich mich nicht weit von meiner Unterkunft entfernen musste, einschließlich eines Orthopäden, der zu mir in die Unterkunft kam, damit ich für die Untersuchung nicht weit fahren musste.'), text_tr = COALESCE(text_tr, 'Kaldığım yerden uzağa gitmek zorunda kalmamam için her şeyi ayarladılar; muayene için uzağa gitmeyeyim diye konakladığım yere gelen bir ortopedi uzmanı da dahil.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xoNFVFZzJTVlZMU0dZd1YwWkVZa3hVU1ZCSWJWRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Двије године заредом љетујемо у Баошићима и докторка Елена из Vranes-а нас је лијечила обје године.
Свака препорука, брзина, квалитет, све на мјесту!
Нагласио бих да је докторка долазила код нас на адресу, што нам је било још практичније и лакше! Хвала вам!'), text_en = COALESCE(text_en, 'For two years in a row we have spent our summer holiday in Baošići, and Dr. Elena from Vranes treated us both years.
Highly recommended: speed, quality, everything is spot on!
I would point out that the doctor came to our address, which made it even more convenient and easier for us! Thank you!'), text_ru = COALESCE(text_ru, 'Уже два года подряд мы отдыхаем летом в Баошичах, и доктор Елена из Vranes лечила нас оба года.
Всячески рекомендую: скорость, качество — всё на высоте!
Отмечу, что доктор приезжала к нам по адресу, что было для нас ещё удобнее и проще! Спасибо вам!'), text_de = COALESCE(text_de, 'Zwei Jahre hintereinander verbringen wir den Sommerurlaub in Baošići, und Ärztin Elena von Vranes hat uns in beiden Jahren behandelt.
Absolute Empfehlung: Schnelligkeit, Qualität, alles stimmt!
Ich möchte hervorheben, dass die Ärztin zu uns an die Adresse kam, was für uns noch praktischer und einfacher war! Vielen Dank!'), text_tr = COALESCE(text_tr, 'İki yıldır üst üste yaz tatilimizi Baošići\'de geçiriyoruz ve Vranes\'ten Dr. Elena her iki yıl da bizi tedavi etti.
Kesinlikle tavsiye ederim: hız, kalite, her şey yerli yerinde!
Doktor hanımın adresimize geldiğini de belirtmek isterim, bu bizim için daha da pratik ve kolay oldu! Teşekkürler!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2s1aE5WRjJSMU51WVRGc1lXNTNlVXRNWVZsV2QxRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Pružili su mi pomoć tokom boravka u Albaniji.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Пружили су ми помоћ током боравка у Албанији.'), text_en = COALESCE(text_en, 'I received help during my stay in Albania.'), text_ru = COALESCE(text_ru, 'Мне оказали помощь во время пребывания в Албании.'), text_de = COALESCE(text_de, 'Mir wurde während meines Aufenthalts in Albanien geholfen.'), text_tr = COALESCE(text_tr, 'Arnavutluk\'ta kaldığım süre boyunca bana yardım edildi.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25sT1F6WklSRUpTWVhaUlFUVTVjbmhVWTB0alUwRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Tokom boravka u Crnoj Gori naš sin se razbolio i zahvaljujući putnom osiguranju vrlo brzo smo dobili pomoć u ovoj ustanovi. Osoblje je bilo ljubazno i profesionalno, i sve je proteklo bez zastoja. Veoma smo zahvalni na brizi i svakako preporučujemo ovo mjesto.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Током боравка у Црној Гори наш син се разболио и захваљујући путном осигурању врло брзо смо добили помоћ у овој установи. Особље је било љубазно и професионално, и све је протекло без застоја. Веома смо захвални на бризи и свакако препоручујемо ово мјесто.'), text_en = COALESCE(text_en, 'During our stay in Montenegro our son fell ill, and thanks to our travel insurance we received help at this facility very quickly. The staff were friendly and professional, and everything went smoothly. We are very grateful for the care and definitely recommend this place.'), text_ru = COALESCE(text_ru, 'Во время пребывания в Черногории наш сын заболел, и благодаря туристической страховке мы очень быстро получили помощь в этом учреждении. Персонал был вежливым и профессиональным, всё прошло без заминок. Мы очень благодарны за заботу и однозначно рекомендуем это место.'), text_de = COALESCE(text_de, 'Während unseres Aufenthalts in Montenegro wurde unser Sohn krank, und dank unserer Reiseversicherung haben wir in dieser Einrichtung sehr schnell Hilfe bekommen. Das Personal war freundlich und professionell, und alles lief reibungslos. Wir sind für die Betreuung sehr dankbar und empfehlen diese Einrichtung auf jeden Fall.'), text_tr = COALESCE(text_tr, 'Karadağ\'da kaldığımız süre boyunca oğlumuz hastalandı ve seyahat sigortamız sayesinde bu kurumda çok hızlı bir şekilde yardım aldık. Personel nazik ve profesyoneldi, her şey sorunsuz ilerledi. Gösterilen ilgi için çok minnettarız ve burayı kesinlikle tavsiye ediyoruz.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2sxUWJVSnRObU5oZVZOTGQwMVpkbmhEZUhabWFHYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Medical Vranes sam upoznala tokom ovogodišnjeg odmora u Crnoj Gori. Kontakt je bio jednostavan, ljekarska posjeta brzo dogovorena, a njihov trud i posvećenost bili su zaista dobri i vrijedni preporuke. Koristila sam urološku njegu — hvala vam!'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Medical Vranes сам упознала током овогодишњег одмора у Црној Гори. Контакт је био једноставан, љекарска посјета брзо договорена, а њихов труд и посвећеност били су заиста добри и вриједни препоруке. Користила сам уролошку његу — хвала вам!'), text_ru = COALESCE(text_ru, 'Я познакомилась с Medical Vranes во время отпуска в Черногории в этом году. Связаться было просто, визит врача организовали быстро, а их старания и самоотдача были на хорошем уровне и заслуживают рекомендации. Я обращалась за урологической помощью — спасибо вам!'), text_de = COALESCE(text_de, 'Ich habe Medical Vranes während meines diesjährigen Urlaubs in Montenegro kennengelernt. Die Kontaktaufnahme war einfach, der Arztbesuch wurde schnell organisiert, und ihr Einsatz und Engagement waren insgesamt gut und empfehlenswert. Ich habe urologische Versorgung in Anspruch genommen – vielen Dank!'), text_tr = COALESCE(text_tr, 'Medical Vranes ile bu yılki Karadağ tatilim sırasında tanıştım. İletişim kurmak kolaydı, doktor ziyareti hızla ayarlandı; gösterdikleri çaba ve özveri gerçekten iyiydi ve tavsiye etmeye değer. Üroloji hizmeti aldım — teşekkür ederim!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT210TmFUWTRia3BrWlU5Rk5GRXRWRWR0WmxoQlVrRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Doktorka me je primila istog dana, otišla je sa mnom do apoteke, stavila zavoj i objasnila kako da ga mijenjam. Nije prošao ni dan, a mojoj nozi je već bolje. Svakako preporučujem 👌🏻'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Докторка ме је примила истог дана, отишла је са мном до апотеке, ставила завој и објаснила како да га мијењам. Није прошао ни дан, а мојој нози је већ боље. Свакако препоручујем 👌🏻'), text_en = COALESCE(text_en, 'The doctor saw me the same day, went with me to the pharmacy, applied a dressing and explained how to change it. Not even a day has passed and my leg is already better. I definitely recommend 👌🏻'), text_ru = COALESCE(text_ru, 'Доктор приняла меня в тот же день, сходила со мной в аптеку, наложила повязку и объяснила, как её менять. Не прошло и дня, а моей ноге уже лучше. Однозначно рекомендую 👌🏻'), text_de = COALESCE(text_de, 'Die Ärztin hat mich noch am selben Tag behandelt, ist mit mir zur Apotheke gegangen, hat einen Verband angelegt und erklärt, wie ich ihn wechseln soll. Es ist nicht einmal ein Tag vergangen, und meinem Bein geht es schon besser. Absolut empfehlenswert 👌🏻'), text_tr = COALESCE(text_tr, 'Doktor hanım beni aynı gün muayene etti, benimle eczaneye geldi, pansuman yaptı ve nasıl değiştireceğimi anlattı. Daha bir gün bile geçmeden bacağım şimdiden daha iyi. Kesinlikle tavsiye ederim 👌🏻') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25scU9GOU5UMVI1T1c5S1dtdHpWa2hvY0dKVk9FRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Доктори су љубазни и професионални'), text_en = COALESCE(text_en, 'The doctors are friendly and professional'), text_ru = COALESCE(text_ru, 'Врачи вежливые и профессиональные'), text_de = COALESCE(text_de, 'Die Ärzte sind freundlich und professionell'), text_tr = COALESCE(text_tr, 'Doktorlar nazik ve profesyonel') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xOTFpIQlNWbU5aWDJreFVYUjBWR3RSVkRaSVJtYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Диван љекар, рекордно брза услуга, преглед обављен код нас у смјештају, преко DDOR осигурања и без плаћања. Све препоруке!'), text_en = COALESCE(text_en, 'A wonderful doctor, record-fast service, the examination was done at our accommodation, through DDOR insurance and without any payment. Highly recommended!'), text_ru = COALESCE(text_ru, 'Замечательный врач, рекордно быстрое обслуживание, осмотр провели прямо у нас по месту проживания, по страховке DDOR и без оплаты. Всячески рекомендую!'), text_de = COALESCE(text_de, 'Ein wunderbarer Arzt, rekordverdächtig schneller Service, die Untersuchung fand bei uns in der Unterkunft statt, über die DDOR-Versicherung und ohne Bezahlung. Absolute Empfehlung!'), text_tr = COALESCE(text_tr, 'Harika bir doktor, rekor hızda hizmet; muayene konakladığımız yerde, DDOR sigortası üzerinden ve hiçbir ücret ödemeden yapıldı. Kesinlikle tavsiye ederim!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21aSFMwNWZSbWRQZUd0eGJVVldka2RTYm1wYWNYYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Изузетно пословни и тачни, презадовољни смо услугом. Свака похвала и препорука.'), text_en = COALESCE(text_en, 'Extremely businesslike and punctual, we are more than satisfied with the service. Full praise and recommendation.'), text_ru = COALESCE(text_ru, 'Очень деловые и пунктуальные, мы более чем довольны обслуживанием. Все похвалы и рекомендации.'), text_de = COALESCE(text_de, 'Äußerst professionell und pünktlich, wir sind mit dem Service mehr als zufrieden. Volles Lob und klare Empfehlung.'), text_tr = COALESCE(text_tr, 'Son derece işini bilen ve dakikler, hizmetten fazlasıyla memnunuz. Tüm övgüler ve tavsiyeler.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25kR1ZHdDJXV2hSVTJSalpXbHZjMVV5UlhwblduYxAB';
