UPDATE reviews SET text_sr = COALESCE(text_sr, 'Primili su nas veoma brzo. Došli smo s putnim zdravstvenim osiguranjem i za manje od sat vremena su nas kontaktirali i zakazali pregled za isti dan. Veoma lijep odnos, preporučujem.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Примили су нас веома брзо. Дошли смо с путним здравственим осигурањем и за мање од сат времена су нас контактирали и заказали преглед за исти дан. Веома лијеп однос, препоручујем.'), text_en = COALESCE(text_en, 'They saw us very quickly. We came with our travel health insurance, and in less than an hour they contacted us and booked an appointment for the same day. Very good treatment, recommended.'), text_ru = COALESCE(text_ru, 'Нас приняли очень быстро. Мы обратились по туристической медицинской страховке, и меньше чем через час с нами связались и записали на приём в тот же день. Очень хорошее отношение, рекомендую.'), text_de = COALESCE(text_de, 'Wir wurden sehr schnell versorgt. Wir kamen über unsere Reisekrankenversicherung, und in weniger als einer Stunde wurden wir kontaktiert und bekamen einen Termin noch am selben Tag. Sehr freundliche Betreuung, empfehlenswert.'), text_tr = COALESCE(text_tr, 'Bizimle çok hızlı ilgilendiler. Seyahat sağlık sigortamızla başvurduk; bir saatten kısa sürede bizimle iletişime geçip aynı gün için randevu verdiler. Çok iyi bir ilgi, tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xReU9WWTJZV1JEYUdzMFpYUlBhMHRYV1dKcFJVRRAB';
