UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Желим да похвалим докторку и доктора, јуче су били код нас у Херцег Новом у апартману, прегледали супруга и мене, дали терапију. Брзо су стигли, лијепо прегледали, љубазни. Оцјена 5, свака препорука. Маја, Земун. Хвала још једном.'), text_en = COALESCE(text_en, 'I want to praise the doctors, a woman and a man, who came to our apartment in Herceg Novi yesterday, examined my husband and me and gave us treatment. They arrived quickly, examined us thoroughly and were kind. A 5 out of 5, highly recommended. Maja, Zemun. Thank you once again.'), text_ru = COALESCE(text_ru, 'Хочу поблагодарить врачей — женщину и мужчину: вчера они приезжали к нам в апартаменты в Херцег-Нови, осмотрели мужа и меня, назначили лечение. Приехали быстро, хорошо осмотрели, вежливые. Оценка 5, всем рекомендую. Майя, Земун. Ещё раз спасибо.'), text_de = COALESCE(text_de, 'Ich möchte die Ärztin und den Arzt loben, die gestern zu uns ins Apartment in Herceg Novi gekommen sind, meinen Mann und mich untersucht und uns eine Therapie gegeben haben. Sie kamen schnell, haben gründlich untersucht und waren freundlich. Note 5, absolut empfehlenswert. Maja, Zemun. Nochmals vielen Dank.'), text_tr = COALESCE(text_tr, 'Dün Herceg Novi\'deki dairemize gelen kadın ve erkek doktoru övmek istiyorum; eşimi ve beni muayene edip tedavi verdiler. Hızlı geldiler, güzelce muayene ettiler, çok naziktiler. 5 üzerinden 5, kesinlikle tavsiye ederim. Maja, Zemun. Bir kez daha teşekkürler.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2t4UldrTktaRWxmVTJoRloyRk5NMGh0VDBWdWJYYxAB';
