UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома добра комуникација, излазак доктора на терен и преглед љекара веома добар и ефикасан'), text_en = COALESCE(text_en, 'Very good communication; the doctor\'s home visit and the examination were very good and efficient'), text_ru = COALESCE(text_ru, 'Очень хорошая коммуникация, выезд врача на дом и осмотр — очень хорошо и эффективно'), text_de = COALESCE(text_de, 'Sehr gute Kommunikation; der Hausbesuch des Arztes und die Untersuchung waren sehr gut und effizient'), text_tr = COALESCE(text_tr, 'Çok iyi iletişim; doktorun ev ziyareti ve muayenesi çok iyi ve etkiliydi') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25FNGRreDZSbTB3VlU5SWRHcHFUVkZKZURkR04yYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Hvala na pomoći i ljekarskoj posjeti u mom hotelu u okviru mog osiguranja :)'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Хвала на помоћи и љекарској посјети у мом хотелу у оквиру мог осигурања :)'), text_en = COALESCE(text_en, 'Thank you for the help and the doctor\'s visit to my hotel under my insurance :)'), text_ru = COALESCE(text_ru, 'Спасибо за помощь и визит врача ко мне в отель по моей страховке :)'), text_de = COALESCE(text_de, 'Danke für die Hilfe und den Arztbesuch in meinem Hotel im Rahmen meiner Versicherung :)'), text_tr = COALESCE(text_tr, 'Yardımınız ve sigortam kapsamında otelime yapılan doktor ziyareti için teşekkürler :)') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tveFdGUXpiamR2YTFoYWJFaGhiVWR5TnkxQk5IYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Bila sam prijatno iznenađena odnosom i susretljivošću osoblja. Dovela sam sina od 8 godina s visokom temperaturom. Veoma dobra pedijatrica, s velikom pažnjom se odnijela prema njemu i pregledala ga. Nakon rezultata analiza propisala je terapiju. Zahvaljujem se ovoj klinici'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Била сам пријатно изненађена односом и сусретљивошћу особља. Довела сам сина од 8 година с високом температуром. Веома добра педијатрица, с великом пажњом се однијела према њему и прегледала га. Након резултата анализа прописала је терапију. Захваљујем се овој клиници'), text_en = COALESCE(text_en, 'I was pleasantly surprised by the staff\'s attitude and helpfulness. I brought my 8-year-old son with a high fever. A very good pediatrician, she treated him with great care and examined him. After the test results she prescribed treatment. Thank you to this clinic'), text_de = COALESCE(text_de, 'Ich war angenehm überrascht von der Haltung und Hilfsbereitschaft des Personals. Ich kam mit meinem 8-jährigen Sohn, der hohes Fieber hatte. Eine sehr gute Kinderärztin, sie hat sich mit großer Sorgfalt um ihn gekümmert und ihn untersucht. Nach den Laborergebnissen hat sie eine Behandlung verordnet. Ich danke dieser Klinik'), text_tr = COALESCE(text_tr, 'Personelin tavrı ve yardımseverliği beni hoş bir şekilde şaşırttı. 8 yaşındaki oğlumu yüksek ateşle götürdüm. Çok iyi bir çocuk doktoru, ona büyük bir özenle yaklaştı ve muayene etti. Tahlil sonuçlarından sonra tedavi verdi. Bu kliniğe teşekkür ederim') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25JeFlXOUtWVXczVjNkRWVtNWhTek5rY1hOVGVGRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Veoma dobar i brz kontakt. Trebala mi je pomoć zbog bola u uhu tokom odmora u Crnoj Gori; ljekar je stigao veoma brzo, a i komunikacija na engleskom je bila laka. Pregledali su me i propisali lijekove. Od srca preporučujem😊'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома добар и брз контакт. Требала ми је помоћ због бола у уху током одмора у Црној Гори; љекар је стигао веома брзо, а и комуникација на енглеском је била лака. Прегледали су ме и прописали лијекове. Од срца препоручујем😊'), text_en = COALESCE(text_en, 'Very good and quick contact. I needed help because of an earache during my holiday in Montenegro; the doctor arrived very quickly, and communicating in English was easy too. I was examined and prescribed medication. I recommend them wholeheartedly😊'), text_ru = COALESCE(text_ru, 'Очень хорошая и быстрая связь. Мне понадобилась помощь из-за боли в ухе во время отпуска в Черногории; врач приехал очень быстро, и общаться по-английски тоже было легко. Меня осмотрели и выписали лекарства. Рекомендую от всего сердца😊'), text_de = COALESCE(text_de, 'Sehr guter und schneller Kontakt. Ich brauchte während meines Urlaubs in Montenegro Hilfe wegen Ohrenschmerzen; der Arzt kam sehr schnell, und die Verständigung auf Englisch war auch einfach. Ich wurde untersucht und bekam Medikamente verschrieben. Von ganzem Herzen empfehlenswert😊'), text_tr = COALESCE(text_tr, 'Çok iyi ve hızlı iletişim. Karadağ\'daki tatilim sırasında kulak ağrısı nedeniyle yardıma ihtiyacım oldu; doktor çok çabuk geldi ve İngilizce iletişim de kolaydı. Muayene edildim ve ilaç yazıldı. Tüm kalbimle tavsiye ederim😊') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT210eVFsTmZObUppWjJsVVgycFNSMEYxY2tSUU4yYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Divna klinika! Ljekari pažljivi, stručni, stigli su na vrijeme, propisali recepte za potrebne lijekove. Usluga je odlično obavljena.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Дивна клиника! Љекари пажљиви, стручни, стигли су на вријеме, прописали рецепте за потребне лијекове. Услуга је одлично обављена.'), text_en = COALESCE(text_en, 'A wonderful clinic! The doctors are attentive and qualified, arrived on time and wrote prescriptions for the necessary medication. Excellent service.'), text_de = COALESCE(text_de, 'Eine wunderbare Klinik! Die Ärzte sind aufmerksam und kompetent, kamen pünktlich und stellten Rezepte für die nötigen Medikamente aus. Ausgezeichneter Service.'), text_tr = COALESCE(text_tr, 'Harika bir klinik! Doktorlar ilgili ve yetkin, zamanında geldiler, gerekli ilaçların reçetelerini yazdılar. Hizmet mükemmeldi.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xwR1RtRXdObmQyVm00M2JWQXdXaTFNTlRkb1FVRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Професионални, брзи, љубазни, услужни. Свака част'), text_en = COALESCE(text_en, 'Professional, fast, kind, helpful. Well done'), text_ru = COALESCE(text_ru, 'Профессиональные, быстрые, вежливые, услужливые. Моё уважение'), text_de = COALESCE(text_de, 'Professionell, schnell, freundlich, hilfsbereit. Hut ab'), text_tr = COALESCE(text_tr, 'Profesyonel, hızlı, nazik, yardımsever. Helal olsun') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT201R1ZrWlVXRWxUYzNad1NETnVTMWRzZW5aUFJHYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома сам задовољан прегледом свог дјетета. Особље је изузетно љубазно, професионално и стрпљиво, а доктори су посветили довољно времена да све детаљно објасне. Преглед је обављен темељно, с доласком на адресу, а приступ дјетету је био пун пажње и разумијевања, што нам је много значило. Све похвале за услугу, стручност и пријатну атмосферу. Топла препорука свима који траже квалитетну здравствену његу за своју дјецу!'), text_en = COALESCE(text_en, 'I am very satisfied with my child\'s examination. The staff are extremely kind, professional and patient, and the doctors took enough time to explain everything in detail. The examination was thorough, done at our address, and their approach to the child was full of care and understanding, which meant a lot to us. All praise for the service, expertise and pleasant atmosphere. A warm recommendation to anyone looking for quality healthcare for their children!'), text_ru = COALESCE(text_ru, 'Я очень доволен осмотром своего ребёнка. Персонал исключительно вежливый, профессиональный и терпеливый, а врачи уделили достаточно времени, чтобы всё подробно объяснить. Осмотр провели тщательно, с выездом на дом, а подход к ребёнку был полон внимания и понимания, что для нас очень много значило. Только похвалы за обслуживание, профессионализм и приятную атмосферу. Горячо рекомендую всем, кто ищет качественную медицинскую помощь для своих детей!'), text_de = COALESCE(text_de, 'Ich bin mit der Untersuchung meines Kindes sehr zufrieden. Das Personal ist äußerst freundlich, professionell und geduldig, und die Ärzte haben sich genug Zeit genommen, alles ausführlich zu erklären. Die Untersuchung war gründlich und fand bei uns zu Hause statt, und der Umgang mit dem Kind war voller Aufmerksamkeit und Verständnis, was uns viel bedeutet hat. Großes Lob für den Service, die Fachkompetenz und die angenehme Atmosphäre. Eine herzliche Empfehlung für alle, die eine gute medizinische Versorgung für ihre Kinder suchen!'), text_tr = COALESCE(text_tr, 'Çocuğumun muayenesinden çok memnunum. Personel son derece nazik, profesyonel ve sabırlı; doktorlar her şeyi ayrıntılı açıklamak için yeterince zaman ayırdı. Muayene adrese gelinerek titizlikle yapıldı ve çocuğa yaklaşımları ilgi ve anlayış doluydu, bu bizim için çok önemliydi. Hizmet, uzmanlık ve hoş atmosfer için tebrikler. Çocukları için kaliteli sağlık hizmeti arayan herkese gönülden tavsiye ederim!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tkMGFVOVhiM1Z3YkVsUFdUWTJUa2hhZERsdE9XYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Прије свега дивни људи и диван колектив. Веома љубазни, пријатни, насмијани, позитивни и професионални. Од самог пријема за педијатријски преглед, преко прегледа до извјештаја — мало је рећи да смо одушевљени и презахвални. Брза, лака и једноставна комуникација и договор. Госпођица која нас је дочекала првог дана и ради на спрату је дивна, а докторка госпођа Весна Костић веома професионална, брижна и пријатна. Свака препорука за професионалце.'), text_en = COALESCE(text_en, 'First of all, wonderful people and a lovely team. Very kind, pleasant, smiling, positive and professional. From the moment we were admitted for the pediatric examination, through the examination itself, to the report, it is an understatement to say we are delighted and extremely grateful. Quick, easy and simple communication and arrangements. The young lady who welcomed us on the first day and works upstairs is wonderful, and the doctor, Mrs Vesna Kostić, is very professional, caring and pleasant. Highly recommended — true professionals.'), text_ru = COALESCE(text_ru, 'Прежде всего — прекрасные люди и чудесный коллектив. Очень вежливые, приятные, улыбчивые, позитивные и профессиональные. От самого приёма на педиатрический осмотр, через осмотр и до заключения — мало сказать, что мы в восторге и безмерно благодарны. Быстрая, лёгкая и простая связь и договорённость. Девушка, которая встретила нас в первый день и работает на этаже, — замечательная, а доктор, госпожа Весна Костич, очень профессиональная, заботливая и приятная. Всем рекомендую этих профессионалов.'), text_de = COALESCE(text_de, 'Vor allem wunderbare Menschen und ein tolles Team. Sehr freundlich, angenehm, lächelnd, positiv und professionell. Von der Aufnahme zur kinderärztlichen Untersuchung über die Untersuchung selbst bis zum Befund – es wäre untertrieben zu sagen, dass wir begeistert und überaus dankbar sind. Schnelle, einfache und unkomplizierte Kommunikation und Absprache. Die junge Frau, die uns am ersten Tag empfangen hat und oben arbeitet, ist wunderbar, und die Ärztin, Frau Vesna Kostić, ist sehr professionell, fürsorglich und angenehm. Absolute Empfehlung für diese Profis.'), text_tr = COALESCE(text_tr, 'Her şeyden önce harika insanlar ve harika bir ekip. Çok nazik, hoş, güler yüzlü, pozitif ve profesyoneller. Pediatri muayenesi için kabulden muayeneye ve rapora kadar, çok memnun ve minnettar olduğumuzu söylemek az kalır. Hızlı, kolay ve basit iletişim ve randevu. İlk gün bizi karşılayan ve üst katta çalışan genç hanım harika, doktor Vesna Kostić Hanım ise çok profesyonel, şefkatli ve hoş biri. Bu profesyonelleri kesinlikle tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xwWk5XWnNSekZuZFVWcFdWTlhXVnBqVm1kRmJYYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Прије свега све похвале за Мају, која је у рекордном року заказала преглед за Ђорђа, и дивна др Весна Костић, препуна стрпљења и стручности. Још једном хвала и све препоруке за клинику ☺️🥰❤️'), text_en = COALESCE(text_en, 'First of all, all praise to Maja, who booked an appointment for Đorđe in record time, and the wonderful Dr Vesna Kostić, full of patience and expertise. Thanks once again, and the clinic is highly recommended ☺️🥰❤️'), text_ru = COALESCE(text_ru, 'Прежде всего огромная благодарность Майе, которая в рекордные сроки записала Джордже на осмотр, и замечательной доктору Весне Костич — само терпение и профессионализм. Ещё раз спасибо, всем рекомендую клинику ☺️🥰❤️'), text_de = COALESCE(text_de, 'Vor allem großes Lob an Maja, die in Rekordzeit einen Termin für Đorđe vereinbart hat, und an die wunderbare Dr. Vesna Kostić, voller Geduld und Fachkompetenz. Nochmals danke, die Klinik ist absolut empfehlenswert ☺️🥰❤️'), text_tr = COALESCE(text_tr, 'Her şeyden önce Đorđe için rekor sürede randevu ayarlayan Maja\'ya ve sabır ve uzmanlık dolu harika Dr. Vesna Kostić\'e tebrikler. Bir kez daha teşekkürler, kliniği kesinlikle tavsiye ederim ☺️🥰❤️') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pkU1ZtRnRNWEoyV21jeVJVbG5UWGd0U0d0WmNVRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Љубазни, тачни, професионални.'), text_en = COALESCE(text_en, 'Kind, punctual, professional.'), text_ru = COALESCE(text_ru, 'Вежливые, пунктуальные, профессиональные.'), text_de = COALESCE(text_de, 'Freundlich, pünktlich, professionell.'), text_tr = COALESCE(text_tr, 'Nazik, dakik, profesyonel.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xKaVdEWTVhSFpyUjFkVU5sWkphbkZtWDJKWmRrRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Докторка је била дивна и љубазна. Има одличан приступ раду с дјецом.'), text_en = COALESCE(text_en, 'The doctor was wonderful and kind. She has an excellent way with children.'), text_ru = COALESCE(text_ru, 'Доктор была замечательной и вежливой. У неё отличный подход к детям.'), text_de = COALESCE(text_de, 'Die Ärztin war wunderbar und freundlich. Sie hat einen hervorragenden Umgang mit Kindern.'), text_tr = COALESCE(text_tr, 'Doktor harika ve nazikti. Çocuklarla çalışmada mükemmel bir yaklaşımı var.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2t3NFoyRmFaMnhLVkZaM1ZVcGZUekJZV2xwMVdtYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома љубазни и стручни, све препоруке.'), text_en = COALESCE(text_en, 'Very kind and competent, highly recommended.'), text_ru = COALESCE(text_ru, 'Очень вежливые и профессиональные, всем рекомендую.'), text_de = COALESCE(text_de, 'Sehr freundlich und kompetent, absolut empfehlenswert.'), text_tr = COALESCE(text_tr, 'Çok nazik ve uzmanlar, kesinlikle tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT20xeFprTkxlVkJqWTBoalJqUldWVVJxZW5CUVNWRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Позитивно искуство, љубазно и стручно особље'), text_en = COALESCE(text_en, 'A positive experience, kind and competent staff'), text_ru = COALESCE(text_ru, 'Положительный опыт, вежливый и квалифицированный персонал'), text_de = COALESCE(text_de, 'Positive Erfahrung, freundliches und kompetentes Personal'), text_tr = COALESCE(text_tr, 'Olumlu bir deneyim, nazik ve uzman personel') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21ObWRrSjJZakJ3VDNsbmNuVTVlR00zUzNsUFdWRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Докторка је дошла кад је дијете имало температуру. Задовољни смо прегледом и стручношћу докторке.'), text_en = COALESCE(text_en, 'The doctor came when our child had a fever. We are satisfied with the examination and the doctor\'s expertise.'), text_ru = COALESCE(text_ru, 'Доктор приехала, когда у ребёнка была температура. Мы довольны осмотром и профессионализмом врача.'), text_de = COALESCE(text_de, 'Die Ärztin kam, als unser Kind Fieber hatte. Wir sind mit der Untersuchung und der Fachkompetenz der Ärztin zufrieden.'), text_tr = COALESCE(text_tr, 'Çocuğumuzun ateşi olduğunda doktor geldi. Muayeneden ve doktorun uzmanlığından memnunuz.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pKclNXaGhkRU5pVUZkQlJHVmZPWE4zYTJWbFVIYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све похвале за стручност и љубазност!'), text_en = COALESCE(text_en, 'All praise for the expertise and kindness!'), text_ru = COALESCE(text_ru, 'Только похвалы за профессионализм и вежливость!'), text_de = COALESCE(text_de, 'Großes Lob für Kompetenz und Freundlichkeit!'), text_tr = COALESCE(text_tr, 'Uzmanlık ve nezaket için tebrikler!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25KS2FEQm1iR2s1YjNGcmRtNXFielpwZFhBNE5IYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Imao sam problem s okom — iznenada se upalilo i vid mi je bio prilično oslabljen. Ljekar je stigao vrlo brzo nakon mog poziva zdravstvenom osiguranju i obavio temeljan pregled. Propisani lijekovi su bili odgovarajući, a savjet da se uradi dodatni pregled kod specijaliste bio je potpuno opravdan. Ubrzo nakon liječenja oko mi je ponovo bilo u funkciji. Komunikacija sa Medical Vranes preko WhatsAppa bila je savršena. Toplo preporučujem svima.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Имао сам проблем с оком — изненада се упалило и вид ми је био прилично ослабљен. Љекар је стигао врло брзо након мог позива здравственом осигурању и обавио темељан преглед. Прописани лијекови су били одговарајући, а савјет да се уради додатни преглед код специјалисте био је потпуно оправдан. Убрзо након лијечења око ми је поново било у функцији. Комуникација са Medical Vranes преко WhatsApp-а била је савршена. Топло препоручујем свима.'), text_ru = COALESCE(text_ru, 'У меня внезапно воспалился глаз, и зрение заметно ухудшилось. Врач приехал очень быстро после моего звонка в медицинскую страховую и провёл тщательный осмотр. Назначенные лекарства подошли, а рекомендация дополнительно обследоваться у специалиста была полностью обоснованной. Вскоре после лечения глаз снова стал нормально видеть. Общение с Medical Vranes через WhatsApp было идеальным. Очень рекомендую всем.'), text_de = COALESCE(text_de, 'Mein Auge hatte sich plötzlich entzündet, und meine Sehkraft war ziemlich beeinträchtigt. Der Arzt kam sehr schnell nach meinem Anruf bei der Krankenversicherung und führte eine gründliche Untersuchung durch. Die verschriebenen Medikamente waren angemessen, und die empfohlene weitere Abklärung beim Facharzt war völlig berechtigt. Kurz nach der Behandlung funktionierte mein Auge wieder. Die Kommunikation mit Medical Vranes über WhatsApp war perfekt. Für jeden sehr zu empfehlen.'), text_tr = COALESCE(text_tr, 'Gözüm aniden iltihaplandı ve görmem epeyce etkilendi. Sağlık sigortamı aradıktan çok kısa süre sonra doktor geldi ve kapsamlı bir muayene yaptı. Reçete edilen ilaçlar uygundu ve uzman tarafından ek tetkik yapılması tavsiyesi tamamen yerindeydi. Tedaviden kısa süre sonra gözüm yeniden işlevini kazandı. Medical Vranes ile WhatsApp üzerinden iletişim mükemmeldi. Herkese şiddetle tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25Kb2FFSk5NbloxY0c5bFMyZDFSVkl0UVVkbGJuYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'U Beogradu, u Srbiji, u hotelu u kojem sam odsjela, pregledala me je vrlo efikasna ljekarka.
Pregledala me je i dala mi lijek, tako da mi je već bolje.
Veoma dobra usluga.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'У Београду, у Србији, у хотелу у којем сам одсјела, прегледала ме је врло ефикасна љекарка.
Прегледала ме је и дала ми лијек, тако да ми је већ боље.
Веома добра услуга.'), text_en = COALESCE(text_en, 'I was seen in Belgrade, Serbia, by a very efficient doctor at the hotel where I was staying.
She examined me and gave me medication, and I\'m already feeling better.
Very good service.'), text_ru = COALESCE(text_ru, 'В Белграде (Сербия) меня приняла очень толковая врач прямо в отеле, где я остановилась.
Она осмотрела меня и дала лекарство, и мне уже лучше.
Очень хороший сервис.'), text_de = COALESCE(text_de, 'In Belgrad, Serbien, wurde ich in meinem Hotel von einer sehr effizienten Ärztin behandelt.
Sie hat mich untersucht und mir ein Medikament gegeben, sodass es mir schon besser geht.
Sehr guter Service.'), text_tr = COALESCE(text_tr, 'Sırbistan\'ın Belgrad şehrinde, kaldığım otelde çok işini bilen bir kadın doktor beni muayene etti.
Beni muayene edip ilaç verdi, şimdiden daha iyiyim.
Çok iyi hizmet.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tGYVMwcE5VMFZ3U1dvNVZFTm1TR1ZKYUZaRVJtYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Veliko hvala kompaniji Medical Vranes na jasnoj i brzoj podršci u rješavanju zdravstvenih problema: akutni napad bola u krstima mogao je da pokvari cijelo putovanje. Organizovani su pregled kod ljekara i konsultacija, propisana je terapija (injekcije). Pošto smo putovali od mjesta do mjesta, injekcije su davane u različitim gradovima. Klinike su birane u blizini mjesta smještaja. Dobili smo i izvještaje o liječenju. Veliko hvala na pomoći u teškom trenutku.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Велико хвала компанији Medical Vranes на јасној и брзој подршци у рјешавању здравствених проблема: акутни напад бола у крстима могао је да поквари цијело путовање. Организовани су преглед код љекара и консултација, прописана је терапија (ињекције). Пошто смо путовали од мјеста до мјеста, ињекције су даване у различитим градовима. Клинике су биране у близини мјеста смјештаја. Добили смо и извјештаје о лијечењу. Велико хвала на помоћи у тешком тренутку.'), text_en = COALESCE(text_en, 'Many thanks to Medical Vranes for their clear and prompt support with our health problems: an acute attack of lower back pain could have ruined the whole trip. They arranged a doctor\'s appointment and consultation, and treatment (injections) was prescribed. Since we were travelling from place to place, the injections were given in different towns. The clinics were chosen close to where we were staying. Treatment reports were provided. Many thanks for the help at a difficult moment.'), text_de = COALESCE(text_de, 'Vielen Dank an Medical Vranes für die klare und schnelle Unterstützung bei unseren gesundheitlichen Problemen: Ein akuter Anfall von Kreuzschmerzen hätte die ganze Reise verderben können. Es wurden ein Arzttermin und eine Beratung organisiert und eine Behandlung (Injektionen) verordnet. Da wir eine Rundreise machten, bekamen wir die Spritzen in verschiedenen Städten. Die Kliniken wurden jeweils in der Nähe unserer Unterkunft ausgewählt. Behandlungsberichte wurden zur Verfügung gestellt. Vielen Dank für die Hilfe in einer schwierigen Situation.'), text_tr = COALESCE(text_tr, 'Sağlık sorunlarımızın çözümünde verdikleri net ve hızlı destek için Medical Vranes\'e çok teşekkür ederiz: Bel bölgesindeki ani ve şiddetli ağrı bütün seyahati mahvedebilirdi. Doktor randevusu ve konsültasyon ayarlandı, tedavi (enjeksiyonlar) reçete edildi. Şehirden şehre gezdiğimiz için iğneler farklı şehirlerde yapıldı. Klinikler kaldığımız yerin yakınından seçildi. Tedavi raporları da verildi. Zor bir anda yardımcı oldukları için çok teşekkürler.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tsbFkyOVVMV3g1YTBWZlNXSlZWV0o2ZWw4dFQzYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Презадовољни услугом! За сваку препоруку!'), text_en = COALESCE(text_en, 'Extremely happy with the service! Highly recommended!'), text_ru = COALESCE(text_ru, 'Более чем довольны обслуживанием! Однозначно рекомендуем!'), text_de = COALESCE(text_de, 'Überaus zufrieden mit dem Service! Absolut empfehlenswert!'), text_tr = COALESCE(text_tr, 'Hizmetten son derece memnunuz! Kesinlikle tavsiye ederiz!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tKZk1WTkhSVlJCWmtvNGJtZGxUblpJU1ROemNrRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Željeli bismo da zahvalimo dr Marini na stručnoj pomoći.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Жељели бисмо да захвалимо др Марини на стручној помоћи.'), text_ru = COALESCE(text_ru, 'Хотим поблагодарить доктора Марину за профессиональную помощь.'), text_de = COALESCE(text_de, 'Wir möchten Dr. Marina für ihre fachkundige Hilfe danken.'), text_tr = COALESCE(text_tr, 'Uzman yardımı için Dr. Marina\'ya teşekkür etmek isteriz.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT214MlMwWlNXblIzZFZsMVpUWm1hRmhxTm0xemJFRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Komunikacija preko WhatsAppa bila je jednostavna i praktična. Tim je bio pristupačan, brz i fleksibilan pri zakazivanju termina. Hitno nam je bio potreban pedijatar za bebu, i konsultacija je organizovana istog dana. Cijeli proces je protekao glatko i efikasno, i bili smo veoma zadovoljni uslugom.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Комуникација преко WhatsApp-а била је једноставна и практична. Тим је био приступачан, брз и флексибилан при заказивању термина. Хитно нам је био потребан педијатар за бебу, и консултација је организована истог дана. Цијели процес је протекао глатко и ефикасно, и били смо веома задовољни услугом.'), text_ru = COALESCE(text_ru, 'Общаться через WhatsApp было просто и удобно. Команда быстро отвечала, действовала оперативно и гибко подошла к записи. Нам срочно понадобился педиатр для малыша, и консультацию организовали в тот же день. Всё прошло гладко и чётко, мы остались очень довольны обслуживанием.'), text_de = COALESCE(text_de, 'Die Kommunikation über WhatsApp war einfach und bequem. Das Team reagierte schnell, war zügig und flexibel bei der Terminvereinbarung. Wir brauchten kurzfristig einen Kinderarzt für unser Baby, und die Konsultation wurde noch am selben Tag organisiert. Alles lief reibungslos und effizient, wir waren mit dem Service sehr zufrieden.'), text_tr = COALESCE(text_tr, 'WhatsApp üzerinden iletişim kolay ve pratikti. Ekip randevu ayarlarken ilgili, hızlı ve esnekti. Bebeğimiz için kısa sürede bir çocuk doktoruna ihtiyacımız vardı ve konsültasyon aynı gün ayarlandı. Tüm süreç sorunsuz ve verimli geçti, hizmetten çok memnun kaldık.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT21oT1VsbHdZVFkzWm5ORFJVcHVRemcxV1dGVlJGRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'dobra usluga'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'добра услуга'), text_ru = COALESCE(text_ru, 'хороший сервис'), text_de = COALESCE(text_de, 'guter Service'), text_tr = COALESCE(text_tr, 'iyi hizmet') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tNMlowSnJZMTlhUVVodVdVWkJUbGxzY0hSVlRVRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Veoma profesionalan i iskusan tim na čelu sa sjajnom dr Milenkom. Bilo je zadovoljstvo obaviti ljekarski pregled u njihovoj klinici. Izuzetno smo zadovoljni njihovom komunikacijom i uslugom u cjelini. Hvala vam.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома професионалан и искусан тим на челу са сјајном др Миленком. Било је задовољство обавити љекарски преглед у њиховој клиници. Изузетно смо задовољни њиховом комуникацијом и услугом у цјелини. Хвала вам.'), text_ru = COALESCE(text_ru, 'Очень профессиональная и опытная команда во главе с замечательной доктором Миленкой. Пройти медосмотр в их клинике было одно удовольствие. Мы очень довольны и общением, и обслуживанием в целом. Спасибо.'), text_de = COALESCE(text_de, 'Ein sehr professionelles und erfahrenes Team unter der Leitung der großartigen Dr. Milenka. Es war eine Freude, die ärztliche Untersuchung in ihrer Klinik machen zu lassen. Wir sind mit der Kommunikation und dem Service insgesamt äußerst zufrieden. Vielen Dank.'), text_tr = COALESCE(text_tr, 'Harika Dr. Milenka\'nın başında olduğu çok profesyonel ve deneyimli bir ekip. Kliniklerinde muayene olmak bir zevkti. İletişimlerinden ve genel olarak hizmetlerinden son derece memnunuz. Teşekkür ederiz.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25KU1dVbFJNV2hvZFZCTk0yZzNSRWRwTTBWUlZsRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Кол-центар нам је помогао око заказивања прегледа преко путног осигурања. Професионална услуга.'), text_en = COALESCE(text_en, 'The call centre helped us book an examination through our travel insurance. Professional service.'), text_ru = COALESCE(text_ru, 'Колл-центр помог нам записаться на приём по туристической страховке. Профессиональный сервис.'), text_de = COALESCE(text_de, 'Das Callcenter hat uns geholfen, über unsere Reiseversicherung einen Untersuchungstermin zu vereinbaren. Professioneller Service.'), text_tr = COALESCE(text_tr, 'Çağrı merkezi, seyahat sigortamız üzerinden muayene randevusu almamıza yardımcı oldu. Profesyonel hizmet.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pCSk9ITlpNVk5aZUUxdmFXZzNhMGhUU0U0elFtYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Veoma dobra klinika. Preporučujem.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома добра клиника. Препоручујем.'), text_en = COALESCE(text_en, 'A very good clinic. I recommend it.'), text_de = COALESCE(text_de, 'Eine sehr gute Klinik. Empfehlenswert.'), text_tr = COALESCE(text_tr, 'Çok iyi bir klinik. Tavsiye ederim.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25sV1FVOTNVblZHTWtaSlUwTkhZVzVOYTFnMWMyYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Fantastična njega.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Фантастична њега.'), text_ru = COALESCE(text_ru, 'Фантастическая забота.'), text_de = COALESCE(text_de, 'Fantastische Betreuung.'), text_tr = COALESCE(text_tr, 'Harika bir bakım.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xOV09XeDZPRlpKVFVoSVgzZFFSalYyYlRCMllXYxAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све похвале, брзо, без посебне процедуре!'), text_en = COALESCE(text_en, 'Full marks — quick and without any red tape!'), text_ru = COALESCE(text_ru, 'Только похвалы: быстро и без лишних формальностей!'), text_de = COALESCE(text_de, 'Großes Lob – schnell und ohne großen Aufwand!'), text_tr = COALESCE(text_tr, 'Tebrikler, hızlı ve gereksiz prosedür olmadan!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT201VVoyUkhhRXN0WTNGRGJEbFBSRXhKT0RSYVJWRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све похвале за љекаре и стручно особље, препорука, љубазни и стручни.'), text_en = COALESCE(text_en, 'Full praise for the doctors and the professional staff — recommended, kind and competent.'), text_ru = COALESCE(text_ru, 'Только похвалы врачам и персоналу: рекомендую, вежливые и профессиональные.'), text_de = COALESCE(text_de, 'Großes Lob an die Ärzte und das Fachpersonal – empfehlenswert, freundlich und kompetent.'), text_tr = COALESCE(text_tr, 'Doktorlara ve uzman personele tebrikler; tavsiye ederim, nazik ve işinin ehli.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pCRFpXWkdRVUkwTlVRMVdEQjVSMjUyZEdGR1NGRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Веома сам задовољна пруженом медицинском услугом, без непотребног чекања. Професионално и стручно.'), text_en = COALESCE(text_en, 'I\'m very satisfied with the medical service I received, with no unnecessary waiting. Professional and competent.'), text_ru = COALESCE(text_ru, 'Я очень довольна оказанной медицинской помощью, без лишнего ожидания. Профессионально и грамотно.'), text_de = COALESCE(text_de, 'Ich bin mit der medizinischen Versorgung sehr zufrieden, ohne unnötige Wartezeit. Professionell und kompetent.'), text_tr = COALESCE(text_tr, 'Aldığım tıbbi hizmetten çok memnunum, gereksiz bekleme olmadı. Profesyonel ve uzman bir hizmet.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tZd056STRkRXhFTjNNM2FFaFhVRzVyYzA1eU5VRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Ефикасни и стручни. Све похвале!'), text_en = COALESCE(text_en, 'Efficient and competent. Full marks!'), text_ru = COALESCE(text_ru, 'Оперативно и профессионально. Только похвалы!'), text_de = COALESCE(text_de, 'Effizient und kompetent. Großes Lob!'), text_tr = COALESCE(text_tr, 'Verimli ve uzmanlar. Tebrikler!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25SSVNIaERkRWh2Wms5cFVYRm1kMnByU0c5dFVuYxAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Sve je bilo u redu. Pomoć je stigla vrlo brzo i pružena je efikasno. Hvala vam puno na konsultaciji i brizi 🙏🏻'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све је било у реду. Помоћ је стигла врло брзо и пружена је ефикасно. Хвала вам пуно на консултацији и бризи 🙏🏻'), text_ru = COALESCE(text_ru, 'Всё было хорошо. Помощь пришла очень быстро и была оказана чётко. Большое спасибо за консультацию и заботу 🙏🏻'), text_de = COALESCE(text_de, 'Alles war bestens. Die Hilfe kam sehr schnell und war effizient. Vielen Dank für die Beratung und die Betreuung 🙏🏻'), text_tr = COALESCE(text_tr, 'Her şey yolundaydı. Yardım çok hızlı geldi ve verimli bir şekilde sağlandı. Konsültasyon ve ilginiz için çok teşekkür ederim 🙏🏻') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pJNGVGVmtPRXd0ZUV0eVNWSlVVRVkyT1VkTFFsRRAB';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Све препоруке за клинику!'), text_en = COALESCE(text_en, 'I fully recommend the clinic!'), text_ru = COALESCE(text_ru, 'Клинику однозначно рекомендую!'), text_de = COALESCE(text_de, 'Die Klinik ist absolut zu empfehlen!'), text_tr = COALESCE(text_tr, 'Kliniği gönül rahatlığıyla tavsiye ederim!') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/Ci9DQUlRQUNvZENodHljRjlvT25KWFZsWjBVMm81VUdadFJGcG5PRmh6Ym1KbFQxRRAB';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Pregled u hotelu zakazan je vrlo brzo. Jezička barijera nije bila problem — koristili smo prevodilac na telefonu. Ljekar je veoma temeljno pregledao dijete i dao preporuke.'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Преглед у хотелу заказан је врло брзо. Језичка баријера није била проблем — користили смо преводилац на телефону. Љекар је веома темељно прегледао дијете и дао препоруке.'), text_en = COALESCE(text_en, 'A hotel visit was arranged very quickly. The language barrier wasn\'t a problem — we used a translator app on the phone. The doctor examined our child very thoroughly and gave recommendations.'), text_ru = COALESCE(text_ru, 'Визит врача в отель организовали очень быстро. Языковой барьер не стал проблемой — мы пользовались переводчиком в телефоне. Врач очень внимательно осмотрел ребёнка и дал рекомендации.'), text_de = COALESCE(text_de, 'Der Arztbesuch im Hotel wurde sehr schnell vereinbart. Die Sprachbarriere war kein Problem – wir haben eine Übersetzer-App auf dem Handy benutzt. Der Arzt hat unser Kind sehr gründlich untersucht und Empfehlungen gegeben.'), text_tr = COALESCE(text_tr, 'Otele doktor ziyareti çok hızlı ayarlandı. Dil engeli sorun olmadı, telefondaki çeviri uygulamasını kullandık. Doktor çocuğu çok dikkatli muayene etti ve önerilerde bulundu.') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/ChZDSUhNMG9nS0VJQ0FnSUN6Ml9xNkRREAE';
UPDATE reviews SET text_sr = COALESCE(text_sr, 'Najbolja usluga u Crnoj Gori'), text_sr_cyrl = COALESCE(text_sr_cyrl, 'Најбоља услуга у Црној Гори'), text_ru = COALESCE(text_ru, 'Лучший сервис в Черногории'), text_de = COALESCE(text_de, 'Der beste Service in Montenegro'), text_tr = COALESCE(text_tr, 'Karadağ\'daki en iyi hizmet') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/ChZDSUhNMG9nS0VJQ0FnSUN6dmNhcmNnEAE';
UPDATE reviews SET text_sr_cyrl = COALESCE(text_sr_cyrl, 'Љубазна докторка, као и оператер. Све похвале'), text_en = COALESCE(text_en, 'The doctor was kind, and so was the operator. Full marks'), text_ru = COALESCE(text_ru, 'Вежливые и врач, и оператор. Только похвалы'), text_de = COALESCE(text_de, 'Die Ärztin war freundlich, ebenso der Mitarbeiter am Telefon. Großes Lob'), text_tr = COALESCE(text_tr, 'Doktor hanım da operatör de çok nazikti. Tebrikler') WHERE provider = 'google_maps' AND provider_review_id = 'places/ChIJv-4KSAB0ThMRg6uQSFU1nvM/reviews/ChZDSUhNMG9nS0VJQ0FnSUN6dVlYc1FnEAE';
